    // Workspace-linked package exports can drift from Vite's prebundle cache.
    // Exclude to always load the current dist entry directly.
    exclude: ['@illog/ui']
  },
  build: {
    outDir: path.resolve(__dirname, '.vite/renderer/main_window'),
    emptyOutDir: true,
    sourcemap: true,
    target: 'es2022'
