import { useEffect, useState } from 'react'

export type Platform =
  | 'mac-arm'
  | 'mac-intel'
  | 'mac'
  | 'windows'
  | 'linux'
  | 'ios'
  | 'android'
  | 'unknown'

async function detectPlatform(): Promise<Platform> {
  const ua = navigator.userAgent.toLowerCase()

  if (/android/.test(ua)) return 'android'
  if (/iphone|ipad|ipod/.test(ua)) return 'ios'

  if (/macintosh|mac os/.test(ua)) {
    try {
      if ('userAgentData' in navigator) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const uaData = (navigator as any).userAgentData
        if (uaData && typeof uaData.getHighEntropyValues === 'function') {
          const highEntropyValues = await uaData.getHighEntropyValues(['architecture'])
          if (highEntropyValues.architecture) {
            const arch = highEntropyValues.architecture.toLowerCase()
            if (arch === 'arm' || arch === 'arm64') return 'mac-arm'
            if (arch === 'x86' || arch === 'x86_64') return 'mac-intel'
          }
        }
      }

      const canvas = document.createElement('canvas')
      const gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl')
      if (gl) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const debugInfo = (gl as any).getExtension('WEBGL_debug_renderer_info')
        if (debugInfo) {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const renderer = (gl as any).getParameter(debugInfo.UNMASKED_RENDERER_WEBGL)
          if (renderer && /apple/i.test(renderer)) return 'mac-arm'
          if (renderer && /intel/i.test(renderer)) return 'mac-intel'
        }
      }
    } catch (error) {
      console.warn('[PlatformDetect] Error detecting Mac architecture:', error)
    }
    return 'mac'
  }

  if (/windows/.test(ua)) return 'windows'
  if (/linux/.test(ua)) return 'linux'

  return 'unknown'
}

export function usePlatform() {
  const [platform, setPlatform] = useState<Platform | null>(null)

  useEffect(() => {
    detectPlatform().then(setPlatform)
  }, [])

  const isMobile = platform === 'ios' || platform === 'android'
  const isMac = platform === 'mac' || platform === 'mac-arm' || platform === 'mac-intel'

  return { platform, isMobile, isMac }
}

export const normalizeName = (name: string) => {
  return name.trim().replace(/\s+/g, ' ')
}

export type ErrorCode =
  | 'DB_ERROR'
  | 'NOT_FOUND'
  | 'VALIDATION_ERROR'
  | 'AI_ERROR'
  | 'FEATURE_DISABLED'
  | 'UNKNOWN_ERROR'

const ERROR_MESSAGES: Record<ErrorCode, string> = {
  DB_ERROR: 'Something went wrong while saving. Please try again.',
  NOT_FOUND: 'The requested item could not be found.',
  VALIDATION_ERROR: 'Invalid input. Please check and try again.',
  AI_ERROR: 'AI reflection is temporarily unavailable. Please try again later.',
  FEATURE_DISABLED: 'This feature requires a Pro plan.',
  UNKNOWN_ERROR: 'An unexpected error occurred. Please try again.'
}

export class AppError extends Error {
  constructor(
    message: string,
    public code: ErrorCode,
    public originalError?: unknown
  ) {
    super(message)
    this.name = 'AppError'
  }
}

export interface SerializedError {
  __appError: true
  message: string
  code: ErrorCode
}

export const APP_ERROR_DELIMITER = '__APP_ERROR__'

export function classifyError(error: unknown): ErrorCode {
  if (error instanceof AppError) return error.code

  if (error instanceof Error) {
    const msg = error.message.toLowerCase()

    if (msg.includes('sqlite') || msg.includes('database') || msg.includes('constraint')) {
      return 'DB_ERROR'
    }
    if (msg.includes('not found') || msg.includes('no result')) {
      return 'NOT_FOUND'
    }
    if (msg.includes('invalid') || msg.includes('required') || msg.includes('validation')) {
      return 'VALIDATION_ERROR'
    }
    if (msg.includes('gemini') || msg.includes('openai') || msg.includes('ai reflection')) {
      return 'AI_ERROR'
    }
    if (msg.includes('pro plan') || msg.includes('feature is not available')) {
      return 'FEATURE_DISABLED'
    }
  }

  return 'UNKNOWN_ERROR'
}

export function serializeError(error: unknown): SerializedError {
  const code = classifyError(error)
  const message = error instanceof Error ? error.message : String(error)

  return { __appError: true, message, code }
}

export function deserializeError(error: unknown): AppError {
  // Electron wraps IPC errors in an Error with the original message
  if (error instanceof Error) {
    // Extract serialized error JSON using delimiter (safe for messages containing any characters)
    const idx = error.message.indexOf(APP_ERROR_DELIMITER)
    if (idx !== -1) {
      try {
        const jsonStr = error.message.slice(idx + APP_ERROR_DELIMITER.length)
        const parsed = JSON.parse(jsonStr) as SerializedError
        if (parsed.__appError) {
          return new AppError(parsed.message, parsed.code)
        }
      } catch {
        // Not our serialized error, fall through
      }
    }

    const code = classifyError(error)
    return new AppError(error.message, code, error)
  }

  return new AppError(String(error), 'UNKNOWN_ERROR', error)
}

export function getUserMessage(error: unknown): string {
  if (error instanceof AppError) {
    return ERROR_MESSAGES[error.code]
  }

  if (error instanceof Error) {
    const code = classifyError(error)
    return ERROR_MESSAGES[code]
  }

  return ERROR_MESSAGES.UNKNOWN_ERROR
}

import { contextBridge, ipcRenderer } from 'electron'
import type {
  TaskFilterParams,
  UpdateTaskRequest,
  CreateTagRequest,
  UpdateTagRequest,
  CreateProjectRequest,
  UpdateProjectRequest,
  UpdateWeeklyReflectionRequest,
  CreateTaskTypeRequest,
  UpdateTaskTypeRequest,
  CreateTaskSubtypeRequest,
  UpdateTaskSubtypeRequest,
  UpdateCrashReportSettingsRequest,
  FeatureId
} from '../shared/types'

const APP_ERROR_DELIMITER = '__APP_ERROR__'

async function safeInvoke(channel: string, ...args: unknown[]) {
  try {
    return await ipcRenderer.invoke(channel, ...args)
  } catch (error) {
    if (error instanceof Error) {
      const idx = error.message.indexOf(APP_ERROR_DELIMITER)
      if (idx !== -1) {
        try {
          const parsed = JSON.parse(error.message.slice(idx + APP_ERROR_DELIMITER.length))
          if (parsed?.__appError) {
            const appError = new Error(parsed.message) as Error & { code: string }
            appError.code = parsed.code
            appError.name = 'AppError'
            throw appError
          }
        } catch (parseError) {
          if (parseError instanceof Error && parseError.name === 'AppError') throw parseError
        }
      }
    }
    throw error
  }
}

