export function parseColor(value: string) {
  // Match: #RRGGBB or #RGB
  const hexMatch = value.match(/^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i)
  if (hexMatch) {
    return {
      r: parseInt(hexMatch[1], 16) / 255,
      g: parseInt(hexMatch[2], 16) / 255,
      b: parseInt(hexMatch[3], 16) / 255,
      a: 1
    }
  }

  const hex3 = value.match(/^#([0-9a-f])([0-9a-f])([0-9a-f])$/i)
  if (hex3) {
    return {
      r: parseInt(hex3[1] + hex3[1], 16) / 255,
      g: parseInt(hex3[2] + hex3[2], 16) / 255,
      b: parseInt(hex3[3] + hex3[3], 16) / 255,
      a: 1
    }
  }

  const rgbaMatch = value.match(/^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d*\.?\d+)\s*\)$/)
  if (rgbaMatch) {
    return {
      r: parseInt(rgbaMatch[1], 10) / 255,
      g: parseInt(rgbaMatch[2], 10) / 255,
      b: parseInt(rgbaMatch[3], 10) / 255,
      a: rgbaMatch[4] !== undefined ? parseFloat(rgbaMatch[4]) : 1
    }
  }

  return null
}

export function generateColorSvg(hexColor: string): string {
  const svg = `<svg width="16" height="16" xmlns="http://www.w3.org/2000/svg"><rect width="16" height="16" rx="3" fill="${hexColor}" stroke="#888" stroke-width="0.5"/></svg>`
  return `data:image/svg+xml;base64,${Buffer.from(svg).toString('base64')}`
}

import { existsSync, readFileSync } from 'fs'
import { join } from 'path'

export type ColorToken = {
  type: 'color'
  camelName: string
  cssVar: string
  lightValue: string
  darkValue: string
}

type SizeCategory = 'space' | 'radius' | 'icon' | 'depth' | 'blur' | 'stroke'

export type SizeToken = {
  type: 'size'
  key: string
  value: number
  category: SizeCategory
}

export type ShadowToken = {
  type: 'shadow'
  key: string
  css: string
}

export type Token = ColorToken | SizeToken | ShadowToken

// Pre-computed shadow CSS values (from dropShadow.ts × depth/blur/black tokens).
// These rarely change so we hardcode rather than parsing TypeScript at runtime.
const SHADOW_TOKENS: Record<string, string> = {
  '100': '0px 1px 4px 0px rgba(0,0,0,0.05)',
  '200': '0px 1px 4px 0px rgba(0,0,0,0.05), 0px 1px 4px 0px rgba(0,0,0,0.05)',
  '300': '0px 4px 4px -1px rgba(0,0,0,0.1), 0px 4px 4px -1px rgba(0,0,0,0.05)',
  '400': '0px 16px 32px -4px rgba(0,0,0,0.1), 0px 4px 4px -4px rgba(0,0,0,0.05)',
  '500': '0px 16px 16px -8px rgba(0,0,0,0.1), 0px 4px 4px -4px rgba(0,0,0,0.05)',
  '600': '0px 16px 32px -8px rgba(0,0,0,0.2)'
}

export class TokenRegistry {
  private lightColor = new Map<string, string>() // { "--background-default-default": "#ffffff", ... }
  private darkColor = new Map<string, string>() // { "--background-default-default": "#1e1e1e", ... }
  private camelToCssVar = new Map<string, string>() // { "backgroundDefaultDefault": "--background-default-default", ... }
  private colorTokens = new Map<string, ColorToken>() // { "backgroundDefaultDefault": { type: 'color', camelName: 'backgroundDefaultDefault', cssVar: '--background-default-default', lightValue: '#ffffff', darkValue: '#1e1e1e' }, ... }
  private sizeTokens = new Map<string, SizeToken>() // { "--space-100": { type: 'size', key: '100', value: 4, category: 'space' }, ... }
  private shadowTokens = new Map<string, ShadowToken>() // { "100": { type: 'shadow', key: '100', css: '0px 1px 4px 0px rgba(0,0,0,0.05)' }, ... }

  private workspaceRoot: string

  constructor(workspaceRoot: string) {
    this.workspaceRoot = workspaceRoot
  }

  load(): void {
    this.loadThemesCSS()
    this.loadGeneratedColors()
    this.buildColorTokens()
    this.loadSizeTokens()
    this.loadShadowTokens()
  }

  private loadShadowTokens(): void {
    this.shadowTokens.clear()
    for (const [key, css] of Object.entries(SHADOW_TOKENS)) {
      this.shadowTokens.set(key, { type: 'shadow', key, css })
    }
  }

  private loadThemesCSS(): void {
    const cssPath = join(this.workspaceRoot, 'packages/themes/dist/themes.css')

    if (!existsSync(cssPath)) {
      return
    }
    const css = readFileSync(cssPath, 'utf-8')

    const blocks = this.parseCssBlocks(css)

    for (const block of blocks) {
      const isDark = block.selector.includes('.theme-dark')
      const varRegex = /--([\w-]+)\s*:\s*([^;]+);/g
      let match: RegExpExecArray | null

      while ((match = varRegex.exec(block.body))) {
        const varName = `--${match[1]}` // e.g. "--background-default-default"
        const value = match[2].trim() // e.g. "#ffffff"

        if (isDark) {
          this.darkColor.set(varName, value)
        } else {
          this.lightColor.set(varName, value)
        }
      }
    }
  }

  /**
   * @css :root {
   * --background-default-default: #ffffff; ...}
   *
   * @return output: [
   *  { selector: ':root', body: '--background-default-default: #ffffff; ...' },
   *  { selector: ':root .theme-dark', body: '--background-default-default: #000000; ...' },
   *   ...
   * ]
   */
  private parseCssBlocks(css: string) {
    const blocks: Array<{ selector: string; body: string }> = []
    // Match blocks like: :root { ... } and :root .theme-dark { ... }
    const regex = /([^{]+)\{([^}]+)\}/g
    let match: RegExpExecArray | null

    while ((match = regex.exec(css))) {
      blocks.push({
        selector: match[1].trim(),
        body: match[2].trim()
      })
    }

    return blocks
  }

  private loadGeneratedColors(): void {
    const genPath = join(this.workspaceRoot, 'packages/ui/src/core/tokens/generatedColors.ts')
    if (!existsSync(genPath)) {
      return
    }
    const content = readFileSync(genPath, 'utf-8')

    // Match: backgroundTagPurple: 'var(--background-tag-purple)',
    const regex = /(\w+)\s*:\s*'var\((--[\w-]+)\)'/g
    let match: RegExpExecArray | null

    while ((match = regex.exec(content))) {
      this.camelToCssVar.set(match[1], match[2])
    }
  }

  private buildColorTokens(): void {
    for (const [camel, cssVar] of this.camelToCssVar) {
      const lightValue = this.lightColor.get(cssVar) ?? ''
      const darkValue = this.darkColor.get(cssVar) ?? ''

      this.colorTokens.set(camel, {
        type: 'color',
        camelName: camel, // e.g. "backgroundDefaultDefault"
        cssVar, // e.g. "--background-default-default"
        lightValue, // e.g. "#ffffff"
        darkValue // e.g. "#1e1e1e"
      })
    }
  }

  private loadSizeTokens(): void {
    const sizeCategories: Partial<Record<string, SizeCategory>> = {
      space: 'space',
      radius: 'radius',
      icon: 'icon',
      depth: 'depth',
      blur: 'blur',
      stroke: 'stroke'
    }

    // lightColor 맵을 순회해서 사이즈 관련 CSS 변수만 추출
    for (const [cssVar, value] of this.lightColor) {
      const varName = cssVar.slice(2) // "--space-400" → "space-400"
      const dashIdx = varName.indexOf('-') // 첫 번째 대시만 사용
      if (dashIdx === -1) continue

      const prefix = varName.slice(0, dashIdx) // "space"
      const category = sizeCategories[prefix]
      if (!category) continue

      const key = varName.slice(dashIdx + 1) // "400" or "negative100"
      const numVal = parseFloat(value)
      if (isNaN(numVal)) continue

      // getSizeToken(category, key)와 일치하는 복합키로 저장
      this.sizeTokens.set(`${category}.${key}`, {
        type: 'size',
        key,
        value: numVal,
        category
      })
    }
  }

  getColorToken(camelName: string): ColorToken | undefined {
    return this.colorTokens.get(camelName)
  }

  getSizeToken(category: string, key: string): SizeToken | undefined {
    return this.sizeTokens.get(`${category}.${key}`)
  }

  getAllColorTokens(): ColorToken[] {
    return Array.from(this.colorTokens.values())
  }

  getAllSizeTokens(): SizeToken[] {
    return Array.from(this.sizeTokens.values())
  }

  getShadowToken(key: string): ShadowToken | undefined {
    return this.shadowTokens.get(key)
  }

  getAllShadowTokens(): ShadowToken[] {
    return Array.from(this.shadowTokens.values())
  }

  getColorByCssVar(cssVar: string, theme: 'light' | 'dark' = 'light'): string | undefined {
    return theme === 'dark' ? this.darkColor.get(cssVar) : this.lightColor.get(cssVar)
  }
}

import {
  Hover,
  HoverProvider,
  MarkdownString,
  Position,
  ProviderResult,
  Range,
  TextDocument
} from 'vscode'
import { TokenRegistry } from '../registry/TokenRegistry'
import { generateColorSvg } from '../utils/color'

export class TokenHoverProvider implements HoverProvider {
  constructor(private registry: TokenRegistry) {}

  provideHover(document: TextDocument, position: Position): ProviderResult<Hover> {
    const line = document.lineAt(position.line).text

    // 1. import 스타일: backgroundColors.xxx, textColors.xxx 등 (.css.ts 파일)
    const colorResult = this.matchColorToken(line, position)
    if (colorResult) return colorResult

    // 2. JSX prop 컬러: bg="backgroundBrandDefault", color="textDefault" 등
    const jsxColorResult = this.matchJsxColorProp(line, position)
    if (jsxColorResult) return jsxColorResult

    // 3. JSX prop 라디우스: rounded="200"
    const jsxRadiusResult = this.matchJsxRadiusProp(line, position)
    if (jsxRadiusResult) return jsxRadiusResult

    // 4. JSX prop 섀도우: shadow="100"
    const jsxShadowResult = this.matchJsxShadowProp(line, position)
    if (jsxShadowResult) return jsxShadowResult

    // 5. 직접 토큰 접근: tokens.size.space['400'], tokens.size.radius[200]
    const sizeResult = this.matchSizeToken(line, position)
    if (sizeResult) return sizeResult

    // 6. sprinkles 오브젝트 스타일: gap: '400', p: '200' 등 + JSX gap="400"
    const sprinklesResult = this.matchSprinklesSpace(line, position)
    if (sprinklesResult) return sprinklesResult

    return null
  }

  private matchJsxColorProp(line: string, position: Position): Hover | null {
    const regex =
      /(?:bg|backgroundColor|color|borderColor|borderTopColor|borderRightColor|borderBottomColor|borderLeftColor)\s*=\s*["'](\w+)["']/g
    let match: RegExpExecArray | null
    while ((match = regex.exec(line))) {
      const start = match.index
      const end = start + match[0].length
      if (position.character < start || position.character > end) continue
      const token = this.registry.getColorToken(match[1])
      if (!token) return null
      return new Hover(
        this.buildColorHoverContent(
          token.camelName,
          token.cssVar,
          token.lightValue,
          token.darkValue
        ),
        new Range(position.line, start, position.line, end)
      )
    }
    return null
  }

  private matchJsxRadiusProp(line: string, position: Position): Hover | null {
    const regex = /(?:rounded|borderRadius)\s*=\s*["'](\w+)["']/g
    let match: RegExpExecArray | null
    while ((match = regex.exec(line))) {
      const start = match.index
      const end = start + match[0].length
      if (position.character < start || position.character > end) continue
      const token = this.registry.getSizeToken('radius', match[1])
      if (!token) return null
      return new Hover(
        this.buildSizeHoverContent('radius', match[1], token.value),
        new Range(position.line, start, position.line, end)
      )
    }
    return null
  }

  private matchJsxShadowProp(line: string, position: Position): Hover | null {
    const regex = /(?:shadow|boxShadow)\s*=\s*["'](\w+)["']/g
    let match: RegExpExecArray | null
    while ((match = regex.exec(line))) {
      const start = match.index
      const end = start + match[0].length
      if (position.character < start || position.character > end) continue
      const shadowToken = this.registry.getShadowToken(match[1])
      if (!shadowToken) return null
      const md = new MarkdownString('', true)
      md.isTrusted = true
      md.appendMarkdown(`**shadow.${match[1]}**\n\n---\n\n`)
      md.appendMarkdown(`\`\`\`\n${shadowToken.css}\n\`\`\``)
      return new Hover(md, new Range(position.line, start, position.line, end))
    }
    return null
  }

  private matchColorToken(line: string, position: Position): Hover | null {
    // Match: backgroundColors.xxx, textColors.xxx, borderColors.xxx, iconColors.xxx
    const regex = /(?:backgroundColors|textColors|borderColors|iconColors)\.(\w+)/g
    let match: RegExpExecArray | null

    while ((match = regex.exec(line))) {
      const start = match.index
      const end = start + match[0].length

      if (position.character >= start && position.character <= end) {
        const camelName = match[1]
        const token = this.registry.getColorToken(camelName)
        if (!token) return null

        return new Hover(
          this.buildColorHoverContent(
            token.camelName,
            token.cssVar,
            token.lightValue,
            token.darkValue
          ),
          new Range(position.line, start, position.line, end)
        )
      }
    }

    return null
  }

  private matchSizeToken(line: string, position: Position): Hover | null {
    // Match: tokens.size.space['400'] or tokens.size.space["400"] or tokens.size.radius[200]
    const regex = /tokens\.size\.(space|radius|icon|depth|blur|stroke)\[['"]?(\w+)['"]?\]/g
    let match: RegExpExecArray | null

    while ((match = regex.exec(line)) !== null) {
      const start = match.index
      const end = start + match[0].length

      if (position.character >= start && position.character <= end) {
        const category = match[1]
        const key = match[2]
        const token = this.registry.getSizeToken(category, key)
        if (!token) return null

        return new Hover(
          this.buildSizeHoverContent(category, key, token.value),
          new Range(position.line, start, position.line, end)
        )
      }
    }

    return null
  }

  private matchSprinklesSpace(line: string, position: Position): Hover | null {
    // Match sprinkles-style: gap: '400', m: '200', p: '100', padding: '600' etc.
    // Only match known space token keys
    const regex =
      /(?:gap|margin|padding|m|mt|mr|mb|ml|mx|my|p|pt|pr|pb|pl|px|py|rowGap|columnGap|gridGap)\s*[:=]\s*['"](\d+|negative\d+)['"]/g
    let match: RegExpExecArray | null

    while ((match = regex.exec(line)) !== null) {
      // Focus on the value part (the quoted number)
      const valueStr = match[1]
      const valueStart = match.index + match[0].lastIndexOf(valueStr)
      const valueEnd = valueStart + valueStr.length

      if (position.character >= valueStart && position.character <= valueEnd) {
        const token = this.registry.getSizeToken('space', valueStr)
        if (!token) return null

        return new Hover(
          this.buildSizeHoverContent('space', valueStr, token.value),
          new Range(position.line, valueStart, position.line, valueEnd)
        )
      }
    }

    return null
  }

  private buildColorHoverContent(
    name: string,
    cssVar: string,
    lightValue: string,
    darkValue: string
  ): MarkdownString {
    const md = new MarkdownString('', true) // 빈 마크다운 + 테마아이콘 지원
    md.isTrusted = true // 이미지/svg 신뢰
    md.supportHtml = true // svg 렌더링 허용

    const lightSvg = generateColorSvg(lightValue)
    const darkSvg = generateColorSvg(darkValue)

    md.appendMarkdown(`**${name}**\n\n`)
    md.appendMarkdown(`---\n\n`)
    md.appendMarkdown(`![light](${lightSvg})&nbsp; Light: \`${lightValue}\`\n\n`)
    md.appendMarkdown(`![dark](${darkSvg})&nbsp; Dark: \`${darkValue}\`\n\n`)
    md.appendMarkdown(`CSS: \`var(${cssVar})\``)

    return md
  }

  private buildSizeHoverContent(category: string, key: string, value: number): MarkdownString {
    const md = new MarkdownString('', true)
    md.isTrusted = true

    const unit = category === 'depth' ? '' : 'px'
    md.appendMarkdown(`**${category}.${key}**\n\n`)
    md.appendMarkdown(`---\n\n`)
    md.appendMarkdown(`Value: \`${value}${unit}\``)

    if (category === 'space' && value > 0) {
      md.appendMarkdown(`  ·  \`${value / 16}rem\``)
    }

    return md
  }
}

import {
  CompletionItem,
  CompletionItemKind,
  CompletionItemProvider,
  MarkdownString,
  Position,
  ProviderResult,
  Range,
  TextDocument
} from 'vscode'
import { TokenRegistry, ColorToken } from '../registry/TokenRegistry'
import { generateColorSvg, parseColor } from '../utils/color'

const SPACE_PROPS = new Set([
  'gap',
  'gridGap',
  'columnGap',
  'rowGap',
  'margin',
  'marginTop',
  'marginRight',
  'marginBottom',
  'marginLeft',
  'padding',
  'paddingTop',
  'paddingRight',
  'paddingBottom',
  'paddingLeft',
  'm',
  'mt',
  'mr',
  'mb',
  'ml',
  'mx',
  'my',
  'p',
  'pt',
  'pr',
  'pb',
  'pl',
  'px',
  'py'
])

const BG_COLOR_PROPS = new Set(['bg', 'backgroundColor'])
const TEXT_COLOR_PROPS = new Set(['color'])
const BORDER_COLOR_PROPS = new Set([
  'borderColor',
  'borderTopColor',
  'borderRightColor',
  'borderBottomColor',
  'borderLeftColor'
])
const RADIUS_PROPS = new Set(['rounded', 'borderRadius'])
const SHADOW_PROPS = new Set(['shadow', 'boxShadow'])

type PropCategory = 'space' | 'bgColor' | 'textColor' | 'borderColor' | 'radius' | 'shadow'

function getPropCategory(propName: string): PropCategory | null {
  if (SPACE_PROPS.has(propName)) return 'space'
  if (BG_COLOR_PROPS.has(propName)) return 'bgColor'
  if (TEXT_COLOR_PROPS.has(propName)) return 'textColor'
  if (BORDER_COLOR_PROPS.has(propName)) return 'borderColor'
  if (RADIUS_PROPS.has(propName)) return 'radius'
  if (SHADOW_PROPS.has(propName)) return 'shadow'
  return null
}

interface PropContext {
  propName: string
  typed: string
}

/**
 * @lineUptoCursor 현재 커서까지의 한 줄 문자열 (예: `<Box p="1` 이면 `lineUptoCursor`는 `<Box p="1`이 됨)
 *
 */
function detectPropContext(lineUptoCursor: string): PropContext | null {
  // Match: 연속된 단어 문자들을 캡처해서 그 뒤에 = 기호가 있고 값이 시작되는 패턴(따옴표가 아니고 이 패턴이 문자열 끝에서 일치해야 함)
  const match = lineUptoCursor.match(/(\w+)=(?:["']|[{]["'])([^"']*)$/)
  if (!match) return null
  return { propName: match[1], typed: match[2] } // propName: p, typed: 1
}

export class SprinklesCompletionProvider implements CompletionItemProvider {
  constructor(private registry: TokenRegistry) {}

  provideCompletionItems(
    document: TextDocument,
    position: Position
  ): ProviderResult<CompletionItem[]> {
    const lineUptoCursor = document.getText(
      new Range(position.line, 0, position.line, position.character)
    )

    const ctx = detectPropContext(lineUptoCursor)
    if (!ctx) return null

    const category = getPropCategory(ctx.propName)
    if (!category) return null

    switch (category) {
      case 'space':
        return this.spaceCompletions()
      case 'radius':
        return this.radiusCompletions()
      case 'shadow':
        return this.shadowCompletions()
      case 'bgColor':
        return this.colorCompletions('background')
      case 'textColor':
        return this.colorCompletions('text')
      case 'borderColor':
        return this.colorCompletions('border')
    }
  }

  private spaceCompletions(): CompletionItem[] {
    return this.registry
      .getAllSizeTokens()
      .filter((t) => t.category === 'space')
      .map((t) => {
        const item = new CompletionItem(
          {
            label: t.key, // e.g. "100"
            detail: `  ${t.value}px` // e.g. "  4px" (2 spaces for alignment)
          },
          CompletionItemKind.Unit
        )
        item.insertText = t.key
        item.detail = `${t.value}px`
        if (t.value > 0) {
          item.documentation = new MarkdownString(
            `**space.${t.key}** → \`${t.value}px\` · \`${t.value / 16}rem\`` // e.g. "space.100 → `4px` · `0.25rem`"
          )
        }

        item.sortText =
          t.value >= 0
            ? `0_${String(t.value).padStart(6, '0')}`
            : `1_${String(-t.value).padStart(6, '0')}`
        return item
      })
  }

  private radiusCompletions(): CompletionItem[] {
    return this.registry
      .getAllSizeTokens()
      .filter((t) => t.category === 'radius')
      .map((t) => {
        const item = new CompletionItem(
          { label: t.key, detail: `  ${t.value === 9999 ? '∞' : t.value + 'px'}` }, // e.g. "100" with detail "  4px", "9999" with detail "  ∞"
          CompletionItemKind.Unit
        )
        item.insertText = t.key
        item.documentation = new MarkdownString(`**radius.${t.key}** → \`${t.value}px\``) // e.g. "radius.100 → `4px`"
        return item
      })
  }

  private shadowCompletions(): CompletionItem[] {
    return this.registry.getAllShadowTokens().map((t) => {
      const item = new CompletionItem(
        { label: t.key, detail: `  shadow-${t.key}` }, // e.g. "100" with detail "  shadow-100"
        CompletionItemKind.Unit
      )
      item.insertText = t.key
      item.documentation = new MarkdownString(`**shadow.${t.key}**\n\n\`\`\`\n${t.css}\n\`\`\``)
      item.sortText = t.key.padStart(4, '0')
      return item
    })
  }

  private colorCompletions(prefix: 'background' | 'text' | 'border' | 'icon'): CompletionItem[] {
    return this.registry
      .getAllColorTokens()
      .filter((t) => t.camelName.toLowerCase().startsWith(prefix))
      .map((t) => this.colorItem(t))
  }

  private colorItem(token: ColorToken): CompletionItem {
    const { camelName, lightValue, darkValue, cssVar } = token

    const item = new CompletionItem(
      { label: camelName, detail: `  ${lightValue}` },
      CompletionItemKind.Color
    )
    item.insertText = camelName
    item.filterText = camelName
    item.sortText = camelName

    const md = new MarkdownString('', true)
    md.isTrusted = true
    md.supportHtml = true

    const lightSvg = generateColorSvg(lightValue)
    const darkSvg = generateColorSvg(darkValue)

    md.appendMarkdown(`**${camelName}**\n\n`)
    md.appendMarkdown(`![light](${lightSvg}) Light: \`${lightValue}\`\n\n`)
    if (darkValue !== lightValue) {
      md.appendMarkdown(`![dark](${darkSvg}) Dark:  \`${darkValue}\`\n\n`)
    }
    md.appendMarkdown(`CSS: \`var(${cssVar})\``)
    item.documentation = md

    // 컬러 사각형 박스 보이게 하기
    const parsed = parseColor(lightValue)
    if (parsed) {
      // TODO: 일부 테마에서 지원되지 않을 수 있으므로 나중에 발견하면 그때 추가 수정 필요
    }

    return item
  }
}

import {
  Color,
  ColorInformation,
  ColorPresentation,
  DocumentColorProvider,
  ProviderResult,
  Range,
  TextDocument
} from 'vscode'
import { TokenRegistry } from '../registry/TokenRegistry'
import { parseColor } from '../utils/color'

export class ColorDecorationProvider implements DocumentColorProvider {
  constructor(private registry: TokenRegistry) {}

  provideDocumentColors(document: TextDocument): ProviderResult<ColorInformation[]> {
    const colors: ColorInformation[] = []
    const text = document.getText()

    // Match: backgroundColors.xxx, textColors.xxx, borderColors.xxx, iconColors.xxx
    const regex = /(?:backgroundColors|textColors|borderColors|iconColors)\.(\w+)/g
    let match
    while ((match = regex.exec(text)) !== null) {
      const tokenName = match[1]

      const token = this.registry.getColorToken(tokenName)
      if (!token || !token.lightValue) {
        continue
      }

      const parsed = parseColor(token.lightValue)
      if (!parsed) continue

      const startPos = document.positionAt(match.index)
      const endPos = document.positionAt(match.index + match[0].length)
      const range = new Range(startPos, endPos)

      colors.push(new ColorInformation(range, new Color(parsed.r, parsed.g, parsed.b, parsed.a)))
    }

    return colors
  }

  provideColorPresentations(
    color: Color,
    context: { readonly document: TextDocument; readonly range: Range }
  ): ProviderResult<ColorPresentation[]> {
    const originalText = context.document.getText(context.range)
    return [new ColorPresentation(originalText)]
  }
}

