import { sprinkles, Sprinkles } from '../core/sprinkles.css'

export function omit<T extends Record<string, unknown>, K extends keyof T>(
  obj: T,
  keys: K[]
): Omit<T, K> {
  const result = { ...obj }
  keys.forEach((key) => delete result[key])
  return result
}

export function extractSprinkleProps<T extends Record<string, unknown>>(
  props: T
): [Partial<Sprinkles>, Omit<T, keyof Sprinkles>] {
  const sprinkleKeys = new Set<keyof Sprinkles>(sprinkles.properties)
  const sprinkleProps: Partial<Sprinkles> = {}
  const restProps: Partial<T> = {}

  for (const key in props) {
    const typedKey = key as keyof T
    if (sprinkleKeys.has(typedKey as keyof Sprinkles)) {
      type K = Extract<typeof typedKey, keyof Sprinkles>
      sprinkleProps[typedKey as K] = props[typedKey] as Sprinkles[K]
    } else {
      restProps[typedKey] = props[typedKey]
    }
  }

  return [sprinkleProps, restProps as Omit<T, keyof Sprinkles>]
}

type Path<T> = T extends object
  ? {
      [K in keyof T & string]: T[K] extends object ? `${K}` | `${K}.${Path<T[K]>}` : `${K}`
    }[keyof T & string]
  : never

type PathValue<T, P extends string> = P extends `${infer K}.${infer Rest}`
  ? K extends keyof T
    ? PathValue<T[K], Rest>
    : never
  : P extends keyof T
    ? T[P]
    : never

export function getKeyFromPath<T extends object, P extends Path<T>>(
  path: P,
  obj: T
): PathValue<T, P> | undefined {
  return path.split('.').reduce<unknown>((acc, key) => {
    if (typeof acc === 'object' && acc !== null && key in acc) {
      return (acc as Record<string, unknown>)[key]
    }
    return undefined
  }, obj) as PathValue<T, P> | undefined
}

export type SelectorColor = 'blue' | 'gray' | 'green' | 'purple' | 'red' | 'yellow'

const SELECTOR_COLORS: SelectorColor[] = ['blue', 'gray', 'green', 'purple', 'red', 'yellow']

export const pickRandomColor = (): SelectorColor => {
  return SELECTOR_COLORS[Math.floor(Math.random() * SELECTOR_COLORS.length)]
}

export type AsProp<T extends React.ElementType> = {
  as?: T
}

export type PropsToOmit<T extends React.ElementType, P> = keyof (AsProp<T> & P)

export type NestedKeys<T, P extends string = ''> = {
  [K in keyof T]: T[K] extends string
    ? `${P}${Extract<K, string>}`
    : NestedKeys<T[K], `${P}${Extract<K, string>}.`>
}[keyof T]

import { CSSProperties } from '@vanilla-extract/css'

const properties = [
  'width',
  'height',
  'minWidth',
  'minHeight',
  'maxWidth',
  'maxHeight',
  'margin',
  'marginTop',
  'marginRight',
  'marginBottom',
  'marginLeft',
  'padding',
  'paddingTop',
  'paddingRight',
  'paddingBottom',
  'paddingLeft',
  'top',
  'right',
  'bottom',
  'left',
  'inset',
  'transform',
  'translate',
  'scale',
  'rotate',
  'opacity',
  'cursor',
  'transition',
  'transitionProperty',
  'transitionDuration',
  'transitionTimingFunction',
  'transitionDelay',
  'overflow',
  'overflowX',
  'overflowY',
  'pointerEvents',
  'userSelect',
  'outline',
  'outlineOffset',
  'outlineColor',
  'outlineStyle',
  'outlineWidth'
] as const

export type StyleProps = {
  [key in (typeof properties)[number]]?: CSSProperties[key]
}

export function convertStylePropsToCSS(props: StyleProps): CSSProperties {
  const style: CSSProperties = {}

  const directProps = properties.filter(
    (prop) => prop !== 'translate' && prop !== 'scale' && prop !== 'rotate'
  )

  directProps.forEach((prop) => {
    if (props[prop] !== undefined) {
      // NOTE: style[prop as keyof CSSProperties] cause TypeScript TS2590 error
      // CSSProperties has many properties, making it difficult for the TypeScript compiler to accurately infer the type when indexing.
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      ;(style as any)[prop] = props[prop]
    }
  })

  if (props.translate || props.scale || props.rotate) {
    const transforms = []

    if (props.translate) transforms.push(`translate(${props.translate})`)
    if (props.scale) transforms.push(`scale(${props.scale})`)
    if (props.rotate) transforms.push(`rotate(${props.rotate})`)

    style.transform = transforms.join(' ')
  }

  return style
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function extractStyleProps<T extends Record<string, any>>(
  props: T
): [StyleProps, Omit<T, keyof StyleProps>] {
  const stylePropsKeys = new Set(properties)

  const styleProps: StyleProps = {}
  const restProps = { ...props }

  Object.keys(props).forEach((key) => {
    if (stylePropsKeys.has(key as keyof StyleProps)) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      ;(styleProps as any)[key] = props[key]
      delete restProps[key]
    }
  })

  return [styleProps, restProps as Omit<T, keyof StyleProps>]
}

