import { useCallback, useState } from 'react'

type Props = {
  initialOpen?: boolean
  onOpen?: () => void
  onClose?: () => void
}

type ReturnType = [boolean, () => void, () => void]

export const useDialog = ({ initialOpen = false, onOpen, onClose }: Props): ReturnType => {
  const [isOpen, setIsOpen] = useState(initialOpen)

  const open = useCallback(() => {
    setIsOpen(true)
    onOpen?.()
  }, [onOpen])

  const close = useCallback(() => {
    setIsOpen(false)
    onClose?.()
  }, [onClose])

  return [isOpen, open, close]
}

import { useCallback, useEffect, useRef } from 'react'

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const useDebouncedCallback = <T extends (...args: any[]) => any>(
  callback: T,
  delay: number
): T => {
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const callbackRef = useRef(callback)

  useEffect(() => {
    callbackRef.current = callback
  }, [callback])

  const debouncedCallback = useCallback(
    (...args: Parameters<T>) => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }

      timeoutRef.current = setTimeout(() => {
        callbackRef.current(...args)
      }, delay)
    },
    [delay]
  ) as T

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
    }
  }, [])

  return debouncedCallback
}

import { useEffect, useRef, useState } from 'react'

export const useDebounce = <T>(value: T, delay: number): T => {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current)
    }

    timeoutRef.current = setTimeout(() => {
      setDebouncedValue(value)
    }, delay)

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
    }
  }, [value, delay])

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
    }
  }, [])

  return debouncedValue
}

import { RefObject, useEffect } from 'react'

export type UseClickOutsideOptions = {
  refs: RefObject<HTMLElement | null>[]
  excludeSelectors?: string[]
  onClickOutside: () => void
  enabled?: boolean
}

/**
 * @param refs List of refs to exclude from click detection
 * @param refs Additional CSS selectors to exclude
 * @param refs Callback invoked when clicking outside
 * @param refs Whether the hook is enabled (default: true)
 */
export function useClickOutside({
  refs,
  excludeSelectors = [],
  onClickOutside,
  enabled = true
}: UseClickOutsideOptions): void {
  useEffect(() => {
    if (!enabled) return

    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement | null
      if (!target) return

      for (const ref of refs) {
        if (ref.current?.contains(target)) {
          return
        }
      }

      for (const selector of excludeSelectors) {
        if (target.closest(selector)) {
          return
        }
      }

      onClickOutside()
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [refs, excludeSelectors, onClickOutside, enabled])
}

import { ChangeEvent, Dispatch, SetStateAction, useCallback, useState, useEffect } from 'react'
import { useAutoSave } from './useAutoSave'

export const useAutoSaveInput = (
  initialValue: string,
  onSave: (value: string) => Promise<void> | void,
  delay: number = 1000
): [
  value: string,
  setValue: Dispatch<SetStateAction<string>>,
  handleChange: (e: ChangeEvent<HTMLTextAreaElement | HTMLInputElement>) => void
] => {
  const [value, setValue] = useState<string>(initialValue)

  useEffect(() => {
    setValue(initialValue)
  }, [initialValue])

  const handleChange = useCallback((e: ChangeEvent<HTMLTextAreaElement | HTMLInputElement>) => {
    setValue(e.target.value)
  }, [])

  useAutoSave(value, onSave, delay)

  return [value, setValue, handleChange]
}

import { useEffect, useRef } from 'react'
import { useDebouncedCallback } from './useDebouncedCallback'

export const useAutoSave = <T>(
  value: T,
  onSave: (value: T) => Promise<void> | void,
  delay: number = 1000
) => {
  const isInitialMount = useRef(true)

  const debouncedSave = useDebouncedCallback(async (valueToSave: T) => {
    try {
      await onSave(valueToSave)
    } catch (error) {
      console.error('Auto save error:', error)
    }
  }, delay)

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false
      return
    }

    debouncedSave(value)
  }, [value, debouncedSave])
}

export const flattenTokens = <T extends Record<string, unknown>>(
  tokens: T,
  prefix = ''
): Record<string, string> => {
  return Object.entries(tokens).reduce(
    (acc, [key, value]) => {
      const newKey = prefix ? `${prefix}.${key}` : key
      if (typeof value === 'object' && value !== null) {
        Object.assign(acc, flattenTokens(value as Record<string, unknown>, newKey))
      } else {
        acc[newKey] = value as string
      }
      return acc
    },
    {} as Record<string, string>
  )
}

function hexToRgb(hex: string): string {
  const r = parseInt(hex.slice(1, 3), 16)
  const g = parseInt(hex.slice(3, 5), 16)
  const b = parseInt(hex.slice(5, 7), 16)

  return `${r}, ${g}, ${b}`
}

export function rgba(baseColor: string, alpha: number): string {
  return `rgba(${hexToRgb(baseColor)}, ${alpha})`
}

