import { useState } from 'react'
import { TimeDistribution } from '@illog/ui'
import { Meta, StoryObj } from '@storybook/react-vite'
import TimeDistributionMdx from './TimeDistribution.mdx'

type TaskCategory = {
  name: string
  hours: number
  color: string
}

const mockCategories: TaskCategory[] = [
  { name: 'Meetings', hours: 8, color: '#4f46e5' },
  { name: 'Focus', hours: 14, color: '#10b981' },
  { name: 'Breaks', hours: 4, color: '#f59e0b' },
  { name: 'Admin', hours: 6, color: '#ef4444' }
]

type TimeDistributionDemoProps = {
  items: TaskCategory[]
  title?: React.ReactNode
  clickable?: boolean
}

const TimeDistributionDemo = ({ items, title, clickable = false }: TimeDistributionDemoProps) => {
  const [lastClicked, setLastClicked] = useState<string | null>(null)

  const total = items.reduce((sum, item) => sum + item.hours, 0)

  return (
    <div style={{ width: '360px' }}>
      {lastClicked && (
        <div
          style={{
            marginBottom: '12px',
            padding: '8px 12px',
            background: '#f3f4f6',
            borderRadius: '6px',
            fontSize: '13px',
            color: '#374151'
          }}
        >
          Last clicked: <strong>{lastClicked}</strong>
        </div>
      )}
      <TimeDistribution
        title={title}
        items={items}
        getValue={(item) => item.hours}
        getFillColor={(item) => item.color}
        getKey={(item) => item.name}
        getLabel={(item, { percentage }) =>
          `${item.name} (${Math.round(percentage)}%)`
        }
        onItemClick={
          clickable
            ? (item) => setLastClicked(`${item.name} — ${item.hours}h / ${total}h total`)
            : undefined
        }
      />
    </div>
  )
}

