const FRUITS = [
  { value: 'apple', label: 'Apple' },
  { value: 'banana', label: 'Banana' },
  { value: 'cherry', label: 'Cherry' },
  { value: 'grape', label: 'Grape' },
  { value: 'mango', label: 'Mango' },
  { value: 'orange', label: 'Orange' }
]

const BasicSelectorDemo = ({
  disabled = false,
  defaultValue = '',
  placeholder = 'Select a fruit...'
}: {
  disabled?: boolean
  defaultValue?: string
  placeholder?: string
}) => {
  return (
    <div style={{ padding: '20px', minWidth: '220px' }}>
      <BasicSelector.Root defaultValue={defaultValue} disabled={disabled}>
        <BasicSelector.Trigger ariaLabel="Select a fruit">
          <BasicSelector.Value placeholder={placeholder} />
        </BasicSelector.Trigger>

        <BasicSelector.Content position="popover" sideOffset={4}>
          <BasicSelector.Viewport>
            {FRUITS.map((fruit) => (
              <BasicSelector.Item key={fruit.value} value={fruit.value}>
                {fruit.label}
              </BasicSelector.Item>
            ))}
          </BasicSelector.Viewport>
        </BasicSelector.Content>
      </BasicSelector.Root>
    </div>
  )
}

const ControlledBasicSelectorDemo = ({
  placeholder = 'Select a fruit...'
}: {
  placeholder?: string
}) => {
  const [value, setValue] = useState('')

  return (
    <div style={{ padding: '20px', minWidth: '220px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <BasicSelector.Root value={value} onValueChange={setValue}>
        <BasicSelector.Trigger ariaLabel="Select a fruit">
          <BasicSelector.Value placeholder={placeholder} />
        </BasicSelector.Trigger>

        <BasicSelector.Content position="popover" sideOffset={4}>
          <BasicSelector.Viewport>
            {FRUITS.map((fruit) => (
              <BasicSelector.Item key={fruit.value} value={fruit.value}>
                {fruit.label}
              </BasicSelector.Item>
            ))}
          </BasicSelector.Viewport>
        </BasicSelector.Content>
      </BasicSelector.Root>

      {value && (
        <p style={{ margin: 0, fontSize: '13px', color: '#555' }}>
          Selected value: <strong>{value}</strong>
        </p>
      )}

      {value && (
        <button
          onClick={() => setValue('')}
          style={{ fontSize: '12px', cursor: 'pointer', width: 'fit-content' }}
        >
          Clear selection
        </button>
      )}
    </div>
  )
}

