const DialogDemo = ({
  role = 'dialog',
  ariaLabel = 'Confirm action',
  showFooter = true
}: {
  role?: 'dialog' | 'alertdialog'
  ariaLabel?: string
  showFooter?: boolean
}) => {
  const [isOpen, setIsOpen] = useState(false)

  return (
    <div style={{ padding: '20px' }}>
      <Button variant="primary" onClick={() => setIsOpen(true)}>
        Open Dialog
      </Button>

      <Dialog
        isOpen={isOpen}
        onClose={() => setIsOpen(false)}
        role={role}
        ariaLabel={ariaLabel}
      >
        <Dialog.Title>Confirm Action</Dialog.Title>

        <Dialog.Content>
          <Dialog.Description>
            Are you sure you want to proceed? This action cannot be undone.
          </Dialog.Description>
        </Dialog.Content>

        {showFooter && (
          <Dialog.Footer>
            <Button variant="secondary" isFullWidth onClick={() => setIsOpen(false)}>
              Cancel
            </Button>
            <Button variant="primary" isFullWidth onClick={() => setIsOpen(false)}>
              Confirm
            </Button>
          </Dialog.Footer>
        )}
      </Dialog>
    </div>
  )
}

