import { app, BrowserWindow } from 'electron'
import path, { join } from 'path'
import windowStateKeeper from 'electron-window-state'
import { resolveIconPath } from '../utils/icon'

// Forge's Vite plugin injects these global variables
declare const MAIN_WINDOW_VITE_DEV_SERVER_URL: string | undefined
declare const MAIN_WINDOW_VITE_NAME: string

export function createWindow(baseDirname: string): BrowserWindow {
  const mainWindowState = windowStateKeeper({
    defaultWidth: 1240,
    defaultHeight: 760
  })

  const win = new BrowserWindow({
    x: mainWindowState.x,
    y: mainWindowState.y,
    width: mainWindowState.width,
    height: mainWindowState.height,
    minWidth: 1240,
    minHeight: 760,
    show: false,
    title: app.getName(),
    icon: resolveIconPath(baseDirname, 'app'),
    webPreferences: {
      sandbox: false, // Need to set it to false to use contextBridge in preload
      preload: path.join(__dirname, 'preload.js'), // Forge Vite plugin compiles preload alongside main
      contextIsolation: true, // Complete isolation between renderer and node.js (CSP level enhancement)
      nodeIntegration: false // Direct use of node.js API in renderer is prohibited
    }
  })

  mainWindowState.manage(win)

  if (MAIN_WINDOW_VITE_DEV_SERVER_URL) {
    let retryCount = 0
    const MAX_RETRIES = 3

    win.loadURL(MAIN_WINDOW_VITE_DEV_SERVER_URL)

    win.webContents.on('did-fail-load', (event, errorCode, errorDescription) => {
      console.log(`Load failed: ${errorDescription} (${errorCode})`)

      if (retryCount < MAX_RETRIES && !win.isDestroyed()) {
        retryCount++
        setTimeout(() => {
          win.loadURL(MAIN_WINDOW_VITE_DEV_SERVER_URL!)
        }, 500 * retryCount)
      }
    })

    win.webContents.openDevTools({ mode: 'detach' })
  } else {
    win.loadFile(join(__dirname, `../renderer/${MAIN_WINDOW_VITE_NAME}/index.html`))
  }
  return win
}

import { app } from 'electron'
import path from 'path'

/**
 * - Packaged: process.resourcesPath/assets/...
 * - Development: resolve from project root to src/main/assets
 */
export function getAssetPath(baseDirname: string, ...segments: string[]) {
  if (app.isPackaged) {
    return path.join(process.resourcesPath, 'assets', ...segments)
  }

  // In dev mode, __dirname points to '.vite/build' (Forge Vite plugin output).
  // Assets live in 'src/main/assets', so resolve from app root.
  const appRoot = path.resolve(baseDirname, '..', '..')
  return path.join(appRoot, 'src', 'main', 'assets', ...segments)
}

import { existsSync } from 'fs'
import { getAssetPath } from './path'

type IconType = 'app' | 'tray'

type PlatformIconMap = Partial<Record<NodeJS.Platform, Record<IconType, string[]>>>

/**
 * Runtime icon paths — nativeImage only supports PNG and JPEG.
 * .icns/.ico are NOT loadable via nativeImage.createFromPath().
 * .icns is only used by electron-builder for the macOS app bundle icon.
 *
 * macOS tray: must use "Template" naming convention for auto dark/light mode.
 *             Electron automatically picks up @2x variant if present.
 *             Recommended sizes: 16x16 (1x), 32x32 (2x)
 *             or 22x22 (1x), 44x44 (2x) for tray.
 */
const platformIconSegments: PlatformIconMap = {
  darwin: {
    app: ['icons', 'darwin', 'app.png'],
    tray: ['icons', 'darwin', 'trayTemplate.png']
  },
  linux: {
    app: ['icons', 'linux', 'app-256.png'],
    tray: ['icons', 'linux', 'tray.png']
  },
  win32: {
    app: ['icons', 'win32', 'app.png'],
    tray: ['icons', 'win32', 'tray.png']
  }
}

// Fallback: 1024x1024 PNG that works on all platforms
const defaultIconSegments: Record<IconType, string[]> = {
  app: ['icons', 'iconTemplate.png'],
  tray: ['icons', 'trayTemplate.png']
}

function resolveSegments(type: IconType): string[] {
  const platform = process.platform
  return platformIconSegments[platform]?.[type] ?? defaultIconSegments[type]
}

/**
 * Resolve icon path at runtime (dev & packaged).
 * Always returns a PNG path that nativeImage can load.
 */
export function resolveIconPath(baseDirname: string, type: IconType): string {
  const segments = resolveSegments(type)
  const iconPath = getAssetPath(baseDirname, ...segments)

  if (existsSync(iconPath)) {
    return iconPath
  }

  // Fallback to cross-platform default
  const fallbackSegments = defaultIconSegments[type]
  const fallbackIconPath = getAssetPath(baseDirname, ...fallbackSegments)

  if (!existsSync(fallbackIconPath)) {
    console.warn(
      `[icon] Icon not found for type "${type}" on "${process.platform}". ` +
        `Checked: ${iconPath}, ${fallbackIconPath}`
    )
    return iconPath
  }

  return fallbackIconPath
}

import { BrowserWindow } from 'electron'
import { autoUpdater } from 'electron'
import log from 'electron-log'

export interface UpdaterConfig {
  feedURL: string
  mainWindow: BrowserWindow | null
}

export class AppUpdater {
  private mainWindow: BrowserWindow | null
  private updateAvailable = false
  private isDevelopment: boolean
  private feedURL: string | null

  constructor(config: UpdaterConfig) {
    this.mainWindow = config.mainWindow
    this.isDevelopment = process.env.NODE_ENV === 'development'
    this.feedURL = this.normalizeFeedUrl(config.feedURL)

    if (this.isDevelopment) {
      log.info('Running in development mode - skipping autoUpdater setup')
      return
    }

    try {
      if (!this.feedURL) {
        log.warn('Feed URL missing - autoUpdater disabled')
        return
      }

      autoUpdater.setFeedURL({
        url: this.feedURL,
        serverType: 'json'
      })

      this.setupListeners()
    } catch (err) {
      log.error('Failed to initialize autoUpdater:', err)
    }
  }

  private setupListeners() {
    autoUpdater.on('error', (err) => {
      log.error('Update error:', err)
    })

    autoUpdater.on('checking-for-update', () => {
      log.info('Checking for update...')
    })

    autoUpdater.on('update-available', () => {
      log.info('Update available')
      this.updateAvailable = true
      this.notifyRenderer()
    })

    autoUpdater.on('update-not-available', () => {
      log.info('Update not available')
      this.updateAvailable = false
    })

    autoUpdater.on('update-downloaded', (event, releaseNotes, releaseName) => {
      log.info('Update downloaded')
      this.showUpdateDialog(releaseNotes, releaseName)
    })
  }

  private notifyRenderer() {
    if (this.mainWindow && !this.mainWindow.isDestroyed()) {
      this.mainWindow.webContents.send('update-available')
    }
  }

  private showUpdateDialog(releaseNotes: string, releaseName: string) {
    if (!this.mainWindow || this.mainWindow.isDestroyed()) {
      return
    }

    this.mainWindow.webContents.send('update-downloaded', {
      releaseNotes,
      releaseName
    })
  }

  public checkForUpdates() {
    if (this.isDevelopment) {
      log.info('Skip update check in development mode')
      return
    }

    if (!this.feedURL) {
      log.warn('Feed URL missing - skip update check')
      return
    }

    try {
      autoUpdater.checkForUpdates()
    } catch (err) {
      log.error('Failed to check for updates:', err)
    }
  }

  public quitAndInstall() {
    if (this.isDevelopment) {
      log.warn('Cannot quit and install in development mode')
      return
    }
    autoUpdater.quitAndInstall()
  }

  public setMainWindow(window: BrowserWindow | null) {
    this.mainWindow = window
  }

  private normalizeFeedUrl(feedURL: string): string | null {
    if (!feedURL) {
      return null
    }

    const trimmed = feedURL.trim()
    if (!trimmed) {
      return null
    }

    if (trimmed.endsWith('/RELEASES.json') || trimmed.endsWith('/releases.json')) {
      return trimmed
    }

    return `${trimmed.replace(/\/+$/, '')}/RELEASES.json`
  }

  /**
   * For testing the update dialog in development mode
   * Can be called from DevTools console with window.api.updater.simulateUpdate()
   */
  public simulateUpdate() {
    if (!this.isDevelopment) {
      log.warn('simulateUpdate is only available in development mode')
      return
    }

    log.info('Simulating update download for testing')
    this.showUpdateDialog(
      'This is a simulated update for testing purposes.',
      'Version 999.9.9 (Simulated)'
    )
  }
}

