import { app, BrowserWindow, Menu, nativeImage, Tray } from 'electron'
import { resolveIconPath } from '../utils/icon'

let tray: Tray | null = null

export function createAppTray(baseDirname: string, win: BrowserWindow | null) {
  if (tray) {
    return tray
  }

  const trayIconPath = resolveIconPath(baseDirname, 'tray')
  let trayIcon = nativeImage.createFromPath(trayIconPath)
  if (trayIcon.isEmpty()) {
    trayIcon = nativeImage.createEmpty()
  }
  if (process.platform === 'darwin') {
    // NOTE: For macOS, set the tray icon as a template image to support dark/light mode automatically
    trayIcon.setTemplateImage(true)
  }
  tray = new Tray(trayIcon)
  if (process.platform === 'darwin') {
    const macTray = tray as Tray & {
      /**
       * selection: The tray icon background is highlighted only when the user clicks on it. (default)
       * always: The tray icon background is always highlighted when the user clicks on it or when the menu is shown.
       * never: The tray icon background is never highlighted.
       */
      setHighlightMode: (mode: 'selection' | 'always' | 'never') => void
    }
    macTray.setHighlightMode?.('always')
  }
  const contextMenu = Menu.buildFromTemplate([
    {
      label: 'Open illog',
      click: () => {
        if (win) {
          if (win.isMinimized()) win.restore()
          win.show()
          win.focus()
        }
      }
    },
    { type: 'separator' },
    { label: 'Quit', role: 'quit' }
  ])
  tray.setToolTip(app.getName())
  tray.setContextMenu(contextMenu)
  tray.on('click', () => {
    if (!win) {
      return
    }
    if (win.isVisible()) {
      win.focus()
    } else {
      win.show()
    }
  })
  return tray
}

import { FeatureFlag, FeatureId, UserPlan, UserPlanInfo, UserProfile } from '../types'

/**
 * Current
 * - Local users: all features disabled (no auth, single 'local' plan)
 *
 * Future
 * - With auth: users can be on 'free', 'pro', or 'enterprise' plans
 * - RemoteConfigService will fetch enabled features for the user's plan from the server
 * - DB schema will store user profile with plan info, and feature flags
 *
 * Plan & Feature Service
 * - local: No features enabled for local users (current)
 * - free: No features enabled for free plan (placeholder for future)
 * - pro: Cloud sync and PDF export enabled (future)
 * - enterprise: Same features as Pro for now (future)
 */

export class UserService {
  private static readonly PLAN_FEATURES: Record<UserPlan, Set<FeatureId>> = {
    local: new Set<FeatureId>([]),
    free: new Set<FeatureId>([]),
    pro: new Set<FeatureId>([
      'ai.reflection',
      'ai.weekly-summary',
      'ai.suggestion',
      'sync.cloud',
      'export.pdf'
    ]),
    enterprise: new Set<FeatureId>([
      'ai.reflection',
      'ai.weekly-summary',
      'ai.suggestion',
      'sync.cloud',
      'export.pdf'
    ])
  }

  private static readonly ALL_FEATURES: FeatureId[] = [
    'ai.reflection',
    'ai.weekly-summary',
    'ai.suggestion',
    'sync.cloud',
    'export.pdf'
  ]

  private static readonly REQUIRED_PLAN: Record<FeatureId, UserPlan> = {
    'ai.reflection': 'pro',
    'ai.weekly-summary': 'pro',
    'ai.suggestion': 'pro',
    'sync.cloud': 'pro',
    'export.pdf': 'pro'
  }

  getCurrentProfile(): UserProfile {
    // TODO: Future implementation will fetch from DB or remote config -> this.authProvider.getCurrentUser()
    return {
      id: 'local-user',
      plan: 'local'
    }
  }

  getUserPlanInfo(): UserPlanInfo {
    const profile = this.getCurrentProfile()
    const features = this.buildFeatureFlags(profile.plan)
    return { profile, features }
  }

  isFeatureEnabled(featureId: FeatureId): boolean {
    const profile = this.getCurrentProfile()
    const enabledSet = UserService.PLAN_FEATURES[profile.plan]
    return enabledSet.has(featureId)
  }

  private buildFeatureFlags(plan: UserPlan): FeatureFlag[] {
    const enabledSet = UserService.PLAN_FEATURES[plan]

    return UserService.ALL_FEATURES.map((id) => ({
      id,
      enabled: enabledSet.has(id),
      requiredPlan: UserService.REQUIRED_PLAN[id]
    }))
  }
}

import { TfIdf, SentenceTokenizer } from 'natural'
import { compareTwoStrings } from 'string-similarity'

interface TextRankResult {
  keySentences: string[]
  sentenceIndices: number[]
  scores: number[]
  processedText: string
}

export class TextRankService {
  private readonly DAMPING_FACTOR = 0.85
  private readonly ITERATIONS = 30
  private readonly MIN_SENTENCE_LENGTH = 10
  private sentenceTokenizer: SentenceTokenizer

  constructor() {
    // @ts-expect-error - SentenceTokenizer is not accurately typed but works without arguments
    this.sentenceTokenizer = new SentenceTokenizer()
  }

  extractKeySentences(text: string, topN?: number): TextRankResult {
    const sentences = this.splitIntoSentences(text)

    if (sentences.length === 0) {
      return {
        keySentences: [],
        sentenceIndices: [],
        scores: [],
        processedText: ''
      }
    }

    if (sentences.length <= 3) {
      return {
        keySentences: sentences,
        sentenceIndices: sentences.map((_, i) => i),
        scores: sentences.map(() => 1.0),
        processedText: sentences.join(' ')
      }
    }

    const tfidf = new TfIdf()
    sentences.forEach((sentence) => tfidf.addDocument(sentence))

    const similarityMatrix = this.buildSimilarityMatrix(sentences)

    const scores = this.textRank(similarityMatrix)

    const numSentences = topN || Math.max(3, Math.ceil(sentences.length * 0.3))
    const rankedIndices = this.getRankedSentenceIndices(scores, numSentences)

    const sortedIndices = rankedIndices.sort((a, b) => a - b)
    const keySentences = sortedIndices.map((i) => sentences[i])
    const keyScores = sortedIndices.map((i) => scores[i])

    return {
      keySentences,
      sentenceIndices: sortedIndices,
      scores: keyScores,
      processedText: keySentences.join(' ')
    }
  }

  private splitIntoSentences(text: string): string[] {
    const rawSentences = this.sentenceTokenizer.tokenize(text)

    if (!rawSentences) {
      return []
    }

    return rawSentences.map((s) => s.trim()).filter((s) => s.length >= this.MIN_SENTENCE_LENGTH)
  }

  private buildSimilarityMatrix(sentences: string[]): number[][] {
    const n = sentences.length
    const matrix: number[][] = Array(n)
      .fill(0)
      .map(() => Array(n).fill(0))

    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        const similarity = compareTwoStrings(sentences[i], sentences[j])
        matrix[i][j] = similarity
        matrix[j][i] = similarity
      }
      matrix[i][i] = 1.0
    }

    return matrix
  }

  private textRank(similarityMatrix: number[][]): number[] {
    const n = similarityMatrix.length
    let scores = Array(n).fill(1.0 / n)

    for (let iter = 0; iter < this.ITERATIONS; iter++) {
      const newScores = Array(n).fill(0)

      for (let i = 0; i < n; i++) {
        let sum = 0
        for (let j = 0; j < n; j++) {
          if (i !== j) {
            const outSum = similarityMatrix[j].reduce((acc, val) => acc + val, 0)
            if (outSum > 0) {
              sum += (similarityMatrix[j][i] / outSum) * scores[j]
            }
          }
        }
        newScores[i] = (1 - this.DAMPING_FACTOR) / n + this.DAMPING_FACTOR * sum
      }

      scores = newScores
    }

    return scores
  }

  private getRankedSentenceIndices(scores: number[], topN: number): number[] {
    const indexed = scores.map((score, index) => ({ score, index }))
    indexed.sort((a, b) => b.score - a.score)
    return indexed.slice(0, topN).map((item) => item.index)
  }

  // NOTE: For debugging - calculate compression ratio
  calculateCompressionRatio(original: string, processed: string): number {
    return processed.length / original.length
  }
}

import { createHash } from 'crypto'
import type { TaskNote, TaskReflection } from '../../shared/types'
import { NoteRepository } from '../repository/noteRepository'
import { GeminiService } from './GeminiService'
import { ReflectionRepository } from '../repository/reflectionRepository'
import { UserService } from './UserService'

type AutoSaveResult =
  | { savedAt: number; conflict: true }
  | { note: TaskNote; savedAt: number; conflict: false }

export class NoteService {
  private queue: Promise<AutoSaveResult> = Promise.resolve({ savedAt: Date.now(), conflict: true })

  constructor(
    private repo: NoteRepository,
    private reflectionRepo: ReflectionRepository,
    private geminiService: GeminiService,
    private userService: UserService
  ) {}

  autoSave(taskId: string, content: string, clientUpdatedAt: number) {
    this.queue = this.queue.then(async () => {
      const last = this.repo.findByTaskId(taskId)

      if (last && Number(last.updatedAt) > clientUpdatedAt) {
        return { savedAt: Number(last.updatedAt), conflict: true }
      }

      const savedAt = Date.now()
      const note = this.repo.upsert(taskId, content, savedAt)
      return { note, savedAt, conflict: false }
    })

    return this.queue
  }

  async *reflectionNoteStream(
    taskId: string,
    text: string
  ): AsyncGenerator<{ chunk: string; done: boolean }, void> {
    if (!this.userService.isFeatureEnabled('ai.reflection')) {
      throw new Error('AI Reflection feature is not available in your current plan')
    }

    let fullContent = ''
    const noteHash = createHash('sha256').update(text).digest('hex')

    for await (const chunk of this.geminiService.reflectionNoteStream(text)) {
      fullContent += chunk
      yield { chunk, done: false }
    }

    this.reflectionRepo.upsert({
      taskId,
      content: fullContent,
      originalNoteHash: noteHash
    })
    yield { chunk: '', done: true }
  }

  getReflection(taskId: string): TaskReflection | null {
    return this.reflectionRepo.findByTaskId(taskId)
  }

  deleteReflection(taskId: string): void {
    this.reflectionRepo.delete(taskId)
  }
}

import { GoogleGenAI } from '@google/genai'
import { TextRankService } from './TextRankService'

export class GeminiService {
  private genAI: GoogleGenAI | null = null
  private apiKey: string
  private textRankService: TextRankService

  constructor(apiKey: string) {
    this.apiKey = apiKey
    this.textRankService = new TextRankService()
  }

  private getClient(): GoogleGenAI {
    if (!this.genAI) {
      if (!this.apiKey) {
        throw new Error('Gemini API key is not configured')
      }
      this.genAI = new GoogleGenAI({ apiKey: this.apiKey })
    }
    return this.genAI
  }

  async *reflectionNoteStream(text: string): AsyncGenerator<string, void> {
    if (!text || text.trim().length === 0) {
      throw new Error('Invalid input text')
    }

    if (!process.env.PROMPT || !process.env.MODEL_NAME) {
      throw new Error('Missing environment variables: PROMPT or MODEL_NAME')
    }

    try {
      const client = this.getClient()
      const textRankResult = this.textRankService.extractKeySentences(text)
      const preprocessedText = textRankResult.processedText
      const systemPrompt = process.env.PROMPT

      const userNote = process.env.PROMPT.replace('{text}', preprocessedText)
      const fullPrompt = `${systemPrompt}\n\n${userNote}`

      const res = await client.models.generateContentStream({
        model: process.env.MODEL_NAME,
        contents: fullPrompt,
        config: {
          thinkingConfig: {
            thinkingBudget: 0
          }
        }
      })

      for await (const chunk of res) {
        if (chunk.text) {
          yield chunk.text
        }
      }
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error'
      console.error('Error generating summary:', error)
      throw new Error(`Failed to generate summary: ${errorMessage}`)
    }
  }

  async reflectionNote(text: string): Promise<string> {
    let result = ''
    for await (const chuck of this.reflectionNoteStream(text)) {
      result += chuck
    }
    return result
  }
}

import * as Sentry from '@sentry/electron/main'
import { app } from 'electron'
import { CrashReportRepository } from '../repository/crashReportRepository'
import type { CrashReportSettings } from '../../shared/types'
import { config, isDev } from '../../config/env'

const SENTRY_DSN = config.sentryDSN
const SENTRY_DEV_DSN = config.sentryDevDSN

/**
 * opt-in flag
 * Sentry.init() must be called before app ready, so it is initialized at the module level,
 * but the actual event sending is controlled by this flag.
 * After connecting to the DB, user settings are read to determine true/false.
 */
let sentryEnabled = false

export function initSentryEarly(): void {
  Sentry.init({
    dsn: isDev ? SENTRY_DEV_DSN : SENTRY_DSN,
    environment: isDev ? 'development' : 'production',

    // PII(Personally Identifiable Information) collection OFF
    sendDefaultPii: false,

    maxBreadcrumbs: 50,

    // Tracing disabled (crash reports only)
    tracesSampleRate: 0,

    // In beforeSend, it checks the sentryEnabled flag
    beforeSend(event) {
      // Drop events if user has not consented to opt-in or if disabled in development
      if (!sentryEnabled) {
        return null
      }

      // Drop events without release
      if (!event.release) {
        return null
      }

      // Remove file:// URLs
      if (event.request?.url?.startsWith('file://')) {
        delete event.request
      }

      // Remove local path information from stack traces
      if (event.exception?.values) {
        for (const exception of event.exception.values) {
          if (exception.stacktrace?.frames) {
            for (const frame of exception.stacktrace.frames) {
              if (frame.filename && frame.filename.startsWith('/')) {
                const parts = frame.filename.split('/')
                frame.filename = parts[parts.length - 1]
              }
              delete frame.abs_path
            }
          }
        }
      }

      // Remove local DB path information
      if (event.extra) {
        const keysToDelete = Object.keys(event.extra).filter(
          (key) =>
            key.toLowerCase().includes('db') ||
            key.toLowerCase().includes('path') ||
            key.toLowerCase().includes('file')
        )
        for (const key of keysToDelete) {
          delete event.extra[key]
        }
      }

      // Remove personally identifiable information from user data fields
      if (event.user) {
        const anonId = event.user.id
        event.user = { id: anonId }
      }

      // Remove sensitive information from breadcrumbs
      if (event.breadcrumbs) {
        event.breadcrumbs = event.breadcrumbs.filter((breadcrumb) => {
          if (
            breadcrumb.data?.url?.startsWith('file://') ||
            breadcrumb.message?.includes('file://')
          ) {
            return false
          }
          return true
        })
      }

      return event
    }
  })

  // Basic tags setting (can be done before app ready)
  Sentry.setTag('arch', process.arch)
  Sentry.setTag('electron_version', process.versions.electron)
  Sentry.setTag('os', process.platform)
}

/**
 * Sentry  crash report service
 *
 * Created after DB connection to control opt-in flag and manage settings.
 * Sentry.init() itself has already been called in initSentryEarly().
 */
export class CrashReportService {
  constructor(private repo: CrashReportRepository) {}

  /**
   * Reads settings from the DB to determine whether Sentry is enabled.
   * Called after app ready + DB connection.
   */
  applySettings(): void {
    const settings = this.repo.getSettings()
    sentryEnabled = settings.enabled

    if (settings.enabled) {
      // release tag setting (can only be done after app ready)
      Sentry.setTag('release', `${app.getName()}@${app.getVersion()}`)
      Sentry.setUser({ id: settings.anonymousId })
    }
  }

  getSettings(): CrashReportSettings {
    return this.repo.getSettings()
  }

  isOnboardingCompleted(): boolean {
    return this.repo.isOnboardingCompleted()
  }

  completeOnboarding(): void {
    this.repo.completeOnboarding()
  }

  async updateSettings(enabled: boolean): Promise<CrashReportSettings> {
    const settings = this.repo.updateEnabled(enabled)
    sentryEnabled = enabled

    if (enabled) {
      Sentry.setTag('release', `${app.getName()}@${app.getVersion()}`)
      Sentry.setUser({ id: settings.anonymousId })
    }

    return settings
  }

  sendCrashReport(error: { message: string; stack?: string }): void {
    if (!sentryEnabled) return

    const sentryError = new Error(error.message)
    if (error.stack) {
      sentryError.stack = error.stack
    }
    Sentry.captureException(sentryError)
  }

  async shutdown(): Promise<void> {
    if (sentryEnabled) {
      await Sentry.close(2000)
      sentryEnabled = false
    }
  }

  isActive(): boolean {
    return sentryEnabled
  }
}

import { app } from 'electron'
import { HttpTracker } from '@illog/analytics'
import type { EventData } from '@illog/analytics'
import { CrashReportService } from './CrashReportService'
import log from 'electron-log'

/**
 * Analytics service for the Electron app.
 * Uses HttpTracker to send events to Umami Cloud.
 * Shares opt-in state with CrashReportService (Sentry).
 */
export class AnalyticsService {
  private tracker: HttpTracker

  constructor(
    private crashReportService: CrashReportService,
    config: { host: string; websiteId: string }
  ) {
    this.tracker = new HttpTracker({
      host: config.host,
      websiteId: config.websiteId,
      userAgent: `illog/${app.getVersion()} (${process.platform}; ${process.arch})`
    })

    this.tracker.setContext({
      hostname: 'illog-electron',
      language: app.getLocale(),
      screen: '0x0' // will be updated from renderer if needed
    })

    this.applySettings()
  }

  /** Sync analytics enabled state with crash report opt-in */
  applySettings(): void {
    if (this.crashReportService.isActive()) {
      this.tracker.enable()
      log.info('[analytics] Enabled (crash report opt-in is active)')
    } else {
      this.tracker.disable()
      log.info('[analytics] Disabled (crash report opt-in is not active)')
    }
  }

  track(eventName: string, data?: EventData): void {
    this.tracker.track(eventName, data)
  }

  pageView(url: string, title?: string): void {
    this.tracker.pageView(url, title)
  }

  async shutdown(): Promise<void> {
    await this.tracker.shutdown()
  }
}

import { session } from 'electron'
import { isDev } from '../../config/env'

/**
 * Content Security Policy (CSP) configuration.
 *
 * Dev mode:
 *   - Allows Vite HMR (localhost:5173, unsafe-inline, unsafe-eval)
 *   - Does NOT intercept chrome-extension:// requests so DevTools work normally
 *
 * Production mode:
 *   - Strict policy: no unsafe-inline/eval for scripts
 *   - Only allows Sentry for external connections
 *   - upgrade-insecure-requests enforced
 */
export function setupCSP() {
  const connectSrcParts = ["'self'"]
  connectSrcParts.push('https://*.ingest.sentry.io', 'https://*.ingest.us.sentry.io')

  if (isDev) {
    connectSrcParts.push(
      'http://localhost:5173',
      'ws://localhost:5173',
      'http://127.0.0.1:5173',
      'ws://127.0.0.1:5173'
    )
  }
  const connectSrc = connectSrcParts.join(' ')

  const scriptSrcParts = ["'self'"]
  if (isDev) {
    scriptSrcParts.push("'unsafe-inline'", "'unsafe-eval'")
  }
  const scriptSrc = scriptSrcParts.join(' ')
  const styleSrc = "'self' 'unsafe-inline'"
  const imgSrc = "'self' data: blob:"
  const fontSrc = "'self' data:"
  const directives = [
    "default-src 'self'",
    "base-uri 'self'",
    `connect-src ${connectSrc}`,
    `script-src ${scriptSrc}`,
    `style-src ${styleSrc}`,
    `font-src ${fontSrc}`,
    `img-src ${imgSrc}`,
    "frame-src 'none'",
    "object-src 'none'",
    "form-action 'self'",
    "frame-ancestors 'none'"
  ]

  if (!isDev) {
    directives.push('upgrade-insecure-requests')
  }

  const cspString = directives.join('; ')

  try {
    // Only apply CSP to http/https and file:// URLs.
    // chrome-extension:// and devtools:// are excluded so DevTools extensions
    // can load their own resources without being blocked.
    const filter = isDev
      ? { urls: ['http://*/*', 'https://*/*', 'file://*'] }
      : { urls: ['https://*/*', 'file://*'] }

    session.defaultSession.webRequest.onHeadersReceived(filter, (details, callback) => {
      callback({
        responseHeaders: {
          ...details.responseHeaders,
          'Content-Security-Policy': [cspString]
        }
      })
    })

    if (isDev) {
      console.log('[CSP] Dev mode — HMR + DevTools allowed')
    } else {
      console.log('[CSP] Production mode — strict policy')
    }
  } catch (e) {
    console.warn('[CSP] setup failed', e)
  }
}

import { eq, sql } from 'drizzle-orm'
import { BetterSQLite3Database } from 'drizzle-orm/better-sqlite3'
import * as schema from '../database/schema'
import { weeklyReflections } from '../database/schema'
import type {
  UpdateWeeklyReflectionRequest,
  WeeklyReflectionResponse,
  AccomplishmentItem
} from '../../shared/types'

export class WeeklyReflectionRepository {
  constructor(private db: BetterSQLite3Database<typeof schema>) {}

  findByWeekId(weekId: string): WeeklyReflectionResponse | null {
    const reflection = this.db
      .select()
      .from(weeklyReflections)
      .where(eq(weeklyReflections.weekId, weekId))
      .get()

    if (!reflection) {
      return null
    }

    return this.parseReflection(reflection)
  }

  create(weekId: string, data: UpdateWeeklyReflectionRequest): WeeklyReflectionResponse {
    const result = this.db
      .insert(weeklyReflections)
      .values({
        weekId,
        accomplishments: JSON.stringify(data.accomplishments ?? []),
        improvements: JSON.stringify(data.improvements ?? []),
        nextWeekFocus: JSON.stringify(data.nextWeekFocus ?? [])
      })
      .returning()
      .get()

    if (!result) {
      throw new Error('Failed to create weekly reflection')
    }

    return this.parseReflection(result)
  }

  update(weekId: string, data: UpdateWeeklyReflectionRequest): WeeklyReflectionResponse {
    const updateData: Record<string, unknown> = {
      updatedAt: sql`(datetime('now'))`
    }

    if (data.accomplishments !== undefined) {
      updateData.accomplishments = JSON.stringify(data.accomplishments)
    }
    if (data.improvements !== undefined) {
      updateData.improvements = JSON.stringify(data.improvements)
    }
    if (data.nextWeekFocus !== undefined) {
      updateData.nextWeekFocus = JSON.stringify(data.nextWeekFocus)
    }

    const result = this.db
      .update(weeklyReflections)
      .set(updateData)
      .where(eq(weeklyReflections.weekId, weekId))
      .returning()
      .get()

    if (!result) {
      throw new Error('Weekly reflection not found')
    }

    return this.parseReflection(result)
  }

  upsert(weekId: string, data: UpdateWeeklyReflectionRequest): WeeklyReflectionResponse {
    const existing = this.findByWeekId(weekId)

    if (existing) {
      return this.update(weekId, data)
    }

    return this.create(weekId, data)
  }

  private parseReflection(
    reflection: typeof weeklyReflections.$inferSelect
  ): WeeklyReflectionResponse {
    return {
      id: reflection.id,
      weekId: reflection.weekId,
      accomplishments: JSON.parse(reflection.accomplishments) as AccomplishmentItem[],
      improvements: JSON.parse(reflection.improvements) as string[],
      nextWeekFocus: JSON.parse(reflection.nextWeekFocus) as string[],
      createdAt: reflection.createdAt.toISOString(),
      updatedAt: reflection.updatedAt.toISOString()
    }
  }
}

import { BetterSQLite3Database } from 'drizzle-orm/better-sqlite3'
import * as schema from '../database/schema/index'
import {
  CreateTaskSubtypeRequest,
  CreateTaskTypeRequest,
  TaskTypeWithSubtypesDto,
  UpdateTaskSubtypeRequest,
  UpdateTaskTypeRequest
} from '../../shared/types/taskTypeDto'
import {
  TaskType,
  taskTypes,
  InsertTaskType,
  taskSubtypes,
  TaskSubtype,
  InsertTaskSubtype
} from '../database/schema'
import { normalizeName } from '../../utils/utils'
import { and, asc, eq, isNull, sql } from 'drizzle-orm'

export class TaskTypeRepository {
  constructor(private db: BetterSQLite3Database<typeof schema>) {}

  create(data: CreateTaskTypeRequest): TaskType {
    const name = normalizeName(data.name)

    const existing = this.db.select().from(taskTypes).where(eq(taskTypes.name, name)).get()

    if (existing) {
      if (existing.deletedAt) {
        const restored = this.db
          .update(taskTypes)
          .set({ color: data.color ?? existing.color, deletedAt: null })
          .where(eq(taskTypes.id, existing.id))
          .returning()
          .get()
        return restored
      }
      throw new Error(`Task type with name ${name} already exists`)
    }

    const insertData: InsertTaskType = {
      name,
      color: data.color ?? 'blue'
    }

    const newTaskType = this.db.insert(taskTypes).values(insertData).returning().get()

    return newTaskType
  }

  get(id: string): TaskType | null {
    const taskType = this.db
      .select()
      .from(taskTypes)
      .where(and(eq(taskTypes.id, id), isNull(taskTypes.deletedAt)))
      .get()
    return taskType ?? null
  }

  getAll(): TaskType[] {
    return this.db
      .select()
      .from(taskTypes)
      .where(isNull(taskTypes.deletedAt))
      .orderBy(asc(taskTypes.createdAt))
      .all()
  }

  getAllWithSubtypes(): TaskTypeWithSubtypesDto[] {
    const types = this.getAll()

    const allSubtypes = this.db
      .select()
      .from(taskSubtypes)
      .where(isNull(taskSubtypes.deletedAt))
      .orderBy(asc(taskSubtypes.createdAt))
      .all()

    const subtypesByTypeId = new Map<string, TaskSubtype[]>()
    for (const subtype of allSubtypes) {
      const list = subtypesByTypeId.get(subtype.taskTypeId) ?? []
      list.push(subtype)
      subtypesByTypeId.set(subtype.taskTypeId, list)
    }

    return types.map((type) => ({
      ...type,
      subtypes: subtypesByTypeId.get(type.id) ?? []
    }))
  }

  update(id: string, data: UpdateTaskTypeRequest): TaskType {
    const existing = this.get(id)

    if (!existing) {
      throw new Error(`Task type with id ${id} not found`)
    }

    const updateData: Partial<InsertTaskType> = {}

    if (data.name !== undefined) {
      updateData.name = normalizeName(data.name)
    }

    if (data.color !== undefined) {
      updateData.color = data.color
    }

    const updated = this.db
      .update(taskTypes)
      .set(updateData)
      .where(eq(taskTypes.id, id))
      .returning()
      .get()

    if (!updated) {
      throw new Error(`Failed to update task type with id ${id}`)
    }

    return updated
  }

  softDelete(id: string): void {
    const existing = this.get(id)

    if (!existing) {
      throw new Error(`Task type with id ${id} not found`)
    }

    const result = this.db
      .update(taskTypes)
      .set({ deletedAt: sql`(unixepoch())` })
      .where(and(eq(taskTypes.id, id), isNull(taskTypes.deletedAt)))
      .run()

    if (result.changes === 0) {
      throw new Error(`Failed to delete task type with id ${id}`)
    }

    this.db
      .update(taskSubtypes)
      .set({ deletedAt: sql`(unixepoch())` })
      .where(and(eq(taskSubtypes.taskTypeId, id), isNull(taskSubtypes.deletedAt)))
      .run()
  }

  getSubtypes(taskTypeId: string): TaskSubtype[] {
    return this.db
      .select()
      .from(taskSubtypes)
      .where(and(eq(taskSubtypes.taskTypeId, taskTypeId), isNull(taskSubtypes.deletedAt)))
      .orderBy(asc(taskSubtypes.createdAt))
      .all()
  }

  getSubtype(id: string): TaskSubtype | null {
    const subtype = this.db
      .select()
      .from(taskSubtypes)
      .where(and(eq(taskSubtypes.id, id), isNull(taskSubtypes.deletedAt)))
      .get()
    return subtype ?? null
  }

  createSubtype(data: CreateTaskSubtypeRequest): TaskSubtype {
    const name = normalizeName(data.name)

    const parentType = this.get(data.taskTypeId)
    if (!parentType) {
      throw new Error(`Parent task type with id ${data.taskTypeId} not found`)
    }

    const existing = this.db
      .select()
      .from(taskSubtypes)
      .where(and(eq(taskSubtypes.taskTypeId, data.taskTypeId), eq(taskSubtypes.name, name)))
      .get()

    if (existing) {
      if (existing.deletedAt) {
        const restored = this.db
          .update(taskSubtypes)
          .set({ deletedAt: null })
          .where(eq(taskSubtypes.id, existing.id))
          .returning()
          .get()

        return restored
      } else {
        throw new Error(
          `Task subtype with name ${name} already exists for task type ${parentType.name}`
        )
      }
    }

    const insertData: InsertTaskSubtype = {
      taskTypeId: data.taskTypeId,
      name
    }

    const newSubtype = this.db.insert(taskSubtypes).values(insertData).returning().get()

    return newSubtype
  }

  updateSubtype(id: string, data: UpdateTaskSubtypeRequest): TaskSubtype {
    const existing = this.getSubtype(id)

    if (!existing) {
      throw new Error(`Task subtype with id ${id} not found`)
    }

    const updateData: Partial<InsertTaskSubtype> = {}

    if (data.name !== undefined) {
      updateData.name = normalizeName(data.name)
    }
    if (data.color !== undefined) {
      updateData.color = data.color
    }

    const updated = this.db
      .update(taskSubtypes)
      .set(updateData)
      .where(eq(taskSubtypes.id, id))
      .returning()
      .get()

    if (!updated) {
      throw new Error(`Failed to update task subtype with id ${id}`)
    }

    return updated
  }

  softDeleteSubtype(id: string): void {
    const existing = this.getSubtype(id)

    if (!existing) {
      throw new Error(`Task subtype with id ${id} not found`)
    }

    const result = this.db
      .update(taskSubtypes)
      .set({ deletedAt: sql`(unixepoch())` })
      .where(and(eq(taskSubtypes.id, id), isNull(taskSubtypes.deletedAt)))
      .run()

    if (result.changes === 0) {
      throw new Error(`Failed to delete task subtype with id ${id}`)
    }
  }

  validateSubtypeBelongsToType(subtypeId: string, typeId: string): boolean {
    const subtype = this.getSubtype(subtypeId)

    return subtype?.taskTypeId === typeId
  }
}

import type { TaskFilterParams, TaskWithTags, UpdateTaskRequest } from '../../shared/types'
import { and, count, desc, eq, getTableColumns, gte, isNull, like, lte, or, sql } from 'drizzle-orm'
import { BetterSQLite3Database } from 'drizzle-orm/better-sqlite3'
import {
  InsertTask,
  tasks,
  tags,
  taskTags,
  projects,
  Tag,
  Task,
  Project,
  TaskType,
  TaskSubtype,
  taskTypes,
  taskSubtypes
} from '../database/schema'
import * as schema from '../database/schema'

export class TaskRepository {
  constructor(private db: BetterSQLite3Database<typeof schema>) {}

  async create(): Promise<TaskWithTags> {
    const [inserted] = this.db.insert(tasks).values({}).returning().all()

    return { ...inserted, tags: [], project: null, taskType: null, taskSubtype: null }
  }

  async get(id: string): Promise<Task> {
    const task = this.db
      .select()
      .from(tasks)
      .where(and(eq(tasks.id, id), isNull(tasks.deletedAt)))
      .get()

    if (!task) {
      throw new Error('Task not found')
    }

    return task
  }

  // NOTE: Need to refactor function name and tag section
  async getWithTags(id: string): Promise<TaskWithTags> {
    const task = this.db
      .select({
        ...getTableColumns(tasks),
        tags: sql`
        COALESCE(
            json_group_array(
              json_object('id', tag.id, 'name', tag.name, 'color', tag.color)
            ) FILTER (WHERE tag.id IS NOT NULL), json('[]')
          )`.as('tags'),
        project: sql`
          CASE WHEN project.id IS NOT NULL
            THEN json_object('id', project.id, 'name', project.name, 'color', project.color)
            ELSE NULL
          END`.as('project'),
        taskType: sql`
        CASE WHEN task_type.id IS NOT NULL
          THEN json_object('id', task_type.id, 'name', task_type.name, 'color', task_type.color)
          ELSE NULL
        END`.as('taskType'),
        taskSubtype: sql`
        CASE WHEN task_subtype.id IS NOT NULL
          THEN json_object('id', task_subtype.id, 'name', task_subtype.name, 'color', task_subtype.color)
          ELSE NULL
        END`.as('taskSubtype')
      })
      .from(tasks)
      .leftJoin(taskTags, eq(taskTags.taskId, tasks.id))
      .leftJoin(tags, and(eq(tags.id, taskTags.tagId), isNull(tags.deletedAt)))
      .leftJoin(projects, and(eq(projects.id, tasks.projectId), isNull(projects.deletedAt)))
      .leftJoin(taskTypes, and(eq(taskTypes.id, tasks.taskTypeId), isNull(taskTypes.deletedAt)))
      .leftJoin(
        taskSubtypes,
        and(eq(taskSubtypes.id, tasks.taskSubtypeId), isNull(taskSubtypes.deletedAt))
      )
      .where(and(eq(tasks.id, id), isNull(tasks.deletedAt)))
      .get()

    if (!task) {
      throw new Error('Task not found')
    }

    return {
      ...task,
      tags: JSON.parse(task.tags as string) as Tag[],
      project: task.project
        ? (JSON.parse(task.project as string) as Pick<Project, 'id' | 'name' | 'color'>)
        : null,
      taskType: task.taskType
        ? (JSON.parse(task.taskType as string) as Pick<TaskType, 'id' | 'name' | 'color'>)
        : null,
      taskSubtype: task.taskSubtype
        ? (JSON.parse(task.taskSubtype as string) as Pick<TaskSubtype, 'id' | 'name' | 'color'>)
        : null
    }
  }

  async getTasksWithTags(filters?: TaskFilterParams): Promise<TaskWithTags[]> {
    const conditions = [isNull(tasks.deletedAt)]

    if (filters?.status) {
      conditions.push(eq(tasks.status, filters.status))
    }
    if (filters?.projectId) {
      conditions.push(eq(tasks.projectId, filters?.projectId))
    }
    if (filters?.startTime) {
      // NOTE: Filter includes tasks that overlap with [startTime, endTime] range.
      // - Tasks whose endTime >= filterStart (task extends into the range)
      // - Tasks with no endTime whose startTime >= filterStart
      // Expects ISO 8601 string (e.g. "2026-02-10T15:00:00.000Z") from the client.
      const filterStart = new Date(filters.startTime)
      conditions.push(
        or(
          gte(tasks.endTime, filterStart),
          and(isNull(tasks.endTime), gte(tasks.startTime, filterStart))
        )!
      )
    }
    if (filters?.endTime) {
      // Tasks whose startTime <= filterEnd (task starts before the range ends)
      const filterEnd = new Date(filters.endTime)
      conditions.push(lte(tasks.startTime, filterEnd))
    }
    if (filters?.search) {
      const searchCondition = or(
        like(tasks.title, `%${filters?.search}%`),
        like(tasks.description, `%${filters?.search}%`)
      )
      if (searchCondition) {
        conditions.push(searchCondition)
      }
    }

    const results = this.db
      .select({
        ...getTableColumns(tasks),
        tags: sql`
        COALESCE(
            json_group_array(
              json_object('id', tag.id, 'name', tag.name, 'color', tag.color)
            ) FILTER (WHERE tag.id IS NOT NULL), json('[]')
          )`.as('tags'),
        project: sql`
          CASE WHEN project.id IS NOT NULL
            THEN json_object('id', project.id, 'name', project.name, 'color', project.color)
            ELSE NULL
          END`.as('project'),
        taskType: sql`
        CASE WHEN task_type.id IS NOT NULL
          THEN json_object('id', task_type.id, 'name', task_type.name, 'color', task_type.color)
          ELSE NULL
        END`.as('taskType'),
        taskSubtype: sql`
        CASE WHEN task_subtype.id IS NOT NULL
          THEN json_object('id', task_subtype.id, 'name', task_subtype.name, 'color', task_subtype.color)
          ELSE NULL
        END`.as('taskSubtype')
      })
      .from(tasks)
      .leftJoin(taskTags, eq(taskTags.taskId, tasks.id))
      .leftJoin(tags, and(eq(tags.id, taskTags.tagId), isNull(tags.deletedAt)))
      .leftJoin(projects, and(eq(projects.id, tasks.projectId), isNull(projects.deletedAt)))
      .leftJoin(taskTypes, and(eq(taskTypes.id, tasks.taskTypeId), isNull(taskTypes.deletedAt)))
      .leftJoin(
        taskSubtypes,
        and(eq(taskSubtypes.id, tasks.taskSubtypeId), isNull(taskSubtypes.deletedAt))
      )
      .where(and(...conditions))
      .groupBy(tasks.id)
      .orderBy(desc(tasks.createdAt))
      .all()

    return results.map((item) => ({
      ...item,
      tags: JSON.parse(item?.tags as string),
      project: item.project ? JSON.parse(item.project as string) : null,
      taskType: item.taskType ? JSON.parse(item.taskType as string) : null,
      taskSubtype: item.taskSubtype ? JSON.parse(item.taskSubtype as string) : null
    }))
  }

  async update(id: string, contents: UpdateTaskRequest): Promise<TaskWithTags> {
    const updateData: Partial<InsertTask> = {}

    if (contents.title !== undefined) {
      updateData.title = contents.title
    }
    if (contents.description !== undefined) {
      updateData.description = contents.description
    }
    if (contents.status !== undefined) {
      updateData.status = contents.status
      if (contents.status === 'done') {
        updateData.doneAt = new Date()
      }
      if (contents.status !== 'done') {
        updateData.doneAt = null
      }
    }
    if (contents.projectId !== undefined) {
      updateData.projectId = contents.projectId
    }

    if (contents.taskTypeId !== undefined) {
      updateData.taskTypeId = contents.taskTypeId
      if (contents.taskSubtypeId === undefined) {
        updateData.taskSubtypeId = null
      }
    }
    if (contents.taskSubtypeId !== undefined) {
      if (contents.taskSubtypeId !== null) {
        const currentTask = await this.get(id)
        const targetTaskTypeId = contents.taskTypeId || currentTask.taskTypeId

        if (targetTaskTypeId) {
          const subtype = this.db
            .select()
            .from(taskSubtypes)
            .where(and(eq(taskSubtypes.id, contents.taskSubtypeId), isNull(taskSubtypes.deletedAt)))
            .get()

          if (subtype && subtype.taskTypeId !== targetTaskTypeId) {
            throw new Error('Task subtype does not belong to the specified task type')
          }
        }
      }
      updateData.taskSubtypeId = contents.taskSubtypeId
    }

    if (contents.startTime !== undefined) {
      updateData.startTime = contents.startTime ? new Date(contents.startTime) : undefined
    }
    if (contents.endTime !== undefined) {
      updateData.endTime = contents.endTime ? new Date(contents.endTime) : null
    }

    const result = this.db.update(tasks).set(updateData).where(eq(tasks.id, id)).run()

    if (result.changes === 0) {
      throw new Error('Task not found or no changes made')
    }

    return this.getWithTags(id)
  }

  async addTag(taskId: string, tagId: string): Promise<TaskWithTags> {
    const [result] = await this.db
      .select({ count: count() })
      .from(taskTags)
      .where(eq(taskTags.taskId, taskId))

    if (result.count >= 5) {
      throw new Error('A task can have a maximum of 5 tags')
    }

    const exists = await this.db
      .select({ one: taskTags.taskId })
      .from(taskTags)
      .where(and(eq(taskTags.taskId, taskId), eq(taskTags.tagId, tagId)))
      .limit(1)

    if (exists.length > 0) {
      throw new Error('Tag already associated with the task')
    }

    await this.db.insert(taskTags).values({
      taskId: taskId,
      tagId: tagId
    })

    return this.getWithTags(taskId)
  }

  async softDelete(id: string) {
    const deletedTask = await this.db
      .update(tasks)
      .set({ deletedAt: sql`(unixepoch())` })
      .where(and(eq(tasks.id, id), isNull(tasks.deletedAt)))

    if (deletedTask.changes === 0) {
      throw new Error('Task not found')
    }
  }

  async removeTag(taskId: string, tagId: string): Promise<TaskWithTags> {
    this.db
      .delete(taskTags)
      .where(and(eq(taskTags.taskId, taskId), eq(taskTags.tagId, tagId)))
      .run()

    return this.getWithTags(taskId)
  }
}

import { normalizeName } from '../../utils/utils'
