import { PropsWithChildren } from 'react'
import { createPortal } from 'react-dom'

export type PortalProps = PropsWithChildren<{
  container?: Element | DocumentFragment
}>

export const Portal = ({ children, container }: PortalProps) => {
  if (!children) return null

  const target = container ?? (typeof document !== 'undefined' ? document.body : null)
  if (!target) return null

  return createPortal(children, target)
}

import { describe, expect, it } from 'vitest'
import { render } from '@testing-library/react'
import { Portal } from './Portal'

describe('Portal', () => {
  it('renders children to document body by default', () => {
    render(<Portal>Portal content</Portal>)

    expect(document.body.textContent).toContain('Portal content')
  })

  it('renders children to specified container', () => {
    const container = document.createElement('div')
    container.id = 'portal-container'
    document.body.appendChild(container)

    render(<Portal container={container}>Custom container content</Portal>)

    expect(container.textContent).toContain('Custom container content')

    document.body.removeChild(container)
  })

  it('returns null when children is null', () => {
    const { container } = render(<Portal>{null}</Portal>)

    expect(container.innerHTML).toBe('')
  })

  it('returns null when children is undefined', () => {
    const { container } = render(<Portal>{undefined}</Portal>)

    expect(container.innerHTML).toBe('')
  })

  it('renders multiple children', () => {
    render(
      <Portal>
        <span>Child 1</span>
        <span>Child 2</span>
      </Portal>
    )

    expect(document.body.textContent).toContain('Child 1')
    expect(document.body.textContent).toContain('Child 2')
  })

  it('renders nested elements correctly', () => {
    render(
      <Portal>
        <div>
          <span>Nested content</span>
        </div>
      </Portal>
    )

    expect(document.body.textContent).toContain('Nested content')
  })

  it('unmounts content when component unmounts', () => {
    const { unmount } = render(<Portal>Unmount test</Portal>)

    expect(document.body.textContent).toContain('Unmount test')

    unmount()

    expect(document.body.textContent).not.toContain('Unmount test')
  })

  it('renders React components as children', () => {
    const TestComponent = () => <div data-testid="test-component">Test</div>

    render(
      <Portal>
        <TestComponent />
      </Portal>
    )

    expect(document.querySelector('[data-testid="test-component"]')).toBeInTheDocument()
  })
})

import { useEffect, useLayoutEffect, useRef, useState, MouseEvent } from 'react'
import { Portal } from '../Portal'
import { OverlayProps } from './types'
import * as styles from './Overlay.css'
import clsx from 'clsx'

export const Overlay = ({
  isOpen,
  onClose,
  children,
  backgroundOpacity = 50,
  disableBackdropClick = false,
  disableEscapeKey = false,
  zIndex = 1000,
  backdropClassName,
  contentClassName,
  animationDuration = 200,
  animation = 'fade',
  ariaLabel,
  container
}: OverlayProps) => {
  const [isExiting, setIsExiting] = useState(false)
  const [shouldRender, setShouldRender] = useState(isOpen)
  const backdropRef = useRef<HTMLDivElement>(null)
  const contentRef = useRef<HTMLDivElement>(null)

  useLayoutEffect(() => {
    if (isOpen) {
      // NOTE: Since useLayoutEffect runs synchronously before DOM updates, calling setState is safe
      // eslint-disable-next-line
      setIsExiting(false)
      setShouldRender(true)
    } else if (shouldRender) {
      setIsExiting(true)
      const timer = setTimeout(() => {
        setShouldRender(false)
        setIsExiting(false)
      }, animationDuration)
      return () => clearTimeout(timer)
    }
  }, [isOpen, shouldRender, animationDuration])

  useEffect(() => {
    if (!shouldRender || disableEscapeKey || !onClose) return

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose()
      }
    }

    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [shouldRender, disableEscapeKey, onClose])

  useEffect(() => {
    if (!shouldRender) return

    const originalOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'

    return () => {
      document.body.style.overflow = originalOverflow
    }
  }, [shouldRender])

  useEffect(() => {
    if (!shouldRender || !contentRef.current) return

    const focusableElements = contentRef.current.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    )

    const firstElement = focusableElements[0] as HTMLElement
    if (firstElement) {
      firstElement.focus()
    }
  }, [shouldRender])

  const handleBackdropClick = (event: MouseEvent<HTMLDivElement>) => {
    if (disableBackdropClick || !onClose) return

    if (event.target === backdropRef.current) {
      onClose()
    }
  }

  const handleContentClick = (event: MouseEvent<HTMLDivElement>) => {
    event.stopPropagation()
  }

  if (!shouldRender) return null

  const backdropOpacity = Math.max(0, Math.min(100, backgroundOpacity)) / 100

  const backdropAlignClass =
    animation === 'slideLeft'
      ? styles.contentAlignLeft
      : animation === 'slideRight'
        ? styles.contentAlignRight
        : undefined

  return (
    <Portal container={container}>
      <div
        ref={backdropRef}
        className={clsx([
          styles.backdrop,
          isExiting && styles.backdropExit,
          backdropAlignClass,
          backdropClassName
        ])}
        style={{
          backgroundColor: `rgba(0, 0, 0, ${backdropOpacity})`,
          zIndex,
          animationDuration: `${animationDuration}ms`
        }}
        onClick={handleBackdropClick}
        role="presentation"
        aria-modal="true"
        aria-label={ariaLabel}
      >
        <div
          ref={contentRef}
          className={clsx([
            styles.contentBase,
            isExiting ? styles.contentAnimationExit[animation] : styles.contentAnimation[animation],
            contentClassName
          ])}
          onClick={handleContentClick}
          role="dialog"
          tabIndex={-1}
          style={{
            animationDuration: `${animationDuration}ms`
          }}
        >
          {children}
        </div>
      </div>
    </Portal>
  )
}

import { describe, expect, it, vi, beforeEach, afterEach } from 'vitest'
import { render } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { Overlay } from './Overlay'

describe('Overlay', () => {
  beforeEach(() => {
    // 각 테스트 전에 body의 overflow를 초기화
    document.body.style.overflow = ''
  })

  afterEach(() => {
    // 각 테스트 후 cleanup
    document.body.style.overflow = ''
  })

  it('renders children when isOpen is true', () => {
    render(
      <Overlay isOpen>
        <div>Overlay content</div>
      </Overlay>
    )

    expect(document.body.textContent).toContain('Overlay content')
  })

  it('does not render when isOpen is false', () => {
    render(
      <Overlay isOpen={false}>
        <div>Hidden content</div>
      </Overlay>
    )

    expect(document.body.textContent).not.toContain('Hidden content')
  })

  it('has aria-modal attribute for accessibility', () => {
    render(
      <Overlay isOpen>
        <div>Modal content</div>
      </Overlay>
    )

    expect(document.querySelector('[aria-modal="true"]')).toBeInTheDocument()
  })

  it('has dialog role', () => {
    render(
      <Overlay isOpen>
        <div>Dialog content</div>
      </Overlay>
    )

    expect(document.querySelector('[role="dialog"]')).toBeInTheDocument()
  })

  it('applies custom ariaLabel', () => {
    render(
      <Overlay isOpen ariaLabel="Custom overlay">
        <div>Content</div>
      </Overlay>
    )

    expect(document.querySelector('[aria-label="Custom overlay"]')).toBeInTheDocument()
  })

  it('calls onClose when backdrop is clicked directly', async () => {
    const handleClose = vi.fn()

    render(
      <Overlay isOpen onClose={handleClose}>
        <div>Content</div>
      </Overlay>
    )

    const backdrop = document.querySelector('[role="presentation"]') as HTMLElement
    // 직접 mousedown 이벤트를 시뮬레이션 (backdrop 자체를 target으로)
    const event = new MouseEvent('click', {
      bubbles: true,
      cancelable: true
    })
    Object.defineProperty(event, 'target', { value: backdrop })
    backdrop.dispatchEvent(event)

    expect(handleClose).toHaveBeenCalledTimes(1)
  })

  it('does not call onClose when content is clicked', async () => {
    const user = userEvent.setup()
    const handleClose = vi.fn()

    render(
      <Overlay isOpen onClose={handleClose}>
        <button>Click me</button>
      </Overlay>
    )

    const button = document.querySelector('button')!
    await user.click(button)

    expect(handleClose).not.toHaveBeenCalled()
  })

  it('does not call onClose when disableBackdropClick is true', async () => {
    const handleClose = vi.fn()

    render(
      <Overlay isOpen onClose={handleClose} disableBackdropClick>
        <div>Content</div>
      </Overlay>
    )

    const backdrop = document.querySelector('[role="presentation"]') as HTMLElement
    const event = new MouseEvent('click', {
      bubbles: true,
      cancelable: true
    })
    Object.defineProperty(event, 'target', { value: backdrop })
    backdrop.dispatchEvent(event)

    expect(handleClose).not.toHaveBeenCalled()
  })

  it('calls onClose when Escape key is pressed', async () => {
    const user = userEvent.setup()
    const handleClose = vi.fn()

    render(
      <Overlay isOpen onClose={handleClose}>
        <div>Content</div>
      </Overlay>
    )

    await user.keyboard('{Escape}')

    expect(handleClose).toHaveBeenCalledTimes(1)
  })

  it('does not call onClose on Escape when disableEscapeKey is true', async () => {
    const user = userEvent.setup()
    const handleClose = vi.fn()

    render(
      <Overlay isOpen onClose={handleClose} disableEscapeKey>
        <div>Content</div>
      </Overlay>
    )

    await user.keyboard('{Escape}')

    expect(handleClose).not.toHaveBeenCalled()
  })

  it('applies custom zIndex', () => {
    render(
      <Overlay isOpen zIndex={2000}>
        <div>Content</div>
      </Overlay>
    )

    const backdrop = document.querySelector('[role="presentation"]')!
