    type = 'text',
    name = '',
    value = '',
    size = 'md',
    variant = 'default',
    isFullWidth,
    isDisabled,
    errorMessage,
    onChange,
    ref,
    className,
    ...rest
  } = props

  return (
    <div className={style.inputWrapper}>
      <input
        type={type}
        name={name}
