  max = DEFAULT_MAX,
  height = DEFAULT_HEIGHT,
  radius = DEFAULT_RADIUS,
  fillColor = DEFAULT_FILL_COLOR,
  trackColor = DEFAULT_TRACK_COLOR,
  isAnimated = true,
  trackStyle,
  fillStyle,
  ariaLabel,
  className,
  style,
  ...restProps
}: HorizontalBarProps) => {
  const safeMin = Number.isFinite(min) ? min : DEFAULT_MIN
  const safeMax = Number.isFinite(max) && max > safeMin ? max : DEFAULT_MAX
  const safeValue = clamp(Number.isFinite(value) ? value : safeMin, safeMin, safeMax)

  const range = safeMax - safeMin
  const ratio = range > 0 ? (safeValue - safeMin) / range : 0

  return (
    <div
      {...restProps}
      className={className}
      style={{ width: '100%', ...style }}
      role="progressbar"
      aria-label={ariaLabel ?? 'Progress'}
      aria-valuemin={safeMin}
      aria-valuemax={safeMax}
      aria-valuenow={safeValue}
    >
      <div
        data-slot="track"
        style={{
          width: '100%',
          height,
          borderRadius: radius,
          backgroundColor: trackColor,
          overflow: 'hidden',
          ...trackStyle
        }}
      >
        <div
          data-slot="fill"
          style={{
            width: `${ratio * 100}%`,
            height: '100%',
            borderRadius: radius,
            backgroundColor: fillColor,
            transition: isAnimated ? 'width 160ms ease-out' : undefined,
            ...fillStyle
          }}
        />
      </div>
    </div>
  )
}

