import { MouseEvent, RefObject, useCallback } from 'react'
import { ContextMenuTriggerProps } from './types'
import { useContextMenuContext } from './context/context'

export const Trigger = ({
  children,
  isDisabled = false,
  className,
  style
}: ContextMenuTriggerProps) => {
  const { isOpen, triggerRef, onOpenChange, onPointerPositionChange } = useContextMenuContext()

  const handleContextMenu = useCallback(
    (e: MouseEvent) => {
      if (isDisabled) return

      const activeElement = document.activeElement
      if (
        activeElement instanceof HTMLInputElement ||
        activeElement instanceof HTMLTextAreaElement
      ) {
        return
      }

      e.preventDefault()
      onPointerPositionChange({ x: e.clientX, y: e.clientY })
      onOpenChange(true)
    },
    [isDisabled, onOpenChange, onPointerPositionChange]
  )

  return (
    <div
      ref={triggerRef as RefObject<HTMLDivElement>}
      onContextMenu={handleContextMenu}
      data-state={isOpen ? 'open' : 'closed'}
      data-disabled={isDisabled ? 'true' : 'false'}
      className={className}
      style={{ ...style }}
    >
      {children}
    </div>
  )
}

import { useCallback, useMemo, useRef, useState } from 'react'
import { ContextMenuRootProps } from './types'
import { ContextMenuContext } from './context/context'

export const Root = ({ children, onOpenChange, modal = false }: ContextMenuRootProps) => {
  const [isOpen, setIsOpen] = useState(false)
  const [pointerPosition, setPointerPosition] = useState({ x: 0, y: 0 })
  const triggerRef = useRef<HTMLElement | null>(null)
  const contentRef = useRef<HTMLDivElement | null>(null)

  const handleOpenChange = useCallback(
    (isOpen: boolean) => {
      setIsOpen(isOpen)
      if (onOpenChange) {
        onOpenChange(isOpen)
      }
    },
    [onOpenChange]
  )

  const handleClose = useCallback(() => {
    handleOpenChange(false)
  }, [handleOpenChange])

  const contextValue = useMemo(
    () => ({
      isOpen,
      onOpenChange: handleOpenChange,
      pointerPosition,
      onPointerPositionChange: setPointerPosition,
      contentRef,
      triggerRef,
      onClose: handleClose,
      modal
    }),
    [isOpen, handleOpenChange, pointerPosition, handleClose, modal]
  )

  return <ContextMenuContext.Provider value={contextValue}>{children}</ContextMenuContext.Provider>
}

import { MouseEvent, useCallback } from 'react'
import { ContextMenuItemProps } from './types'
import { useContextMenuContext } from './context/context'
import { item as itemStyle } from './contextMenu.css'
import clsx from 'clsx'

export const Item = ({
  isDisabled = false,
  textValue,
  className,
  style,
  children,
  onSelect
}: ContextMenuItemProps) => {
  const { onClose } = useContextMenuContext()

  const handleClick = useCallback(
    (e: MouseEvent<HTMLDivElement>) => {
      e.stopPropagation()
      if (isDisabled) return
      onSelect?.()
      onClose()
    },
    [isDisabled, onSelect, onClose]
  )

  return (
    <div
      role="menuitem"
      aria-disabled={isDisabled || undefined}
      tabIndex={isDisabled ? undefined : -1}
      data-disabled={isDisabled ? '' : undefined}
      data-value={textValue}
      className={clsx(itemStyle, className)}
      style={style}
      onClick={handleClick}
    >
      {children}
    </div>
  )
}

