import { S3Client, GetObjectCommand } from '@aws-sdk/client-s3'
import { getSignedUrl } from '@aws-sdk/s3-request-presigner'

const REGION = process.env.AWS_REGION
const ACCESS_KEY_ID = process.env.AWS_ACCESS_KEY_ID
const SECRET_ACCESS_KEY = process.env.AWS_SECRET_ACCESS_KEY
const SESSION_TOKEN = process.env.AWS_SESSION_TOKEN
const BUCKET_NAME = process.env.S3_DOWNLOAD_BUCKET
const PRESIGN_TTL_SECONDS = Number.parseInt(process.env.S3_PRESIGN_TTL ?? '300', 10)

const PLATFORM_OBJECT_MAP: Record<string, string | undefined> = {
  'mac-intel': process.env.S3_OBJECT_KEY_MAC_INTEL,
  'mac-arm': process.env.S3_OBJECT_KEY_MAC_ARM,
  'mac-universal': process.env.S3_OBJECT_KEY_MAC_UNIVERSAL,
  windows: process.env.S3_OBJECT_KEY_WINDOWS,
  linux: process.env.S3_OBJECT_KEY_LINUX,
  // Default 'mac' uses universal or falls back to arm (most common now)
  mac: process.env.S3_OBJECT_KEY_MAC_UNIVERSAL ?? process.env.S3_OBJECT_KEY_MAC_ARM
}

function createS3Client() {
  if (!REGION || !ACCESS_KEY_ID || !SECRET_ACCESS_KEY) {
    return null
  }

  return new S3Client({
    region: REGION,
    credentials: {
      accessKeyId: ACCESS_KEY_ID,
      secretAccessKey: SECRET_ACCESS_KEY,
      ...(SESSION_TOKEN && { sessionToken: SESSION_TOKEN })
    }
  })
}

type RouteContext = {
  params: Promise<{ platform: string }>
}

export async function GET(_request: NextRequest, context: RouteContext) {
  const { platform: rawPlatform } = await context.params
  const platform = rawPlatform.toLowerCase()

  // Validate platform
  const objectKey = PLATFORM_OBJECT_MAP[platform]
  if (!objectKey) {
    return NextResponse.json(
      {
        error: 'Unsupported platform',
        supported: Object.keys(PLATFORM_OBJECT_MAP).filter((k) => PLATFORM_OBJECT_MAP[k])
      },
      { status: 404 }
    )
  }

  // Check configuration
  if (!BUCKET_NAME) {
    console.error('[download api] Missing S3_DOWNLOAD_BUCKET configuration')
    return NextResponse.json({ error: 'Download service not configured' }, { status: 503 })
  }

  const s3Client = createS3Client()
  if (!s3Client) {
    console.error('[download api] Missing AWS credentials')
    return NextResponse.json({ error: 'Download service not configured' }, { status: 503 })
  }

  try {
    const filename = objectKey.split('/').pop() ?? 'illog.dmg'

    const command = new GetObjectCommand({
      Bucket: BUCKET_NAME,
      Key: objectKey,
      ResponseContentDisposition: `attachment; filename="${encodeURIComponent(filename)}"`
    })

    const signedUrl = await getSignedUrl(s3Client, command, {
      expiresIn: Number.isFinite(PRESIGN_TTL_SECONDS) ? PRESIGN_TTL_SECONDS : 300
    })

    // Redirect to the presigned URL
    return NextResponse.redirect(signedUrl, 302)
  } catch (error) {
    console.error('[download api] Failed to generate presigned URL', {
      platform,
      objectKey,
      error: error instanceof Error ? error.message : error
    })

    return NextResponse.json(
      { error: 'Failed to prepare download. Please try again later.' },
      { status: 500 }
    )
  }
}

export function validateUrl(url: string): boolean {
  try {
    new URL(url)
    return true
  } catch {
    return false
  }
}

import { differenceInMinutes, endOfWeek, startOfWeek } from 'date-fns'
import { toZonedTime } from 'date-fns-tz'
import type { TaskWithTags } from '../../../shared/types'

// Note: in the future, user can choose week's start (Sun or Mon)
type WEEK_START = 0 | 1

export function getThisWeekDateRange(timeZone: string) {
  const now = new Date()
  const weekStartsOn: WEEK_START = 1

  const currentTimeInTimeZone = toZonedTime(now, timeZone)

  const startOfThisWeek = startOfWeek(currentTimeInTimeZone, { weekStartsOn }).toISOString()
  const endOfThisWeek = endOfWeek(currentTimeInTimeZone, { weekStartsOn }).toISOString()

  return { startOfThisWeek, endOfThisWeek }
}

export function getDurationMinutes(startTime: Date, endTime: Date): number {
  return differenceInMinutes(endTime, startTime)
}

export function getThisWeekTotalHours(tasks: TaskWithTags[]): string {
  let totalMinutes = 0

  for (const { startTime, endTime } of tasks) {
    if (!startTime || !endTime) {
      continue
    }

    totalMinutes += getDurationMinutes(startTime, endTime)
  }

  const hours = Math.floor(totalMinutes / 60)
  const minutes = totalMinutes % 60

  return `${hours}h ${minutes}m`
}

import { getWeek, getYear, format, startOfDay, isSameDay } from 'date-fns'
import type { TaskWithTags } from '../../../shared/types'

export interface WeeklyStats {
  completedCount: number
  totalMinutes: number
  uniqueProjectCount: number
  avgTasksPerDay: number
}

export interface DayTasks {
  date: Date
  dayLabel: string // "Monday, Dec 11"
  tasks: TaskWithTags[]
  totalMinutes: number
}

export function getWeekId(date: Date): string {
  const week = getWeek(date, { weekStartsOn: 1 })
  const year = getYear(date)
  return `${year}-W${week.toString().padStart(2, '0')}`
}

export function getTaskDurationMinutes(task: TaskWithTags): number {
  if (!task.startTime || !task.endTime) return 0

  const start = new Date(task.startTime)
  const end = new Date(task.endTime)
  return Math.max(0, Math.floor((end.getTime() - start.getTime()) / (1000 * 60)))
}

export function formatDuration(minutes: number): string {
  if (minutes === 0) return '0m'

  const hours = Math.floor(minutes / 60)
  const mins = minutes % 60

  if (hours === 0) return `${mins}m`
  if (mins === 0) return `${hours}h`
  return `${hours}h ${mins}m`
}

export function formatHoursDecimal(minutes: number): string {
  const hours = minutes / 60
  return `${hours.toFixed(1)}h`
}

export function calculateWeeklyStats(tasks: TaskWithTags[], weekStart?: Date): WeeklyStats {
  const completedCount = tasks.filter((t) => t.doneAt !== null).length

  const totalMinutes = tasks.reduce((sum, task) => sum + getTaskDurationMinutes(task), 0)

  const uniqueProjects = new Set(tasks.map((t) => t.project?.id).filter(Boolean))
  const uniqueProjectCount = uniqueProjects.size

  let daysInWeek = 7
  if (weekStart) {
    const now = new Date()
    const weekEnd = new Date(weekStart)
    weekEnd.setDate(weekEnd.getDate() + 6)

    if (now < weekEnd) {
      // NOTE: Current or future week: count elapsed days (at least 1)
      const elapsed = Math.floor((now.getTime() - weekStart.getTime()) / (1000 * 60 * 60 * 24)) + 1
      daysInWeek = Math.min(Math.max(elapsed, 1), 7)
    }
  }

  const avgTasksPerDay = completedCount / daysInWeek

  return {
    completedCount,
    totalMinutes,
    uniqueProjectCount,
    avgTasksPerDay
  }
}

export function groupTasksByDay(tasks: TaskWithTags[], startOfWeek: Date): DayTasks[] {
  const days: DayTasks[] = []

  for (let i = 0; i < 7; i++) {
    const date = new Date(startOfWeek)
    date.setDate(date.getDate() + i)
    const dayStart = startOfDay(date)

    const dayTasks = tasks.filter((task) => {
      if (!task.startTime) return false
      const taskDate = startOfDay(new Date(task.startTime))
      return isSameDay(taskDate, dayStart)
    })

    const totalMinutes = dayTasks.reduce((sum, task) => sum + getTaskDurationMinutes(task), 0)

    days.push({
      date: dayStart,
      dayLabel: format(dayStart, 'EEEE, MMM d'), // "Monday, Dec 11"
      tasks: dayTasks,
      totalMinutes
    })
  }

  return days
}

import type { BadgeColor } from '@illog/ui'
import type { TaskWithTags } from '../../../shared/types'
import { getTaskDurationMinutes } from './this-week-stats'

export interface ProjectOverviewMetrics {
  totalTasks: number
  completedTasks: number
  inProgressTasks: number
  todoTasks: number
  completionRate: number // percentage
  totalMinutesSpent: number
}

export interface TaskTypeMetrics {
  id: string
  name: string
  color: BadgeColor
  count: number
  completionRate: number
  avgCompletionMinutes: number | null
  totalMinutes: number
}

export interface SubtypeMetrics {
  id: string
  name: string
  color: BadgeColor
  taskTypeId: string
  taskTypeName: string
  taskTypeColor: BadgeColor
  count: number
  completionRate: number
  totalMinutes: number
}

/**
 * Calculate lead time in minutes from createdAt to doneAt
 * Returns null if task is not completed (doneAt is null)
 */
function calculateLeadTime(task: TaskWithTags): number | null {
  if (!task.doneAt) return null
  const created = new Date(task.createdAt).getTime()
  const done = new Date(task.doneAt).getTime()
  return Math.max(0, Math.floor((done - created) / (1000 * 60))) // minutes
}

/**
 * Calculate project overview metrics
 */
export function calculateProjectOverview(tasks: TaskWithTags[]): ProjectOverviewMetrics {
  const totalTasks = tasks.length
  const completedTasks = tasks.filter((t) => t.status === 'done').length
  const inProgressTasks = tasks.filter((t) => t.status === 'in_progress').length
  const todoTasks = tasks.filter((t) => t.status === 'todo').length

  const completionRate = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0

  // Calculate average lead time for completed tasks
  const totalMinutesSpent = tasks.reduce((sum, task) => sum + getTaskDurationMinutes(task), 0)

  return {
    totalTasks,
    completedTasks,
    inProgressTasks,
    todoTasks,
    completionRate,
    totalMinutesSpent
  }
}

/**
 * Calculate task type metrics including distribution and performance
 */
export function calculateTaskTypeMetrics(tasks: TaskWithTags[]): TaskTypeMetrics[] {
  const typeMap = new Map<
    string,
    {
      id: string
      name: string
      color: BadgeColor
      count: number
      completed: number
      leadTimes: number[]
      totalMinutes: number
    }
  >()

  // Aggregate by task type
  for (const task of tasks) {
    const id = task.taskType?.id ?? 'uncategorized'
    const name = task.taskType?.name ?? 'Uncategorized'
    const color = task.taskType?.color ?? 'gray'

    let entry = typeMap.get(id)
    if (!entry) {
      entry = { id, name, color, count: 0, completed: 0, leadTimes: [], totalMinutes: 0 }
      typeMap.set(id, entry)
    }

    entry.count += 1
    entry.totalMinutes += getTaskDurationMinutes(task)
    if (task.status === 'done') {
      entry.completed += 1
      const leadTime = calculateLeadTime(task)
      if (leadTime !== null) {
        entry.leadTimes.push(leadTime)
      }
    }
  }

  // Convert to metrics array
  return Array.from(typeMap.values()).map((entry) => ({
    id: entry.id,
    name: entry.name,
    color: entry.color,
    count: entry.count,
    completionRate: entry.count > 0 ? (entry.completed / entry.count) * 100 : 0,
    avgCompletionMinutes:
      entry.leadTimes.length > 0
        ? entry.leadTimes.reduce((sum, t) => sum + t, 0) / entry.leadTimes.length
        : null,
    totalMinutes: entry.totalMinutes
  }))
}

/**
 * Calculate subtype metrics for deep analysis
 */
export function calculateSubtypeMetrics(tasks: TaskWithTags[]): SubtypeMetrics[] {
  const subtypeMap = new Map<
    string,
    {
      id: string
      name: string
      color: BadgeColor
      taskTypeId: string
      taskTypeName: string
      taskTypeColor: BadgeColor
      count: number
      completed: number
      leadTimes: number[]
      totalMinutes: number
    }
  >()
  // Aggregate by subtype
  for (const task of tasks) {
    if (!task.taskSubtype) continue

    const id = task.taskSubtype.id
    const name = task.taskSubtype.name
    const color = task.taskSubtype.color ?? 'gray'
    const taskTypeId = task.taskType?.id ?? 'unknown'
    const taskTypeName = task.taskType?.name ?? 'Unknown'
    const taskTypeColor = task.taskType?.color ?? 'gray'

    let entry = subtypeMap.get(id)
    if (!entry) {
      entry = {
        id,
        name,
        color,
        taskTypeId,
        taskTypeName,
        taskTypeColor,
        count: 0,
        completed: 0,
        leadTimes: [],
        totalMinutes: 0
      }
      subtypeMap.set(id, entry)
    }

    entry.count += 1
    entry.totalMinutes += getTaskDurationMinutes(task)
    if (task.status === 'done') {
      entry.completed += 1
      const leadTime = calculateLeadTime(task)
      if (leadTime !== null) {
        entry.leadTimes.push(leadTime)
      }
    }
  }

  // Convert to metrics array
  return Array.from(subtypeMap.values())
    .map((entry) => ({
      id: entry.id,
      name: entry.name,
      color: entry.color,
      taskTypeId: entry.taskTypeId,
      taskTypeName: entry.taskTypeName,
      taskTypeColor: entry.taskTypeColor,
      count: entry.count,
      completionRate: entry.count > 0 ? (entry.completed / entry.count) * 100 : 0,
      totalMinutes: entry.totalMinutes
    }))
    .sort((a, b) => b.count - a.count) // Sort by count descending
}

import { $createHeadingNode, $createQuoteNode, HeadingTagType } from '@lexical/rich-text'
import { $setBlocksType } from '@lexical/selection'
import {
  $addUpdateTag,
  $createParagraphNode,
  $getSelection,
  $isRangeSelection,
  LexicalEditor,
  SKIP_SELECTION_FOCUS_TAG
} from 'lexical'
import {
  INSERT_CHECK_LIST_COMMAND,
  INSERT_ORDERED_LIST_COMMAND,
  INSERT_UNORDERED_LIST_COMMAND
} from '@lexical/list'
import { $createCodeNode } from '@lexical/code'

export const formatParagraph = (editor: LexicalEditor) => {
  editor.update(() => {
    const selection = $getSelection()
    $setBlocksType(selection, () => $createParagraphNode())
  })
}

export const formatHeading = (editor: LexicalEditor, headingSize: HeadingTagType) => {
  editor.update(() => {
    const selection = $getSelection()
    $setBlocksType(selection, () => $createHeadingNode(headingSize))
  })
}

/**
 * Toggle bullet list - if current block is already bullet, convert to paragraph
 * @param editor - Lexical editor instance
 * @param currentBlockType - Current block type from toolbar state
 */
export const formatBulletList = (editor: LexicalEditor, currentBlockType: string) => {
  if (currentBlockType === 'bullet') {
    formatParagraph(editor)
  } else {
    editor.dispatchCommand(INSERT_UNORDERED_LIST_COMMAND, undefined)
  }
}

/**
 * Toggle check list - if current block is already check, convert to paragraph
 */
export const formatCheckList = (editor: LexicalEditor, currentBlockType: string) => {
  if (currentBlockType === 'check') {
    formatParagraph(editor)
  } else {
    editor.dispatchCommand(INSERT_CHECK_LIST_COMMAND, undefined)
  }
}

/**
 * Toggle quote - if current block is already quote, convert to paragraph
 */
export const formatQuote = (editor: LexicalEditor, currentBlockType: string) => {
  if (currentBlockType === 'quote') {
    formatParagraph(editor)
  } else {
    editor.update(() => {
      $addUpdateTag(SKIP_SELECTION_FOCUS_TAG)
      const selection = $getSelection()
      $setBlocksType(selection, () => $createQuoteNode())
    })
  }
}

/**
 * Toggle code block - if current block is already code, convert to paragraph
 */
export const formatCode = (editor: LexicalEditor, currentBlockType: string) => {
  if (currentBlockType === 'code') {
    formatParagraph(editor)
  } else {
    editor.update(() => {
      $addUpdateTag(SKIP_SELECTION_FOCUS_TAG)
      const selection = $getSelection()
      if (!selection) {
        return
      }
      if ($isRangeSelection(selection)) {
        $setBlocksType(selection, () => $createCodeNode())
      } else {
        const textContent = selection.getTextContent()
        const codeNode = $createCodeNode()
        selection.insertNodes([codeNode])
        const newSelection = $getSelection()
        if ($isRangeSelection(newSelection)) {
          newSelection.insertRawText(textContent)
        }
      }
    })
  }
}

/**
 * Toggle numbered list - if current block is already numbered, convert to paragraph
 */
export const formatNumberedList = (editor: LexicalEditor, currentBlockType: string) => {
  if (currentBlockType === 'number') {
    formatParagraph(editor)
  } else {
    editor.dispatchCommand(INSERT_ORDERED_LIST_COMMAND, undefined)
  }
}

import { $getSelection, $isRangeSelection, $isTextNode, LexicalNode } from 'lexical'

export const FLOATING_TOOLBAR_CONFIG = {
  verticalGap: 10,
  horizontalPadding: 5
} as const

export interface FloatingPosition {
  top: number
  left: number
  opacity: '0' | '1'
}

export function getDOMRangeRect(
  nativeSelection: Selection,
  rootElement: HTMLElement
): DOMRect | null {
  // 1. If there is no selection range, return null
  if (nativeSelection.rangeCount === 0) {
    return null
  }

  const domRange = nativeSelection.getRangeAt(0)

  // 2. If empty Editor: Selection points directly to root
  if (nativeSelection.anchorNode === rootElement) {
    let inner = rootElement
    while (inner.firstElementChild != null) {
      inner = inner.firstElementChild as HTMLElement
    }
    return inner.getBoundingClientRect()
  }

  // 3. Return selected text range
  return domRange.getBoundingClientRect()
}

/**
 *
 * Depends on selection direction
 * - Forward selection: prioritize anchor node
 * - Backward selection: prioritize focus node
 *
 * "Hello" → "World"    "Hello" ← "World"
 *    ↑        ↑           ↑        ↑
 *  anchor   focus       focus    anchor
 */
export function getSelectedNode(selection: ReturnType<typeof $getSelection>): LexicalNode | null {
  if (!$isRangeSelection(selection)) return null

  const anchorNode = selection.anchor.getNode()
  const focusNode = selection.focus.getNode()

  if (anchorNode === focusNode) {
    return anchorNode
  }

  const isBackward = selection.isBackward()
  if (isBackward) {
    return $isTextNode(focusNode) ? focusNode : anchorNode
  } else {
    return $isTextNode(anchorNode) ? anchorNode : focusNode
  }
}

export function setFloatingElemPosition(
  targetRect: DOMRect | null,
  floatingElem: HTMLElement,
  anchorElem: HTMLElement
): void {
  const scrollerElem = anchorElem.parentElement
  const { verticalGap, horizontalPadding } = FLOATING_TOOLBAR_CONFIG

  if (targetRect === null || !scrollerElem) {
    floatingElem.style.opacity = '0'
    floatingElem.style.transform = 'translate(-10000px, -10000px)'
    return
  }

  const floatingElemRect = floatingElem.getBoundingClientRect()
  const anchorElementRect = anchorElem.getBoundingClientRect()
  const editorScrollerRect = scrollerElem.getBoundingClientRect()

  // 1. Basic position: above the selection, centered
  let top = targetRect.top - floatingElemRect.height - verticalGap
  let left = targetRect.left + targetRect.width / 2 - floatingElemRect.width / 2

  // 2. Flip below if top boundary collision
  if (top < editorScrollerRect.top) {
    top = targetRect.bottom + verticalGap
  }

  // 3. Handle left boundary
  if (left < editorScrollerRect.left) {
    left = editorScrollerRect.left + horizontalPadding
  }

  // 4. Handle right boundary
  if (left + floatingElemRect.width > editorScrollerRect.right) {
    left = editorScrollerRect.right - floatingElemRect.width - horizontalPadding
  }

  // 5. Calculate relative position based on anchorElement (Editor wrapper)
  top -= anchorElementRect.top
  left -= anchorElementRect.left

  floatingElem.style.opacity = '1'
  floatingElem.style.transform = `translate(${left}px, ${top}px)`
}

import { BadgeColor } from '@illog/ui'
import type { TaskWithTags } from '../../../shared/types'
import { getTaskDurationMinutes } from './this-week-stats'

export type ChartSegment = {
  id: string
  name: string
  color: BadgeColor
  taskCount: number
  totalMinutes: number
  percentage: number
}

export type ViewMode = 'project' | 'taskType' | 'subtype'

export const ETC_SEGMENT_ID = 'etc'
export const ETC_FILTER_ID = '__etc__' as const

export type CategorySelection = {
  id: string | typeof ETC_FILTER_ID
  name: string
}

export type AnalyticsFilter = {
  viewMode: ViewMode
  selectedCategory: CategorySelection | null
  selectedSubcategory: CategorySelection | null
}

export const INITIAL_FILTER: AnalyticsFilter = {
  viewMode: 'project',
  selectedCategory: null,
  selectedSubcategory: null
}

function aggregateToSegments(
  tasks: TaskWithTags[],
  getKey: (task: TaskWithTags) => string,
  getName: (task: TaskWithTags) => string,
  getColor: (task: TaskWithTags) => BadgeColor
): ChartSegment[] {
  const map = new Map<
    string,
    { id: string; name: string; color: BadgeColor; taskCount: number; totalMinutes: number }
  >()

  let grandTotal = 0

  for (const task of tasks) {
    const id = getKey(task)
    const minutes = getTaskDurationMinutes(task)
    grandTotal += minutes

    const existing = map.get(id)
    if (existing) {
      existing.taskCount += 1
      existing.totalMinutes += minutes
    } else {
      map.set(id, {
        id,
        name: getName(task),
        color: getColor(task),
        taskCount: 1,
        totalMinutes: minutes
      })
    }
  }

  return Array.from(map.values())
    .map((entry) => ({
      ...entry,
      percentage: grandTotal > 0 ? (entry.totalMinutes / grandTotal) * 100 : 0
    }))
    .sort((a, b) => b.totalMinutes - a.totalMinutes)
}

function groupByProject(tasks: TaskWithTags[]): ChartSegment[] {
  return aggregateToSegments(
    tasks,
    (t) => t.project?.id ?? ETC_SEGMENT_ID,
    (t) => t.project?.name ?? ETC_SEGMENT_ID,
    (t) => t.project?.color ?? 'gray'
  )
}

function groupByTaskType(tasks: TaskWithTags[]): ChartSegment[] {
  return aggregateToSegments(
    tasks,
    (t) => t.taskType?.id ?? ETC_SEGMENT_ID,
    (t) => t.taskType?.name ?? ETC_SEGMENT_ID,
    (t) => t.taskType?.color ?? 'gray'
  )
}

function groupBySubtype(tasks: TaskWithTags[]): ChartSegment[] {
  return aggregateToSegments(
    tasks,
    (t) => t.taskSubtype?.id ?? ETC_SEGMENT_ID,
    (t) => t.taskSubtype?.name ?? ETC_SEGMENT_ID,
    (t) => t.taskSubtype?.color ?? 'gray'
  )
}

function filterByProject(tasks: TaskWithTags[], id: string | '__etc__'): TaskWithTags[] {
  if (id === ETC_FILTER_ID) return tasks.filter((t) => t.project === null)
  return tasks.filter((t) => t.project?.id === id)
}

function filterByTaskType(tasks: TaskWithTags[], id: string | '__etc__'): TaskWithTags[] {
  if (id === ETC_FILTER_ID) return tasks.filter((t) => t.taskType === null)
  return tasks.filter((t) => t.taskType?.id === id)
}

function filterBySubtype(tasks: TaskWithTags[], id: string | '__etc__'): TaskWithTags[] {
  if (id === ETC_FILTER_ID) return tasks.filter((t) => t.taskSubtype === null)
  return tasks.filter((t) => t.taskSubtype?.id === id)
}

export function getStatsForFilterLevel(
  tasks: TaskWithTags[],
  filter: AnalyticsFilter
): ChartSegment[] {
  const { viewMode, selectedCategory, selectedSubcategory } = filter

  if (viewMode === 'project') {
    if (!selectedCategory) return groupByProject(tasks)
    const byProject = filterByProject(tasks, selectedCategory.id)
    if (!selectedSubcategory) return groupByTaskType(byProject)
    return groupBySubtype(filterByTaskType(byProject, selectedSubcategory.id))
  }

  if (viewMode === 'taskType') {
    if (!selectedCategory) return groupByTaskType(tasks)
    const byType = filterByTaskType(tasks, selectedCategory.id)
    if (!selectedSubcategory) return groupByProject(byType)
    return groupBySubtype(filterByProject(byType, selectedSubcategory.id))
  }

  if (!selectedCategory) return groupBySubtype(tasks)
  return groupByProject(filterBySubtype(tasks, selectedCategory.id))
}

export function isLeafLevel(filter: AnalyticsFilter): boolean {
  if (filter.viewMode === 'subtype') return filter.selectedCategory !== null
  return filter.selectedSubcategory !== null
}

export function getLevelLabel(filter: AnalyticsFilter): string {
  const { viewMode, selectedCategory, selectedSubcategory } = filter

  if (viewMode === 'project') {
    if (!selectedCategory) return 'By Project'
    if (!selectedSubcategory) return 'By Task Type'
    return 'By Subtype'
  }

  if (viewMode === 'taskType') {
    if (!selectedCategory) return 'By Task Type'
    if (!selectedSubcategory) return 'By Project'
    return 'By Subtype'
  }

  if (!selectedCategory) return 'By Subtype'
  return 'By Project'
}

export function getCategoryLabel(filter: AnalyticsFilter): string {
  const { viewMode, selectedCategory } = filter

  if (!selectedCategory) return ''

  if (viewMode === 'project') return 'Project'
  if (viewMode === 'taskType') return 'Task Type'
  return 'Subtype'
}

export function getSubcategoryLabel(filter: AnalyticsFilter): string {
  const { viewMode, selectedCategory, selectedSubcategory } = filter

  if (!selectedSubcategory) return ''

  if (viewMode === 'project') {
    return selectedCategory ? 'Task Type' : ''
  }

  if (viewMode === 'taskType') {
    return selectedCategory ? 'Project' : ''
  }

  return ''
}

export function getBreadcrumbRoot(viewMode: ViewMode): string {
  if (viewMode === 'project') return 'All Projects'
  if (viewMode === 'taskType') return 'All Task Types'
  return 'All Sub Types'
}

export function getFilteredTasks(tasks: TaskWithTags[], filter: AnalyticsFilter): TaskWithTags[] {
  const { viewMode, selectedCategory, selectedSubcategory } = filter

  let filtered = tasks

  if (viewMode === 'project') {
    if (selectedCategory) filtered = filterByProject(filtered, selectedCategory.id)
    if (selectedSubcategory) filtered = filterByTaskType(filtered, selectedSubcategory.id)
  } else if (viewMode === 'taskType') {
    if (selectedCategory) filtered = filterByTaskType(filtered, selectedCategory.id)
    if (selectedSubcategory) filtered = filterByProject(filtered, selectedSubcategory.id)
  } else {
    if (selectedCategory) filtered = filterBySubtype(filtered, selectedCategory.id)
  }

  return filtered
}

import { addDays, isAfter, isBefore, startOfDay } from 'date-fns'
import { TaskWithTags } from '../types'
import { CalendarTask, LayoutColumn } from '../types/calendar'
import {
  BackgroundColorToken,
  formatTimeLabel,
  getMinutesFromMidnight,
  TextColorToken
} from '@illog/ui'
import type { TimeCellColor } from '@illog/ui'

const MINUTES_IN_DAY = 24 * 60

/**
 * Given a list of tasks and a specific date, returns CalendarTask entries
 * for that date. Multi-day tasks are split:
 *  - Start day:  startTime → midnight
 *  - Middle day: 00:00 → 23:59
 *  - End day:    00:00 → endTime
 *  - Same day:   startTime → endTime
 */
export function getCalendarTasksForDate(tasks: TaskWithTags[], targetDate: Date): CalendarTask[] {
  const dayStart = startOfDay(targetDate)
  const dayEnd = startOfDay(addDays(targetDate, 1))

  return tasks
    .filter((task) => task.startTime && task.endTime)
    .reduce<CalendarTask[]>((acc, task) => {
      const taskStart = new Date(task.startTime!)
      const taskEnd = new Date(task.endTime!)

      if (taskEnd <= dayStart || taskStart >= dayEnd) return acc

      const visibleStart = isBefore(taskStart, dayStart) ? dayStart : taskStart
      const visibleEnd = isAfter(taskEnd, dayEnd) ? dayEnd : taskEnd

      const startMinutes = getMinutesFromMidnight(visibleStart)
      const endMinutes =
        visibleEnd.getTime() === dayEnd.getTime()
          ? MINUTES_IN_DAY
          : getMinutesFromMidnight(visibleEnd)

      const durationMinutes = Math.max(endMinutes - startMinutes, 15)
      acc.push({ task, startMinutes, durationMinutes })
      return acc
    }, [])
    .sort((a, b) => a.startMinutes - b.startMinutes)
}

export function getLayoutColumns(calendarTasks: CalendarTask[]): LayoutColumn[] {
  if (calendarTasks.length === 0) return []

  // 1. Group tasks by overlap
  const groups: CalendarTask[][] = []
  let currentGroup: CalendarTask[] = []
  let currentGroupEnd = 0

  for (const ct of calendarTasks) {
    // 현재 task 의 시작 시간이 현재 그룹의 끝나는 시간보다 빠르면 -> 겹침
    if (currentGroup.length === 0 || ct.startMinutes < currentGroupEnd) {
      currentGroup.push(ct)
      currentGroupEnd = Math.max(currentGroupEnd, ct.startMinutes + ct.durationMinutes)
    } else {
      groups.push(currentGroup)
      currentGroup = [ct]
      currentGroupEnd = ct.startMinutes + ct.durationMinutes
    }
  }
  if (currentGroup.length > 0) groups.push(currentGroup)

  // 2. Greedy column packing
  const result: LayoutColumn[] = []
  for (const group of groups) {
    const columns: CalendarTask[][] = []

    for (const ct of group) {
      let placed = false
      for (let colIdx = 0; colIdx < columns.length; colIdx++) {
        const lastInColumn = columns[colIdx][columns[colIdx].length - 1]
        // 현재 컬럼의 마지막 task 의 끝나는 시간이 현재 task의 시작 시간보다 빠르면 -> 같은 컬럼에 배치 가능
        if (lastInColumn.startMinutes + lastInColumn.durationMinutes <= ct.startMinutes) {
          columns[colIdx].push(ct)
          placed = true
          break
        }
      }
      // 모든 기존 컬럼에 배치 불가능하면 새로운 컬럼 생성
      if (!placed) columns.push([ct])
    }

    // 3. Assign column index and total columns for each task
    const totalColumns = columns.length
    for (let colIdx = 0; colIdx < columns.length; colIdx++) {
      for (const ct of columns[colIdx]) {
        result.push({ calendarTask: ct, columnIndex: colIdx, totalColumns })
      }
    }
  }

  return result
}

export function getTimeCellText(task: TaskWithTags): { subtitle?: string; caption?: string } {
  const subtitle =
    task.startTime && task.endTime
      ? `${formatTimeLabel(new Date(task.startTime))} – ${formatTimeLabel(new Date(task.endTime))}`
      : undefined
  const caption = task.taskType
    ? `${task.taskType.name}${task.project ? ` · ${task.project.name}` : ''}`
    : undefined

  return { subtitle, caption }
}

const BG_TOKEN_MAP: Record<string, BackgroundColorToken> = {
  blue: 'backgroundTagBlue',
  green: 'backgroundTagGreen',
  yellow: 'backgroundTagYellow',
  purple: 'backgroundTagPurple',
  red: 'backgroundTagRed',
  gray: 'backgroundTagGray'
}

const BORDER_COLOR_MAP: Record<string, string> = {
  blue: 'var(--text-tag-blue)',
  green: 'var(--text-tag-green)',
  yellow: 'var(--text-tag-yellow)',
  purple: 'var(--text-tag-purple)',
  red: 'var(--text-tag-red)',
  gray: 'var(--text-tag-gray)'
}

const TEXT_TOKEN_MAP: Record<string, TextColorToken> = {
  blue: 'textTagBlue',
  green: 'textTagGreen',
  yellow: 'textTagYellow',
  purple: 'textTagPurple',
  red: 'textTagRed',
  gray: 'textTagGray'
}

export function getTaskColor(task: TaskWithTags): TimeCellColor {
  const colorKey = task.taskType?.color
  if (colorKey) {
    const bg = BG_TOKEN_MAP[colorKey]
    const border = BORDER_COLOR_MAP[colorKey]
    const text = TEXT_TOKEN_MAP[colorKey]
    if (bg && border && text) {
      return { bg, border, text }
    }
  }
  return {
    bg: 'backgroundBrandTertiary' as BackgroundColorToken,
    border: 'var(--border-brand-default)',
    text: 'textDefaultDefault' as TextColorToken
  }
}

export function getTimeCellStyle({
  startMinutes,
  durationMinutes,
  task,
  columnIndex,
  totalColumns,
  hourHeight,
  gutterWidth
}: {
  startMinutes: number
  durationMinutes: number
  task: TaskWithTags
  columnIndex: number
  totalColumns: number
  hourHeight: number
  gutterWidth: number
}) {
  const top = (startMinutes / 60) * hourHeight
  const height = Math.max((durationMinutes / 60) * hourHeight, 22)
  const colors = getTaskColor(task)

  const gutterLeft = gutterWidth + 8
  const rightPad = 8
  const colWidthPercent = 100 / totalColumns
  const leftPercent = columnIndex * colWidthPercent
  const gap = totalColumns > 1 ? 2 : 0

  const left = `calc(${gutterLeft}px + (100% - ${gutterLeft + rightPad}px) * ${leftPercent / 100})`
  const width = `calc((100% - ${gutterLeft + rightPad}px) * ${colWidthPercent / 100} - ${gap}px)`

  return { top, height, colors, left, width }
}

