import { useMemo, useEffect } from 'react'
import { useAllProjects, useProject } from './queries/useProjectQueries'
import { useTasksByFilters } from './queries/useTaskQueries'
import { useUIStore } from '../stores/useUIStore'
import {
  calculateProjectOverview,
  calculateTaskTypeMetrics,
  calculateSubtypeMetrics
} from '../utils/project-insights'
import type { TaskFilterParams } from '../../../shared/types'

const selectProjectId = (s: { currentSelectedProjectId: string | undefined }) =>
  s.currentSelectedProjectId
const selectSetProjectId = (s: { setCurrentSelectedProjectId: (id: string) => void }) =>
  s.setCurrentSelectedProjectId

export function useProjects() {
  const selectedProjectId = useUIStore(selectProjectId)
  const setSelectedProjectId = useUIStore(selectSetProjectId)

  const { data: projects = [], isLoading: isProjectsLoading } = useAllProjects()
  const { data: project } = useProject(selectedProjectId ?? '')

  // Auto-select first project if none selected
  useEffect(() => {
    if (projects.length > 0 && !selectedProjectId) {
      setSelectedProjectId(projects[0].id)
    }
  }, [projects, selectedProjectId, setSelectedProjectId])

  const taskFilters = useMemo<TaskFilterParams>(
    () => ({ projectId: selectedProjectId ?? undefined }),
    [selectedProjectId]
  )

  const { data: tasks = [], isLoading: isTasksLoading, error } = useTasksByFilters(taskFilters)

  const overviewMetrics = useMemo(() => calculateProjectOverview(tasks), [tasks])
  const taskTypeMetrics = useMemo(() => calculateTaskTypeMetrics(tasks), [tasks])
  const subtypeMetrics = useMemo(() => calculateSubtypeMetrics(tasks), [tasks])

  const isLoading = isProjectsLoading || isTasksLoading

  return {
    projects,
    selectedProjectId,
    setSelectedProjectId,
    project,

    tasks,
    isLoading,
    error,

    overviewMetrics,
    taskTypeMetrics,
    subtypeMetrics
  } as const
}

import { useEffect } from 'react'
import { useCrashReportSettings, useSendCrashReport } from './queries'
import { useCrashReportStore } from '../stores/useCrashReportStore'

export const useGlobalErrorHandler = () => {
  const { data: settings } = useCrashReportSettings()
  const { mutate: sendReport } = useSendCrashReport()
  const showCrashDialog = useCrashReportStore((s) => s.showCrashDialog)

  useEffect(() => {
    const handleError = (event: ErrorEvent) => {
      const errorPayload = {
        message: event.error?.message || event.message,
        stack: event.error?.stack
      }

      if (settings?.enabled) {
        sendReport(errorPayload)
      } else {
        showCrashDialog(errorPayload)
      }
    }

    const handleUnhandledRejection = (event: PromiseRejectionEvent) => {
      const error = event.reason instanceof Error ? event.reason : new Error(String(event.reason))
      const errorPayload = {
        message: error.message,
        stack: error.stack
      }

      if (settings?.enabled) {
        sendReport(errorPayload)
      } else {
        showCrashDialog(errorPayload)
      }
    }

    window.addEventListener('error', handleError)
    window.addEventListener('unhandledrejection', handleUnhandledRejection)

    return () => {
      window.removeEventListener('error', handleError)
      window.removeEventListener('unhandledrejection', handleUnhandledRejection)
    }
  }, [settings, sendReport, showCrashDialog])
}

import { useMemo } from 'react'
import type { FeatureId, FeatureFlag } from '../types'
import { useUserPlanInfo } from './queries/useUserQueries'

/**
 * @example
 * const { enabled, requiredPlan, isLoading } = useFeatureFlag('ai.reflection')
 * if (!enabled) return <ProBadge requiredPlan={requiredPlan} />
 */
export function useFeatureFlag(featureId: FeatureId) {
  const { data, isLoading } = useUserPlanInfo()

  return useMemo(() => {
    if (!data) {
      return { enabled: false, requiredPlan: undefined, isLoading }
    }

    const flag: FeatureFlag | undefined = data.features.find((f) => f.id === featureId)

    return {
      enabled: flag?.enabled ?? false,
      requiredPlan: flag?.requiredPlan,
      isLoading
    }
  }, [data, featureId, isLoading])
}

/**
 * @example
 * const flags = useFeatureFlags(['ai.reflection', 'ai.suggestion'])
 * flags['ai.reflection'].enabled // boolean
 */
export function useFeatureFlags(featureIds: FeatureId[]) {
  const { data, isLoading } = useUserPlanInfo()

  return useMemo(() => {
    const result: Record<string, { enabled: boolean; requiredPlan?: string }> = {}

    for (const id of featureIds) {
      if (!data) {
        result[id] = { enabled: false, requiredPlan: undefined }
        continue
      }
      const flag = data.features.find((f) => f.id === id)
      result[id] = {
        enabled: flag?.enabled ?? false,
        requiredPlan: flag?.requiredPlan
      }
    }

    return { flags: result, isLoading }
  }, [data, featureIds, isLoading])
}

/**
 * @example
 * const { plan, isLocal } = useCurrentPlan()
 */
export function useCurrentPlan() {
  const { data, isLoading } = useUserPlanInfo()

  return useMemo(
    () => ({
      plan: data?.profile.plan ?? 'local',
      isLocal: !data || data.profile.plan === 'local',
      profile: data?.profile ?? null,
      isLoading
    }),
    [data, isLoading]
  )
}

import { ChangeEvent, useEffect, useRef, useState } from 'react'

import { useTaskNote, useAutoSaveNote as useAutoSaveNoteMutation } from './queries/useNoteQueries'
import type { TaskNote } from '../types'

export const useAutoSaveNote = (
  currentTaskId: string | undefined
): [
  note: TaskNote | null,
  handleChange: (e: ChangeEvent<HTMLTextAreaElement | HTMLInputElement>) => void
] => {
  const { data: fetchedNote } = useTaskNote(currentTaskId)
  const { mutate: saveNote } = useAutoSaveNoteMutation()

  const [localContent, setLocalContent] = useState<string>(() => fetchedNote?.content || '')
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    // NOTE: Since external data and local state synchronization is needed, useEffect is appropriate
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setLocalContent(fetchedNote?.content || '')
  }, [currentTaskId, fetchedNote])

  const handleChange = (e: ChangeEvent<HTMLTextAreaElement | HTMLInputElement>) => {
    const { value } = e.target
    setLocalContent(value)

    if (timeoutRef.current) clearTimeout(timeoutRef.current)

    timeoutRef.current = setTimeout(() => {
      if (currentTaskId) {
        saveNote({
          taskId: currentTaskId,
          content: value,
          clientUpdatedAt: Date.now()
        })
      }
    }, 1000)
  }

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current)
    }
  }, [])

  const note: TaskNote | null = fetchedNote
    ? { ...fetchedNote, content: localContent }
    : currentTaskId
      ? { taskId: currentTaskId, content: localContent, updatedAt: new Date().toISOString() }
      : null

  return [note, handleChange]
}

import { useState, useCallback, useMemo } from 'react'
import {
  INITIAL_FILTER,
  isLeafLevel,
  ETC_SEGMENT_ID,
  ETC_FILTER_ID,
  type AnalyticsFilter,
  type ViewMode,
  type ChartSegment
} from '../utils/category-analytics'

export function useAnalyticsFilter() {
  const [filter, setFilter] = useState<AnalyticsFilter>(INITIAL_FILTER)

  const setViewMode = useCallback((viewMode: ViewMode) => {
    setFilter({ viewMode, selectedCategory: null, selectedSubcategory: null })
  }, [])

  const selectCategory = useCallback((id: string | '__etc__', name: string) => {
    setFilter((prev) => ({ ...prev, selectedCategory: { id, name }, selectedSubcategory: null }))
  }, [])

  const selectSubCategory = useCallback((id: string | '__etc__', name: string) => {
    setFilter((prev) => ({ ...prev, selectedSubcategory: { id, name } }))
  }, [])

  const goBackToCategory = useCallback(() => {
    setFilter((prev) => ({ ...prev, selectedSubcategory: null }))
  }, [])

  const resetCategory = useCallback(() => {
    setFilter((prev) => ({ ...prev, selectedCategory: null, selectedSubcategory: null }))
  }, [])

  const isLeaf = useMemo(() => isLeafLevel(filter), [filter])

  const handleSegmentClick = useCallback(
    (segment: ChartSegment) => {
      if (isLeafLevel(filter)) return
      const id = segment.id === ETC_SEGMENT_ID ? ETC_FILTER_ID : segment.id
      if (!filter.selectedCategory) {
        selectCategory(id, segment.name)
      } else {
        selectSubCategory(id, segment.name)
      }
    },
    [filter, selectCategory, selectSubCategory]
  )

  return {
    filter,
    isLeaf,
    setViewMode,
    selectCategory,
    selectSubCategory,
    goBackToCategory,
    resetCategory,
    handleSegmentClick
  }
}

