import { useCallback, useEffect, useRef } from 'react'
import { BasicSelectorContentProps } from './types'
import { Portal } from '../../Portal'
import clsx from 'clsx'
import { useBasicSelectorContext } from './context'
import { useClickOutside } from 'packages/ui/src/hooks'
import { content as contentStyle } from './basicSelector.css.js'

export const Content = ({
  position = 'item-aligned',
  side = 'bottom',
  sideOffset = 0,
  children,
  className
}: BasicSelectorContentProps) => {
  const { isOpened, onOpenChange, triggerRef } = useBasicSelectorContext()
  const localRef = useRef<HTMLDivElement | null>(null)

  const handleClickOutside = useCallback(() => {
    if (isOpened) {
      onOpenChange(false)
    }
  }, [isOpened, onOpenChange])

  useClickOutside({
    refs: [localRef, triggerRef],
    onClickOutside: handleClickOutside
  })

  useEffect(() => {
    if (!isOpened || !localRef.current || !triggerRef.current) return

    const trigger = triggerRef.current
    const content = localRef.current

    const updatePosition = () => {
      const triggerRect = trigger.getBoundingClientRect()

      if (position === 'popover') {
        let top = 0
        let left = triggerRect.left

        switch (side) {
          case 'top':
            top = triggerRect.top - content.offsetHeight - sideOffset
            break
          case 'bottom':
            top = triggerRect.bottom + sideOffset
            break
          case 'left':
            top = triggerRect.top
          case 'right':
            top = triggerRect.top
            left = triggerRect.right + sideOffset
            break
        }
        content.style.top = `${top}px`
        content.style.left = `${left}px`
      } else {
        content.style.top = `${triggerRect.bottom + sideOffset}px`
        content.style.left = `${triggerRect.left}px`
        content.style.minWidth = `${triggerRect.width}px`
      }
    }

    updatePosition()

    window.addEventListener('resize', updatePosition)
    window.addEventListener('scroll', updatePosition, true)

    return () => {
      window.removeEventListener('resize', updatePosition)
      window.removeEventListener('scroll', updatePosition, true)
    }
  }, [isOpened, sideOffset, side, position, triggerRef])

  if (!isOpened) return null

  return (
    <Portal>
      <div
        ref={localRef}
        role="listbox"
        data-state={isOpened ? 'open' : 'closed'}
        className={clsx(contentStyle, className)}
      >
        {children}
      </div>
    </Portal>
  )
}

import { describe, expect, it, vi } from 'vitest'
import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { BasicSelector } from './index'

const renderBasicSelector = ({
  defaultValue = '',
  value,
  onValueChange,
  disabled = false
}: {
  defaultValue?: string
  value?: string
  onValueChange?: (v: string) => void
  disabled?: boolean
} = {}) => {
  return render(
    <BasicSelector.Root
      defaultValue={defaultValue}
      value={value}
      disabled={disabled}
      onValueChange={onValueChange}
    >
      <BasicSelector.Trigger ariaLabel="Select option">
        <BasicSelector.Value placeholder="Select..." />
      </BasicSelector.Trigger>
      <BasicSelector.Content>
        <BasicSelector.Viewport>
          <BasicSelector.Item value="apple">Apple</BasicSelector.Item>
          <BasicSelector.Item value="banana">Banana</BasicSelector.Item>
          <BasicSelector.Item value="cherry" disabled>
            Cherry (disabled)
          </BasicSelector.Item>
        </BasicSelector.Viewport>
      </BasicSelector.Content>
    </BasicSelector.Root>
  )
}

describe('BasicSelector', () => {
  it('renders the trigger', () => {
    renderBasicSelector()
    expect(screen.getByRole('combobox')).toBeInTheDocument()
  })

  it('shows placeholder when no value selected', () => {
    renderBasicSelector()
    expect(screen.getByText('Select...')).toBeInTheDocument()
  })

  it('content is not visible initially', () => {
    renderBasicSelector()
    expect(screen.queryByRole('listbox')).not.toBeInTheDocument()
  })

  it('opens content on trigger click', async () => {
    const user = userEvent.setup()
    renderBasicSelector()

    await user.click(screen.getByRole('combobox'))
    expect(screen.getByRole('listbox')).toBeInTheDocument()
  })

  it('shows all options when open', async () => {
    const user = userEvent.setup()
    renderBasicSelector()

    await user.click(screen.getByRole('combobox'))
    expect(screen.getByRole('option', { name: 'Apple' })).toBeInTheDocument()
    expect(screen.getByRole('option', { name: 'Banana' })).toBeInTheDocument()
  })

  it('selects an item on click and calls onValueChange', async () => {
    const user = userEvent.setup()
    const onValueChange = vi.fn()
    renderBasicSelector({ onValueChange })

    await user.click(screen.getByRole('combobox'))
    await user.click(screen.getByRole('option', { name: 'Apple' }))

    expect(onValueChange).toHaveBeenCalledWith('apple')
  })

  it('closes content after item selection', async () => {
    const user = userEvent.setup()
    renderBasicSelector()

    await user.click(screen.getByRole('combobox'))
    await user.click(screen.getByRole('option', { name: 'Apple' }))

    expect(screen.queryByRole('listbox')).not.toBeInTheDocument()
