    ...item
  })

  const handleNameChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    setCurrentItem((prev) => ({ ...prev, name: e.target.value }))
    onChange(currentItem.id, { name: e.target.value, color: currentItem.color })
