  }

  const handleDelete = async () => {
    onDelete(currentItem.id)
  }

  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      onChange(currentItem.id, { name: currentItem.name, color: currentItem.color })
      onCloseEditor()
