import { RefObject, useCallback, useRef } from 'react'

const ITEM_SELECTOR =
  '[role="menuitem"]:not([data-disabled]), [role="menuitemcheckbox"]:not([data-disabled]), [role="menuitemradio"]:not([data-disabled])'

type Props = {
  containerRef: RefObject<HTMLElement | null>
  isLoop: boolean
}

export function useRovingFocus({ containerRef, isLoop }: Props) {
  const highlightedRef = useRef<HTMLElement | null>(null)

  const getItems = useCallback(() => {
    if (!containerRef.current) return []
    return Array.from(containerRef.current.querySelectorAll(ITEM_SELECTOR)) as HTMLElement[]
  }, [containerRef])

  const clearHighlight = useCallback(() => {
    if (highlightedRef.current) {
      highlightedRef.current.removeAttribute('data-highlighted')
      highlightedRef.current = null
    }
  }, [])

  const highlight = useCallback(
    (index: number) => {
      const items = getItems()
      clearHighlight()

      if (index >= 0 && index < items.length) {
        const item = items[index]
        item.setAttribute('data-highlighted', '')
        item.focus()
        highlightedRef.current = item
      }
    },
    [getItems, clearHighlight]
  )

  const getHighlightedIndex = useCallback(() => {
    if (!highlightedRef.current) return -1
    const items = getItems()
    return items.indexOf(highlightedRef.current)
  }, [getItems])

  const highlightNext = useCallback(() => {
    const items = getItems()
    if (items.length === 0) return
    const current = getHighlightedIndex()
    let next = current + 1
    if (next >= items.length) {
      next = isLoop ? 0 : items.length - 1
    }
    highlight(next)
  }, [getItems, getHighlightedIndex, highlight, isLoop])

  const highlightPrev = useCallback(() => {
    const items = getItems()
    if (items.length === 0) return
    const current = getHighlightedIndex()
    let prev = current - 1
    if (prev < 0) {
      prev = isLoop ? items.length - 1 : 0
    }
    highlight(prev)
  }, [getItems, getHighlightedIndex, highlight, isLoop])

  const highlightFirst = useCallback(() => highlight(0), [highlight])

  const highlightLast = useCallback(() => {
    const items = getItems()
    highlight(items.length - 1)
  }, [getItems, highlight])

  const highlightByElement = useCallback(
    (element: HTMLElement) => {
      clearHighlight()
      element.setAttribute('data-highlighted', '')
      highlightedRef.current = element
      element.focus()
    },
    [clearHighlight]
  )

  return {
    getItems,
    getHighlightedIndex,
    highlightedRef,
    highlight,
    highlightNext,
    highlightPrev,
    highlightFirst,
    highlightLast,
    highlightByElement,
    clearHighlight
  }
}

import { KeyboardEvent, PointerEvent, RefObject, useCallback, useRef } from 'react'
import { useContextMenuSubContext } from '../context/subContext'
import { ContextMenuSubTriggerProps } from '../types'
import { Icon } from '../../Icon'
import { subTrigger as subTriggerStyle } from '../contextMenu.css'
import clsx from 'clsx'

const OPEN_DELAY = 100
const CLOSE_DELAY = 150

export const SubTrigger = ({
  isDisabled,
  textValue,
  className,
  style,
  children
}: ContextMenuSubTriggerProps) => {
  const { onOpenChange, isOpen, triggerRef, contentRef } = useContextMenuSubContext()
  const openTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const clearOpenTimer = useCallback(() => {
    if (openTimerRef.current) {
      clearTimeout(openTimerRef.current)
      openTimerRef.current = null
    }
  }, [])

  const clearCloseTimer = useCallback(() => {
    if (closeTimerRef.current) {
      clearTimeout(closeTimerRef.current)
      closeTimerRef.current = null
    }
  }, [])

  const handlePointerEnter = useCallback(() => {
    if (isDisabled) return
    clearOpenTimer()
    clearCloseTimer()
    openTimerRef.current = setTimeout(() => {
      onOpenChange(true)
    }, OPEN_DELAY)
  }, [isDisabled, onOpenChange, clearOpenTimer, clearCloseTimer])

  const handlePointerLeave = useCallback(
    (e: PointerEvent) => {
      clearOpenTimer()
      const relatedTarget = e.relatedTarget as HTMLElement | null

      if (relatedTarget && contentRef.current?.contains(relatedTarget)) return
      closeTimerRef.current = setTimeout(() => {
        onOpenChange(false)
      }, CLOSE_DELAY)
    },
    [clearOpenTimer, onOpenChange, contentRef]
  )

  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (isDisabled) return
      if (e.key === 'ArrowRight') {
        e.preventDefault()
        e.stopPropagation()
        onOpenChange(true)
      }
    },
    [isDisabled, onOpenChange]
  )

  return (
    <div
      ref={triggerRef as RefObject<HTMLDivElement>}
      role="menuitem"
      aria-haspopup="menu"
      aria-expanded={isOpen}
      aria-disabled={isDisabled || undefined}
      tabIndex={isDisabled ? undefined : -1}
      data-state={isOpen ? 'open' : 'closed'}
      data-disabled={isDisabled ? '' : undefined}
      data-value={textValue}
      className={clsx(subTriggerStyle, className)}
      style={style}
      onPointerEnter={handlePointerEnter}
      onPointerLeave={handlePointerLeave}
      onKeyDown={handleKeyDown}
    >
      {children}
      <Icon name="chevron_down" size="small" rotate={-90} />
    </div>
  )
}

import { useCallback, useMemo, useRef, useState } from 'react'
import { ContextMenuSubRootProps } from '../types'
import { ContextMenuSubContext } from '../context/subContext'

export const SubRoot = ({
  isOpen: controlledOpen,
  isDefaultOpen = false,
  onOpenChange,
  children
}: ContextMenuSubRootProps) => {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(isDefaultOpen)
  const triggerRef = useRef<HTMLElement | null>(null)
  const contentRef = useRef<HTMLDivElement | null>(null)

  const isControlled = controlledOpen !== undefined
  const isOpen = isControlled ? controlledOpen : uncontrolledOpen

  const handleOpenChange = useCallback(
    (isOpen: boolean) => {
      if (!isControlled) setUncontrolledOpen(isOpen)
      onOpenChange?.(isOpen)
    },
    [isControlled, onOpenChange]
  )

  const contextValue = useMemo(
    () => ({
      isOpen,
      triggerRef,
      contentRef,
      onOpenChange: handleOpenChange
    }),
    [isOpen, handleOpenChange]
  )

  return (
    <ContextMenuSubContext.Provider value={contextValue}>{children}</ContextMenuSubContext.Provider>
  )
}

import { useCallback, useEffect, useLayoutEffect, useState } from 'react'
import { useContextMenuContext } from '../context/context'
import { useContextMenuSubContext } from '../context/subContext'
import { useRovingFocus } from '../hooks/useRovingFocus'
import { ContextMenuSubContentProps } from '../types'
import { Portal } from '../../Portal'
import { content as contentStyle } from '../contextMenu.css'
import clsx from 'clsx'

export const SubContent = ({
  isLoop = true,
  sideOffset = 0,
  alignOffset = 0,
  style,
  className,
  children,
  onEscapeKeyDown
}: ContextMenuSubContentProps) => {
  const [position, setPosition] = useState<{ top: number; left: number } | null>(null)
  const { isOpen, contentRef, triggerRef, onOpenChange } = useContextMenuSubContext()
  const { onClose: onCloseRoot } = useContextMenuContext()

  const {
    highlightNext,
    highlightPrev,
    highlightFirst,
    highlightLast,
    highlightByElement,
    clearHighlight,
    highlightedRef
  } = useRovingFocus({ containerRef: contentRef, isLoop })

  useLayoutEffect(() => {
    if (!isOpen || !contentRef.current || !triggerRef.current) return

    const content = contentRef.current
    const trigger = triggerRef.current

    const rafId = requestAnimationFrame(() => {
      const triggerRect = trigger.getBoundingClientRect()
      const contentRect = content.getBoundingClientRect()

      let left = triggerRect.right + sideOffset
      if (left + contentRect.width > window.innerWidth) {
        left = triggerRect.left - contentRect.width - sideOffset
      }
      if (left < 0) {
        left = triggerRect.right + sideOffset
      }

      let top = triggerRect.top + alignOffset
      if (top + contentRect.height > window.innerHeight) {
        top = Math.max(0, window.innerHeight - contentRect.height)
      }

      setPosition({ top, left })
    })

    return () => cancelAnimationFrame(rafId)
  }, [isOpen, sideOffset, alignOffset, contentRef, triggerRef])

  const activateHighlighted = useCallback(() => {
    if (highlightedRef.current) {
      highlightedRef.current.click()
    }
  }, [highlightedRef])

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault()
          highlightNext()
          break
        case 'ArrowUp':
          e.preventDefault()
          highlightPrev()
          break
        case 'Home':
          e.preventDefault()
          highlightFirst()
          break
        case 'End':
          e.preventDefault()
          highlightLast()
          break
        case 'Enter':
        case ' ':
          e.preventDefault()
          activateHighlighted()
          break
        case 'ArrowLeft':
          e.preventDefault()
          e.stopPropagation()
          onOpenChange(false)
          triggerRef.current?.focus()
          break
        case 'Escape':
          e.preventDefault()
          onEscapeKeyDown?.(e.nativeEvent)
          onCloseRoot()
          break
        default:
          break
      }
    },
    [
      highlightNext,
      highlightPrev,
      highlightFirst,
      highlightLast,
      activateHighlighted,
      onOpenChange,
      onCloseRoot,
      onEscapeKeyDown,
      triggerRef
    ]
  )

  const handlePointerMove = useCallback(
    (e: React.PointerEvent) => {
      const target = (e.target as HTMLElement).closest(
        '[role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"]'
      ) as HTMLElement | null

      if (target && !target.hasAttribute('data-disabled')) {
        highlightByElement(target)
      }
    },
    [highlightByElement]
  )

  const handlePointerLeave = useCallback(
    (e: React.PointerEvent) => {
      clearHighlight()

      const relatedTarget = e.relatedTarget as HTMLElement | null

      if (relatedTarget && triggerRef.current?.contains(relatedTarget)) return
      onOpenChange(false)
    },
    [clearHighlight, onOpenChange, triggerRef]
  )

  useEffect(() => {
    if (isOpen && contentRef.current) {
      contentRef.current.focus()
    }
  }, [isOpen, contentRef])

  if (!isOpen) return null

  return (
    <Portal>
      <div
        ref={contentRef}
        role="menu"
        aria-orientation="vertical"
        data-state="open"
        tabIndex={-1}
        className={clsx(contentStyle, className)}
        style={{
          ...style,
          top: position?.top ?? 0,
          left: position?.left ?? 0,
          visibility: position ? 'visible' : 'hidden'
        }}
        onKeyDown={handleKeyDown}
        onPointerMove={handlePointerMove}
        onPointerLeave={handlePointerLeave}
      >
        {children}
      </div>
    </Portal>
  )
}

