import type { CreateTagRequest, Tag, UpdateTagRequest } from '../../../../shared/types'
import { queryKeys } from './queryKeys'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { TAG_CREATED, TAG_DELETED } from '@illog/analytics'

export const useAllTags = () => {
  return useQuery({
    queryKey: queryKeys.tags.all,
    queryFn: () => window.api.tag.getAll()
  })
}

export const useTag = (id: string) => {
  return useQuery({
    queryKey: queryKeys.tags.detail(id),
    queryFn: () => window.api.tag.get(id),
    enabled: !!id
  })
}

export const useCreateTag = () => {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (tag: CreateTagRequest) => {
      const newTag = await window.api.tag.create(tag)
      return newTag
    },
    meta: { errorMessage: 'Failed to create tag', successMessage: 'Tag created' },
    onSuccess: (newTag) => {
      queryClient.setQueryData<Tag[]>(queryKeys.tags.all, (old) => {
        if (!old) return [newTag]

        const exists = old.find((t) => t.id === newTag.id)
        if (exists) {
          return old.map((t) => (t.id === newTag.id ? newTag : t))
        }

        return [...old, newTag]
      })

      queryClient.setQueryData(queryKeys.tags.detail(newTag.id), newTag)
      window.api?.analytics?.track(TAG_CREATED)
    },
    onError: () => {
      // Global MutationCache onError handles toast display
    }
  })
}

export const useUpdateTag = () => {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async ({ id, data }: { id: string; data: UpdateTagRequest }) => {
      const updatedTag = await window.api.tag.update(id, data)
      return updatedTag
    },
    meta: { errorMessage: 'Failed to update tag' },
    onMutate: async ({ id, data }) => {
      await queryClient.cancelQueries({ queryKey: queryKeys.tags.all })

      const previousTags = queryClient.getQueryData<Tag[]>(queryKeys.tags.all)

      queryClient.setQueryData<Tag[]>(queryKeys.tags.all, (old) =>
        old?.map((tag) => (tag.id === id ? { ...tag, ...data } : tag))
      )

      return { previousTags }
    },
    onSuccess: (updatedTag) => {
      queryClient.setQueryData<Tag[]>(queryKeys.tags.all, (old) =>
        old?.map((tag) => (tag.id === updatedTag.id ? updatedTag : tag))
      )
      queryClient.setQueryData(queryKeys.tags.detail(updatedTag.id), updatedTag)
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks.today() })
    },
    onError: (_err, _variables, context) => {
      if (context?.previousTags) {
        queryClient.setQueryData(queryKeys.tags.all, context.previousTags)
      }
    }
  })
}

export const useDeleteTag = () => {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: (id: string) => window.api.tag.softDelete(id),
    meta: { errorMessage: 'Failed to delete tag', successMessage: 'Tag deleted' },
    onMutate: async (id) => {
      await queryClient.cancelQueries({ queryKey: queryKeys.tags.all })

      const previousTags = queryClient.getQueryData<Tag[]>(queryKeys.tags.all)

      queryClient.setQueryData<Tag[]>(queryKeys.tags.all, (old) =>
        old?.filter((tag) => tag.id !== id)
      )

      return { previousTags }
    },
    onError: (_err, _variables, context) => {
      if (context?.previousTags) {
        queryClient.setQueryData(queryKeys.tags.all, context.previousTags)
      }
    },
    onSuccess: () => {
      window.api?.analytics?.track(TAG_DELETED)
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.tags.all })
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks.today() })
    }
  })
}

import type { CreateProjectRequest, Project, UpdateProjectRequest } from '../../../../shared/types'
import { queryKeys } from './queryKeys'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { PROJECT_CREATED, PROJECT_DELETED } from '@illog/analytics'

export const useAllProjects = () => {
  return useQuery({
    queryKey: queryKeys.projects.all,
    queryFn: () => window.api.project.getAll()
  })
}

export const useProject = (id: string) => {
  return useQuery({
    queryKey: queryKeys.projects.detail(id),
    queryFn: () => window.api.project.get(id),
    enabled: !!id
  })
}

export const useCreateProject = () => {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (project: CreateProjectRequest) => {
      const newProject = await window.api.project.create(project)
      return newProject
    },
    meta: { errorMessage: 'Failed to create project', successMessage: 'Project created' },
    onSuccess: (newProject) => {
      queryClient.setQueryData<Project[]>(queryKeys.projects.all, (old) => {
        if (!old) return [newProject]

        const exists = old.find((p) => p.id === newProject.id)
        if (exists) {
          return old.map((p) => (p.id === newProject.id ? newProject : p))
        }

        return [...old, newProject]
      })

      queryClient.setQueryData(queryKeys.projects.detail(newProject.id), newProject)
      window.api?.analytics?.track(PROJECT_CREATED)
    },
    onError: () => {
      // Global MutationCache onError handles toast display
    }
  })
}

export const useUpdateProject = () => {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async ({ id, data }: { id: string; data: UpdateProjectRequest }) => {
      const updatedProject = await window.api.project.update(id, data)
      return updatedProject
    },
    meta: { errorMessage: 'Failed to update project' },
    onMutate: async ({ id, data }) => {
      await queryClient.cancelQueries({ queryKey: queryKeys.projects.all })

      const previousProjects = queryClient.getQueryData<Project[]>(queryKeys.projects.all)

      queryClient.setQueryData<Project[]>(queryKeys.projects.all, (old) =>
        old?.map((project) => (project.id === id ? { ...project, ...data } : project))
      )

      return { previousProjects }
    },
    onSuccess: (updatedProject) => {
      queryClient.setQueryData<Project[]>(queryKeys.projects.all, (old) =>
        old?.map((project) => (project.id === updatedProject.id ? updatedProject : project))
      )
      queryClient.setQueryData(queryKeys.projects.detail(updatedProject.id), updatedProject)
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks.today() })
    },
    onError: (_err, _variables, context) => {
      if (context?.previousProjects) {
        queryClient.setQueryData(queryKeys.projects.all, context.previousProjects)
      }
    }
  })
}

export const useDeleteProject = () => {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: (id: string) => window.api.project.softDelete(id),
    meta: { errorMessage: 'Failed to delete project', successMessage: 'Project deleted' },
    onMutate: async (id) => {
      await queryClient.cancelQueries({ queryKey: queryKeys.projects.all })

      const previousProjects = queryClient.getQueryData<Project[]>(queryKeys.projects.all)

      queryClient.setQueryData<Project[]>(queryKeys.projects.all, (old) =>
        old?.filter((project) => project.id !== id)
      )

      return { previousProjects }
    },
    onError: (_err, _variables, context) => {
      if (context?.previousProjects) {
        queryClient.setQueryData(queryKeys.projects.all, context.previousProjects)
      }
    },
    onSuccess: () => {
      window.api?.analytics?.track(PROJECT_DELETED)
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.projects.all })
      queryClient.invalidateQueries({ queryKey: queryKeys.tasks.today() })
    }
  })
}

