export const Time = ({ task }: Props) => {
  const duration = getTaskDurationMinutes(task)
  const { mutate: updateTask } = useUpdateTask()

  const handleDateTimeChange = (value: { start: string | null; end: string | null }) => {
    if (!task) return

    updateTask({
      id: task.id,
      data: {
        startTime: value.start,
        endTime: value.end
