  useCreateTaskSubtype,
  useUpdateTaskSubtype,
  useDeleteTaskSubtype
} from '../../hooks/queries/useTaskSubtypeQueries'

const TaskTypeBadgeTrigger = ({ taskType }: { taskType: BadgeItem | null }) => {
