export const TaskTypeSection = ({ task }: { task: TaskWithTags }) => {
  const { data: taskTypesWithSubtypes = [] } = useAllTaskTypesWithSubtypes()
  const { mutateAsync: createTaskType } = useCreateTaskType()
  const { mutateAsync: updateTaskType } = useUpdateTaskType()
  const { mutateAsync: deleteTaskType } = useDeleteTaskType()
  const { mutateAsync: createTaskSubtype } = useCreateTaskSubtype()
  const { mutateAsync: updateTaskSubtype } = useUpdateTaskSubtype()
  const { mutateAsync: deleteTaskSubtype } = useDeleteTaskSubtype()
  const { mutateAsync: setTaskType } = useSetTaskTypeToTask()
  const { mutateAsync: setTaskSubtype } = useSetTaskSubtypeToTask()
  const { mutateAsync: clearTaskType } = useClearTaskTypeFromTask()

  const taskTypeList = useMemo(
    () =>
      taskTypesWithSubtypes.map((t) => ({
        id: t.id,
        name: t.name,
        color: t.color
      })) as BadgeItem[],
    [taskTypesWithSubtypes]
  )

  const selectedTaskType = useMemo(() => {
    if (!task.taskType) return null
    const found = taskTypesWithSubtypes.find((t) => t.id === task.taskType?.id)
    if (found) {
      return { id: found.id, name: found.name, color: found.color } as BadgeItem
    }
    return task.taskType as BadgeItem
  }, [task.taskType, taskTypesWithSubtypes])

  const selectedTaskSubtype = useMemo(() => {
    if (!task.taskSubtype) return null
    return {
      id: task.taskSubtype.id,
      name: task.taskSubtype.name,
      color: task.taskSubtype.color ?? 'gray'
    }
  }, [task.taskSubtype])

  const subtypeList = useMemo(() => {
    if (!task.taskType) return []
    const taskType = taskTypesWithSubtypes.find((t) => t.id === task.taskType?.id)
    if (!taskType) return []
    return (
      taskType.subtypes?.map((s) => ({
        id: s.id,
        name: s.name,
        color: s.color
      })) || []
    )
  }, [task.taskType, taskTypesWithSubtypes])

  const handleSelectTaskType = async (taskTypeId: string) => {
    await setTaskType({ taskId: task.id, taskTypeId })
  }

  const handleClearTaskType = async () => {
    await clearTaskType(task.id)
  }

  const handleCreateTaskType = async (data: Partial<OmittedBadgeItem>) => {
    if (!data.name) throw new Error('Task type name is required')
    const newTaskType = await createTaskType({
      name: data.name,
      color: data.color
    } as CreateTaskTypeRequest)
    return newTaskType.id
  }

  const handleUpdateTaskType = async (taskTypeId: string, data: Partial<OmittedBadgeItem>) => {
    await updateTaskType({ id: taskTypeId, data: data as UpdateTaskTypeRequest })
  }

  const handleDeleteTaskType = async (taskTypeId: string) => {
    await deleteTaskType(taskTypeId)
  }

  const handleSelectTaskSubtype = async (subtypeId: string) => {
    await setTaskSubtype({ taskId: task.id, taskSubtypeId: subtypeId })
  }

  const handleClearTaskSubtype = async () => {
    if (!task.taskType) return
    await setTaskType({ taskId: task.id, taskTypeId: task.taskType.id })
  }

  const handleCreateTaskSubtype = async (data: Partial<OmittedBadgeItem>) => {
    if (!data.name || !task.taskType) throw new Error('Subtype name and task type are required')
    const newSubtype = await createTaskSubtype({
      taskTypeId: task.taskType.id,
      name: data.name
    })
    return newSubtype.id
  }

  const handleUpdateTaskSubtype = async (subtypeId: string, data: Partial<OmittedBadgeItem>) => {
    if (!task.taskType) throw new Error('Task type is required')
    await updateTaskSubtype({
      id: subtypeId,
      taskTypeId: task.taskType.id,
      data: { name: data.name, color: data.color }
    })
  }

  const handleDeleteTaskSubtype = async (subtypeId: string) => {
    await deleteTaskSubtype(subtypeId)
  }

  return (
    <>
      <BadgeSelector.Root
        items={taskTypeList}
        selectedItem={selectedTaskType}
        onSelectItem={handleSelectTaskType}
        onClearItem={handleClearTaskType}
        onCreateItem={handleCreateTaskType}
        onDeleteItem={handleDeleteTaskType}
        onUpdateItem={handleUpdateTaskType}
      >
        <BadgeSelector.Trigger asChild>
          <TaskTypeBadgeTrigger taskType={selectedTaskType} />
        </BadgeSelector.Trigger>

        <BadgeSelector.Content>
          <BadgeSelector.Search placeholder="Search task types..." />
          <Divider />
          <BadgeSelector.List />
        </BadgeSelector.Content>
      </BadgeSelector.Root>

      {task.taskType && (
        <BadgeSelector.Root
          items={subtypeList}
          selectedItem={
            selectedTaskSubtype
              ? ({
                  id: selectedTaskSubtype.id,
                  name: selectedTaskSubtype.name,
                  color: selectedTaskSubtype.color as BadgeColor
                } as BadgeItem)
              : null
          }
          onSelectItem={handleSelectTaskSubtype}
          onClearItem={handleClearTaskSubtype}
          onCreateItem={handleCreateTaskSubtype}
          onDeleteItem={handleDeleteTaskSubtype}
          onUpdateItem={handleUpdateTaskSubtype}
        >
          <BadgeSelector.Trigger asChild>
            <TaskSubtypeBadgeTrigger taskSubtype={selectedTaskSubtype} />
          </BadgeSelector.Trigger>

          <BadgeSelector.Content>
            <BadgeSelector.Search placeholder="Search subtypes..." />
            <Divider />
            <BadgeSelector.List />
          </BadgeSelector.Content>
        </BadgeSelector.Root>
      )}
    </>
  )
}

import { useState, useCallback, useEffect } from 'react'
import { Box, Button, Icon, Inline, Stack, Text, Input, useDebouncedCallback } from '@illog/ui'
import {
  useWeeklyReflection,
  useUpdateWeeklyReflection
} from '../../hooks/queries/useWeeklyReflectionQueries'
import { useAllTags } from '../../hooks/queries/useTagQueries'
import type { AccomplishmentItem } from '../../../../shared/types'

type Props = {
  weekId: string
}

export const WeeklyReflection = ({ weekId }: Props) => {
  const { data: reflection } = useWeeklyReflection(weekId)
  const { data: allTags = [] } = useAllTags()
  const { mutate: updateReflection } = useUpdateWeeklyReflection()

  const [accomplishments, setAccomplishments] = useState<AccomplishmentItem[]>([])
  const [improvements, setImprovements] = useState<string[]>([])
  const [nextWeekFocus, setNextWeekFocus] = useState<string[]>([])

  const [newAccomplishment, setNewAccomplishment] = useState('')
  const [newImprovement, setNewImprovement] = useState('')

  useEffect(() => {
    if (reflection) {
      /* eslint-disable react-hooks/set-state-in-effect */
      setAccomplishments(reflection.accomplishments)
      setImprovements(reflection.improvements)
      setNextWeekFocus(reflection.nextWeekFocus)
      /* eslint-enable react-hooks/set-state-in-effect */
    }
  }, [reflection])

  const debouncedSave = useDebouncedCallback(
    (data: {
      accomplishments?: AccomplishmentItem[]
      improvements?: string[]
      nextWeekFocus?: string[]
    }) => {
      updateReflection({ weekId, data })
    },
    1000
  )

  const handleAddAccomplishment = useCallback(() => {
    if (!newAccomplishment.trim()) return
    const newItem: AccomplishmentItem = {
      id: crypto.randomUUID(),
      text: newAccomplishment.trim(),
      completed: false
    }
    const updated = [...accomplishments, newItem]
    setAccomplishments(updated)
    setNewAccomplishment('')
    debouncedSave({ accomplishments: updated })
  }, [newAccomplishment, accomplishments, debouncedSave])

  const handleToggleAccomplishment = useCallback(
    (id: string) => {
      const updated = accomplishments.map((item) =>
        item.id === id ? { ...item, completed: !item.completed } : item
      )
      setAccomplishments(updated)
      debouncedSave({ accomplishments: updated })
    },
    [accomplishments, debouncedSave]
  )

  const handleRemoveAccomplishment = useCallback(
    (id: string) => {
      const updated = accomplishments.filter((item) => item.id !== id)
      setAccomplishments(updated)
      debouncedSave({ accomplishments: updated })
    },
    [accomplishments, debouncedSave]
  )

  const handleAddImprovement = useCallback(() => {
    if (!newImprovement.trim()) return
    const updated = [...improvements, newImprovement.trim()]
    setImprovements(updated)
    setNewImprovement('')
    debouncedSave({ improvements: updated })
  }, [newImprovement, improvements, debouncedSave])

  const handleRemoveImprovement = useCallback(
    (index: number) => {
      const updated = improvements.filter((_, i) => i !== index)
      setImprovements(updated)
      debouncedSave({ improvements: updated })
    },
    [improvements, debouncedSave]
  )

  const handleToggleFocusTag = useCallback(
    (tagId: string) => {
      const updated = nextWeekFocus.includes(tagId)
        ? nextWeekFocus.filter((id) => id !== tagId)
        : [...nextWeekFocus, tagId]
      setNextWeekFocus(updated)
      debouncedSave({ nextWeekFocus: updated })
    },
    [nextWeekFocus, debouncedSave]
  )

  return (
    <Stack gap="600">
      <Text textStyle="bodyStrong" color="textDefaultDefault">
        Weekly Reflection
      </Text>

      <Stack gap="300">
        <Text textStyle="bodyBase" color="textDefaultSecondary">
          Key Accomplishments
        </Text>
        <Stack gap="200">
          {accomplishments.map((item) => (
            <Inline key={item.id} gap="200" align="center" overflow="hidden">
              <input
                type="checkbox"
                checked={item.completed}
                onChange={() => handleToggleAccomplishment(item.id)}
                style={{ cursor: 'pointer', flexShrink: 0 }}
              />
              <Text
                textStyle="bodyBase"
                color={item.completed ? 'textDefaultTertiary' : 'textDefaultDefault'}
                style={{
                  textDecoration: item.completed ? 'line-through' : 'none',
                  flex: 1,
                  minWidth: 0
                }}
                lineClamp="2"
              >
                {item.text}
              </Text>
              <Box flexShrink={0}>
                <Button variant="secondary" onClick={() => handleRemoveAccomplishment(item.id)}>
                  <Icon name="cancel" size="small" />
                </Button>
              </Box>
            </Inline>
          ))}
          <Inline gap="200">
            <Input
              placeholder="Add accomplishment..."
              value={newAccomplishment}
              onChange={(e) => setNewAccomplishment(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAddAccomplishment()}
              style={{ flex: 1 }}
