          <TaskCard key={task.id} task={task} handleOpenNote={openTaskNote} />
        ))}
        {hiddenCount > 0 && !expanded && (
          <Button variant="secondary" onClick={() => setExpanded(true)}>
            +{hiddenCount} more tasks
