import { Button, Dialog, Stack, Text } from '@illog/ui'
import { useEffect, useState } from 'react'

interface UpdateInfo {
  releaseNotes?: string
  releaseName?: string
}

export function UpdateDialog() {
  const [updateInfo, setUpdateInfo] = useState<UpdateInfo | null>(null)
  const [isDownloaded, setIsDownloaded] = useState(false)

  useEffect(() => {
    const unsubscribeAvailable = window.api.events.onUpdateAvailable(() => {})

    const unsubscribeDownloaded = window.api.events.onUpdateDownloaded((info: UpdateInfo) => {
      setUpdateInfo(info)
      setIsDownloaded(true)
    })

    return () => {
      unsubscribeAvailable()
      unsubscribeDownloaded()
    }
  }, [])

  const handleUpdate = async () => {
    await window.api.updater.quitAndInstall()
  }

  const handleCancel = () => {
    setIsDownloaded(false)
    setUpdateInfo(null)
  }

  if (!isDownloaded) {
    return null
  }

  return (
    <Dialog isOpen={isDownloaded} onClose={handleCancel} ariaLabel="Update Available">
      <Dialog.Title>Update Available</Dialog.Title>
      <Dialog.Content>
        <Stack gap="400" textAlign="center">
          {updateInfo?.releaseName && (
            <Text as="p" textStyle="bodyBase" color="textBrandTertiary">
              {updateInfo.releaseName}
            </Text>
          )}
          <Text as="p" textStyle="bodyBase" color="textBrandTertiary">
            A new version has been downloaded. Would you like to update now?
          </Text>
          {updateInfo?.releaseNotes && (
            <Text as="p" textStyle="bodyBase" color="textBrandTertiary">
              <pre className="whitespace-pre-wrap">{updateInfo.releaseNotes}</pre>
            </Text>
          )}
        </Stack>
      </Dialog.Content>
      <Dialog.Footer>
        <Button variant="primary" onClick={handleUpdate} isFullWidth>
          Update Now
        </Button>
        <Button variant="secondary" onClick={handleCancel} isFullWidth>
          Later
        </Button>
      </Dialog.Footer>
    </Dialog>
  )
}

import { useMemo } from 'react'
import { addDays, startOfDay, isSameDay, format } from 'date-fns'
import type { TaskWithTags } from '../../../../shared/types'
import { getCalendarTasksForDate, getLayoutColumns, getTaskColor } from '../../utils/calendar'
import { Calendar, DEFAULT_HOUR_HEIGHT, DEFAULT_GUTTER_WIDTH, formatTimeLabel } from '@illog/ui'
import type { DayColumnHeader } from '@illog/ui'
import { CalendarTask } from '../../types/calendar'

const DAY_COUNT = 7
const HOUR_HEIGHT = DEFAULT_HOUR_HEIGHT
const GUTTER_WIDTH = DEFAULT_GUTTER_WIDTH

type Props = {
  tasks: TaskWithTags[]
  weekStart: string // ISO string of Monday
  onTaskClick: (taskId: string) => void
}

function buildDayTasks(tasks: TaskWithTags[], weekStartDate: Date): Map<number, CalendarTask[]> {
  const map = new Map<number, CalendarTask[]>()
  for (let i = 0; i < DAY_COUNT; i++) {
    const day = addDays(weekStartDate, i)
    map.set(i, getCalendarTasksForDate(tasks, day))
  }
  return map
}

export const WeeklyCalendarView = ({ tasks, weekStart, onTaskClick }: Props) => {
  const weekStartDate = useMemo(() => startOfDay(new Date(weekStart)), [weekStart])

  const dayTasks = useMemo(() => buildDayTasks(tasks, weekStartDate), [tasks, weekStartDate])
  const dayLayouts = useMemo(() => {
    const m = new Map<number, ReturnType<typeof getLayoutColumns>>()
    for (let i = 0; i < DAY_COUNT; i++) {
      m.set(i, getLayoutColumns(dayTasks.get(i)!))
    }
    return m
  }, [dayTasks])

  const todayColIndex = useMemo(() => {
    const today = startOfDay(new Date())
    for (let i = 0; i < DAY_COUNT; i++) {
      if (isSameDay(today, addDays(weekStartDate, i))) return i
    }
    return -1
  }, [weekStartDate])

  const dayHeaders: DayColumnHeader[] = useMemo(() => {
    return Array.from({ length: DAY_COUNT }, (_, i) => {
      const date = addDays(weekStartDate, i)
      return {
        label: format(date, 'EEE'),
        dateNum: format(date, 'd'),
        isToday: todayColIndex === i
      }
    })
  }, [weekStartDate, todayColIndex])

  return (
    <Calendar.TimeGrid
      columns={DAY_COUNT}
      hourHeight={HOUR_HEIGHT}
      gutterWidth={GUTTER_WIDTH}
      scrollHeight="calc(100vh - 200px)"
      showCurrentTime={false}
      currentTimeColumn={todayColIndex}
      header={<Calendar.DayColumnHeaders days={dayHeaders} gutterWidth={GUTTER_WIDTH} />}
      style={{ marginTop: 16 }}
    >
      {Array.from({ length: DAY_COUNT }, (_, dayIdx) => {
        const items = dayLayouts.get(dayIdx) ?? []
        return items.map(({ calendarTask, columnIndex, totalColumns }) => {
          const { task, startMinutes, durationMinutes } = calendarTask
          const top = (startMinutes / 60) * HOUR_HEIGHT
          const height = Math.max((durationMinutes / 60) * HOUR_HEIGHT, 22)
          const colors = getTaskColor(task)

          const dayColLeftCalc = `(100% - ${GUTTER_WIDTH}px) / ${DAY_COUNT}`
          const dayColStartCalc = `${GUTTER_WIDTH}px + ${dayIdx} * ${dayColLeftCalc}`
          const subColWidth = `${dayColLeftCalc} / ${totalColumns}`
          const left = `calc(${dayColStartCalc} + ${columnIndex} * ${subColWidth} + 2px)`
          const width = `calc(${subColWidth} - 4px)`

          const subtitle =
            task.startTime && task.endTime
              ? `${formatTimeLabel(new Date(task.startTime))} – ${formatTimeLabel(new Date(task.endTime))}`
              : undefined

          return (
            <Calendar.TimeCell
              key={`${task.id}-day${dayIdx}`}
              id={task.id}
              title={task.title}
              subtitle={subtitle}
              color={colors}
              top={top}
              height={height}
              left={left}
              width={width}
              titleFontSize={11}
              subtitleFontSize={10}
              onClick={() => onTaskClick(task.id)}
              style={{ padding: '2px 4px' }}
            />
          )
        })
      })}
    </Calendar.TimeGrid>
  )
}

import {
  Calendar,
  DEFAULT_GUTTER_WIDTH,
  DEFAULT_HOUR_HEIGHT,
  getMinutesFromMidnight,
  Stack,
  Text
} from '@illog/ui'
import { TaskWithTags } from '../../types'
import { useMemo } from 'react'
import {
  getCalendarTasksForDate,
  getLayoutColumns,
  getTimeCellStyle,
  getTimeCellText
} from '../../utils/calendar'

const HOUR_HEIGHT = DEFAULT_HOUR_HEIGHT
const GUTTER_WIDTH = DEFAULT_GUTTER_WIDTH
const SCROLL_HEIGHT = 'calc(100vh - 160px)'

type Props = {
  tasks: TaskWithTags[]
  onTaskClick: (taskId: string) => void
}

export const CalendarView = ({ tasks, onTaskClick }: Props) => {
  const today = useMemo(() => new Date(), [])
  const calendarTasks = useMemo(() => getCalendarTasksForDate(tasks, today), [tasks, today])
  const layoutItems = useMemo(() => getLayoutColumns(calendarTasks), [calendarTasks])

  const nowMinutes = getMinutesFromMidnight(new Date())
  const nowTop = (nowMinutes / 60) * HOUR_HEIGHT
  const hasCalendarTasks = calendarTasks.length > 0

  return (
    <Calendar.TimeGrid
      columns={1}
      hourHeight={HOUR_HEIGHT}
      gutterWidth={GUTTER_WIDTH}
      scrollHeight={SCROLL_HEIGHT}
      showCurrentTime
      style={{ marginTop: 16 }}
    >
      {layoutItems.map(({ calendarTask, columnIndex, totalColumns }) => {
        const { task, startMinutes, durationMinutes } = calendarTask
        const { subtitle, caption } = getTimeCellText(task)
        const { top, height, left, width, colors } = getTimeCellStyle({
          startMinutes,
          durationMinutes,
          task,
          columnIndex,
          totalColumns,
          hourHeight: HOUR_HEIGHT,
          gutterWidth: GUTTER_WIDTH
        })

        return (
          <Calendar.TimeCell
            key={task.id}
            id={task.id}
            title={task.title}
            subtitle={subtitle}
            caption={caption}
            color={colors}
            top={top}
            height={height}
            left={left}
            width={width}
            onClick={() => onTaskClick(task.id)}
          />
        )
      })}

      {!hasCalendarTasks && (
        <Stack position="absolute" top={nowTop + 20} left={GUTTER_WIDTH} right={0} zIndex={1}>
          <Text textStyle="bodyBase" color="textDefaultTertiary">
            No time-tracked tasks for today. Add start & end times to see them here.
          </Text>
        </Stack>
      )}
    </Calendar.TimeGrid>
  )
}

