import { useEffect } from 'react'
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext'
import { $getSelection, $isRangeSelection, $isRootOrShadowRoot } from 'lexical'
import { $isListNode, ListNode } from '@lexical/list'
import { $isHeadingNode } from '@lexical/rich-text'
import { $isCodeNode } from '@lexical/code'
import { $findMatchingParent, $getNearestNodeOfType } from '@lexical/utils'

import { useToolbarStore } from '../../../context/ToolbarStoreContext'
import { blockTypeToBlockName } from '../../../stores/useEditorStore'

type BlockType = keyof typeof blockTypeToBlockName

export function ToolbarPlugin() {
  const [editor] = useLexicalComposerContext()
  const batchUpdateToolbarState = useToolbarStore((state) => state.batchUpdateToolbarState)

  useEffect(() => {
    return editor.registerUpdateListener(({ editorState }) => {
      editorState.read(() => {
        const selection = $getSelection()

        if (!$isRangeSelection(selection)) {
          return
        }

        const anchorNode = selection.anchor.getNode()
        let element =
          anchorNode.getKey() === 'root'
            ? anchorNode
            : $findMatchingParent(anchorNode, (e) => {
                const parent = e.getParent()
                return parent !== null && $isRootOrShadowRoot(parent)
              })

        if (element === null) {
          element = anchorNode.getTopLevelElementOrThrow()
        }

        let blockType: BlockType = 'paragraph'

        if ($isListNode(element)) {
          const parentList = $getNearestNodeOfType<ListNode>(anchorNode, ListNode)
          const type = parentList ? parentList.getListType() : element.getListType()

          if (type === 'bullet') {
            blockType = 'bullet'
          } else if (type === 'number') {
            blockType = 'number'
          } else if (type === 'check') {
            blockType = 'check'
          }
        } else if ($isHeadingNode(element)) {
          const tag = element.getTag()
          blockType = tag as BlockType
        } else if ($isCodeNode(element)) {
          blockType = 'code'
        } else {
          const type = element.getType()
          if (type === 'quote') {
            blockType = 'quote'
          } else {
            blockType = 'paragraph'
          }
        }

        batchUpdateToolbarState({
          blockType,
          isBold: selection.hasFormat('bold'),
          isCode: selection.hasFormat('code'),
          isItalic: selection.hasFormat('italic'),
          isStrikethrough: selection.hasFormat('strikethrough'),
          isSubscript: selection.hasFormat('subscript'),
          isSuperscript: selection.hasFormat('superscript'),
          isUnderline: selection.hasFormat('underline')
        })
      })
    })
  }, [editor, batchUpdateToolbarState])

  return null
}

import { useEffect, useRef } from 'react'
import { $createParagraphNode, $createTextNode, $getRoot } from 'lexical'
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext'

type InitialContentPluginProps = {
  content: string
}

export function InitialContentPlugin({ content }: InitialContentPluginProps) {
  const [editor] = useLexicalComposerContext()
  const isInitialized = useRef(false)

  useEffect(() => {
    if (!isInitialized.current && content) {
      editor.update(
        () => {
          const root = $getRoot()

          try {
            const parsedState = JSON.parse(content)
            if (parsedState.root) {
              const editorState = editor.parseEditorState(content)
              editor.setEditorState(editorState)
              isInitialized.current = true
              return
            }
          } catch {
            // TODO: Need to handle as plain text
          }

          root.clear()
          const lines = content.split('\n')
          lines.forEach((line) => {
            const paragraph = $createParagraphNode()
            if (line) {
              const textNode = $createTextNode(line)
              paragraph.append(textNode)
            }
            root.append(paragraph)
          })
        },
        { discrete: true }
      )
      isInitialized.current = true
    }
  }, [editor, content])

  return null
}

import { useCallback, useState } from 'react'
import { EditorState } from 'lexical'
import { OnChangePlugin } from '@lexical/react/LexicalOnChangePlugin'
import { useAutoSave } from '@illog/ui'

const AUTO_SAVE_DEBOUNCE_MS = 1000

type AutoSavePluginProps = {
  taskId: string
  saveNote: (data: { taskId: string; content: string; clientUpdatedAt: number }) => void
}

export function AutoSavePlugin({ taskId, saveNote }: AutoSavePluginProps) {
  const [editorContent, setEditorContent] = useState<string>('')

  const handleChange = useCallback((editorState: EditorState) => {
    const jsonString = JSON.stringify(editorState.toJSON())
    setEditorContent(jsonString)
  }, [])

  const handleSave = useCallback(
    (content: string) => {
      saveNote({
        taskId,
        content,
        clientUpdatedAt: Date.now()
      })
    },
    [taskId, saveNote]
  )

  useAutoSave(editorContent, handleSave, AUTO_SAVE_DEBOUNCE_MS)

  return <OnChangePlugin onChange={handleChange} />
}

import { useCallback } from 'react'
import { useShallow } from 'zustand/react/shallow'
import { CommandPayloadType, FORMAT_TEXT_COMMAND } from 'lexical'
import { useToolbarStore } from '../../../context/ToolbarStoreContext'
import { Icon, IconNameOptions, Inline } from '@illog/ui'
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext'

type FormatType = CommandPayloadType<typeof FORMAT_TEXT_COMMAND>

interface FormatButtonProps {
  type: FormatType
  iconName: (typeof IconNameOptions)[number]
  isActive: boolean
  onClick: () => void
}

const FormatButton = ({ type, iconName, isActive, onClick }: FormatButtonProps) => {
  return (
    <Inline
      as="button"
      type="button"
      onClick={onClick}
      className={`format-button`}
      aria-label={`Format text as ${type}`}
      aria-pressed={isActive}
      p="150"
      rounded="200"
      _hover={{ bg: 'backgroundDefaultDefaultHover' }}
      _active={{ bg: 'backgroundDefaultDefaultHover' }}
      isActive={isActive}
    >
      <Icon name={iconName}></Icon>
    </Inline>
  )
}

export const TextFormat = () => {
  const [editor] = useLexicalComposerContext()
  const { isBold, isCode, isItalic, isStrikethrough, isSubscript, isSuperscript, isUnderline } =
    useToolbarStore(
      useShallow((s) => ({
        isBold: s.isBold,
        isCode: s.isCode,
        isItalic: s.isItalic,
        isStrikethrough: s.isStrikethrough,
        isSubscript: s.isSubscript,
        isSuperscript: s.isSuperscript,
        isUnderline: s.isUnderline
      }))
    )

  const handleFormat = useCallback(
    (formatType: FormatType) => {
      editor.dispatchCommand(FORMAT_TEXT_COMMAND, formatType)
    },
    [editor]
  )

  if (!editor.isEditable()) {
    return null
  }

  return (
    <Inline gap="200">
      <FormatButton
        type="bold"
        iconName="bold"
        isActive={isBold}
        onClick={() => handleFormat('bold')}
      />
      <FormatButton
        type="code"
        iconName="code"
        isActive={isCode}
        onClick={() => handleFormat('code')}
      />
      <FormatButton
        type="italic"
        iconName="italic"
        isActive={isItalic}
        onClick={() => handleFormat('italic')}
      />
      <FormatButton
        type="strikethrough"
        iconName="strikethrough"
        isActive={isStrikethrough}
        onClick={() => handleFormat('strikethrough')}
      />
      <FormatButton
        type="subscript"
        iconName="subscript"
        isActive={isSubscript}
        onClick={() => handleFormat('subscript')}
      />
      <FormatButton
        type="superscript"
        iconName="superscript"
        isActive={isSuperscript}
        onClick={() => handleFormat('superscript')}
      />
      <FormatButton
        type="underline"
        iconName="underline"
        isActive={isUnderline}
        onClick={() => handleFormat('underline')}
      />
    </Inline>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import {
  $getSelection,
  $isRangeSelection,
  $isTextNode,
  $isParagraphNode,
  COMMAND_PRIORITY_LOW,
  SELECTION_CHANGE_COMMAND,
  getDOMSelection
} from 'lexical'
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext'
import { mergeRegister } from '@lexical/utils'

import { TextFormat } from './TextFormat'
import { Box, Portal } from '@illog/ui'
import {
  getDOMRangeRect,
  getSelectedNode,
  setFloatingElemPosition
} from '../../../utils/floating-format-position'

interface FloatingTextFormatProps {
  anchorElement: HTMLElement | null
}

export const FloatingTextFormat = ({ anchorElement }: FloatingTextFormatProps) => {
  const [editor] = useLexicalComposerContext()
  const floatingToolbarRef = useRef<HTMLDivElement | null>(null)
  const [isText, setIsText] = useState(false)

  const updateFloatingToolbar = useCallback(() => {
    editor.getEditorState().read(() => {
      const selection = $getSelection()
      const nativeSelection = getDOMSelection(editor._window)
      const rootElement = editor.getRootElement()
      const floatingToolbarElem = floatingToolbarRef.current

      // 1. Check the validity of the selection
      if (
        nativeSelection !== null &&
        (!$isRangeSelection(selection) ||
          rootElement === null ||
          !rootElement.contains(nativeSelection.anchorNode))
      ) {
        setIsText(false)
        return
      }

      if (!$isRangeSelection(selection)) {
        setIsText(false)
        return
      }

      // 2. Check the type of the selected node
      const node = getSelectedNode(selection)
      const isTextNode = $isTextNode(node) || $isParagraphNode(node)

      if (!isTextNode) {
        setIsText(false)
        return
      }

      // 3. Check for empty text selection
      const rawTextContent = selection.getTextContent().replace(/\n/g, '')
      if (selection.isCollapsed() || rawTextContent === '') {
        setIsText(false)
        return
      }

      // 4. All conditions met → Show toolbar and update position
      setIsText(true)

      // 5. Calculate toolbar position (execute in the next frame)
      if (floatingToolbarElem && nativeSelection && !nativeSelection.isCollapsed && anchorElement) {
        requestAnimationFrame(() => {
          const rangeRect = getDOMRangeRect(nativeSelection, rootElement!)
          setFloatingElemPosition(rangeRect, floatingToolbarElem, anchorElement)
        })
      }
    })
  }, [editor, anchorElement])

  useEffect(() => {
    document.addEventListener('selectionchange', updateFloatingToolbar)
    return () => {
      document.removeEventListener('selectionchange', updateFloatingToolbar)
    }
  }, [updateFloatingToolbar])

  useEffect(() => {
    return mergeRegister(
      editor.registerUpdateListener(() => {
        updateFloatingToolbar()
      }),
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        () => {
          updateFloatingToolbar()
          return false
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerRootListener(() => {
        if (editor.getRootElement() === null) {
          setIsText(false)
        }
      })
    )
  }, [editor, updateFloatingToolbar])

  if (!isText || !anchorElement) {
    return null
  }

  // TODO: Need to update UI
  return (
    <Portal container={anchorElement}>
      <Box
        ref={floatingToolbarRef}
        position="absolute"
        bg="backgroundDefaultDefault"
        rounded="100"
        p="100"
        top={0}
        left={0}
        opacity={0}
        willChange="transform"
        zIndex={1000}
        boxShadow="200"
      >
        <TextFormat />
      </Box>
    </Portal>
  )
}
